(2062,3,1,'ဒုတိယမွန်ဗျည်း။',null)
,(2063,3,4,'ခစားသည်။ အမှီပြုသည်။ မှီခိုသည်။ အားကိုးသည်။','“ဖေက်ကၠခမယိ မယိကြံ လောန်နူကၠ။” = “ကျားကိုကြောက်လို့ ရှင်ကြီးကိုး ရှင်ကြီးကျားထက်ဆိုး။”')
,(2064,3,1,'ညှပ်။','ခေၚပ်သၞေမ်တဲ = လက်သည်းညှပ်။')
,(2065,3,4,'၁။ ခစားသည်။ အစေအပါးခံသည်။ အလုပ်အကျွေးပြုသည်။ အမှုတော်ထမ်းသည်။','“သၟာတ္ၚဒယှ်ဂှ် သၟိက်ဂွံခစသၟိၚ်ရ။” = “ထိုလေးသမားအကျော်သည် ဘုရင်ကိုခစားလို၏။” (ဇ—၈ဝ။ အစွောံ။) (အခကြေးငွေယူ၍ မင်း၏အမှုတော်ကို ထမ်းရွက်လိုသည်ဟု ဆိုလိုသည်။)')
,(2065,3,4,'၁။ ခစားသည်။ အစေအပါးခံသည်။ အလုပ်အကျွေးပြုသည်။ အမှုတော်ထမ်းသည်။','၂။ ခစားသည်။ ဖူးမြင်သည်။ ဆည်းကပ်သည်။')
,(2065,3,4,'၁။ ခစားသည်။ အစေအပါးခံသည်။ အလုပ်အကျွေးပြုသည်။ အမှုတော်ထမ်းသည်။','“သေဋ္ဌဳတိုန်ခစသၟိၚ် ရိုဟ်ဒဒှ်တ္ၚဲရ။” = “သူဌေးသည် မင်းအား နေ့စဉ်တက်ရောက်ခစားသည် (ဝါ) ဖူးမြင်သည်။”')
,(2065,3,4,'၁။ ခစားသည်။ အစေအပါးခံသည်။ အလုပ်အကျွေးပြုသည်။ အမှုတော်ထမ်းသည်။','‘သဳကၠဳ’ (ကြိ) လည်းရှု။')
,(2065,3,4,'၁။ ခစားသည်။ အစေအပါးခံသည်။ အလုပ်အကျွေးပြုသည်။ အမှုတော်ထမ်းသည်။','“ခစရတ်ပိပြကာလၟိုန်” = “ရတနာသုံးပါးကို အမြဲဆည်းကပ်သည်။”')
,(2065,3,4,'၁။ ခစားသည်။ အစေအပါးခံသည်။ အလုပ်အကျွေးပြုသည်။ အမှုတော်ထမ်းသည်။','၃။ (ရန်ဖြစ်ထားကြ၍ အချင်းချင်းစကားမပြောဘဲ မဆက်ဆံကြဘဲနေရာမှ) စကားအလျင်စပြောသည်။')
,(2066,3,1,'ကစွယ်ပင်၊ ကစွယ်သား။',null)
,(2067,3,1,'အိမ်မြှောင်။',null)
,(2068,3,1,'သဘာဝအလျောက် သေသောအိမ်မြှောင်။',null)
,(2069,3,1,'ငြောင့်။ ၚုတ်ချွန်။',null)
,(2070,3,4,'တိုင်တောသည်။ တို့မီးရှို့မီးလုပ်သည်။',null)
,(2071,3,1,'ဆူးငြောင့်ခလုတ်။',null)
,(2072,3,4,'တို့မီးရှို့မီးလုပ်သည်။ ကုန်းချောသည်။ ကုန်းတိုက်သည်။',null)
,(2073,3,4,'မီးရှို့သည်။',null)
,(2074,3,4,'စပ်စုသည်။',null)
,(2075,3,4,'စုတွဲသည်။ ပြွတ်သိပ်သည်။','(စည်း) အတွဲ၊ အပြွတ်စသည်ကို ရေတွက် ရာတွင် သုံးသောစကားလုံး။')
,(2075,3,4,'စုတွဲသည်။ ပြွတ်သိပ်သည်။','ကြုက်မွဲခစိုက် = သရက်သီးတစ်တွဲ။')
,(2076,3,4,'မမြင်မကန်းလုပ်သည်။ စမ်းတဝါးဝါးဖြစ်သည်။','ခစုၚ်ကၠောန် = စမ်းတဝါးဝါး နှင့်လုပ်သည်။')
,(2076,3,4,'မမြင်မကန်းလုပ်သည်။ စမ်းတဝါးဝါးဖြစ်သည်။','ခစုၚ်ကွာ် = စမ်းတဝါးဝါးလျှောက်သည်။')
,(2077,3,4,'စောင်းသည်။ တစ်ဖက်စောင်းသည်။',null)
,(2078,3,4,'ငုံ့သည်။','“ပ္ဍဲဂတမၞိဟ်ဇမၞော် ကွာ်ဂစိုၚ်အာညိ။” = “လူကြီးရှေ့တွင် ငုံ့၍လျှောက်ပါ။”')
,(2079,3,4,'ခေါင်းငုံ့သည်။',null)
,(2080,3,1,'ပြွတ်။','(ကြိ) ပက်ဖျန်းသည်။ ပန်းထွက်သည်။')
,(2081,3,1,'လေထိုးပြွတ်။ လေထိုးတံ။',null)
,(2082,3,1,'ရေပြွတ်။',null)
,(2083,3,4,'ကမန်းကတန်းပြုသည်။ ရေးကြီးသုတ်ပျာပြုသည်။ ကမျောသောပါးပြုသည်။','ခစာတ်ကၠုၚ် = ရေးကြီးသုတ်ပျာနှင့်လာသည်။ ပျာပျာသလဲနှင့်လာသည်။')
,(2084,3,4,'စုတ်သတ်သည်။',null)
,(2085,3,1,'ဟင်းခတ်စရာ။',null)
,(2086,3,4,'၁။ ရုန်းသည်။ ရုန်းကန်သည်။','၂။ ကြိုးစားသည်။ အားထုတ်သည်။ လုံ့ လပြုသည်။')
,(2086,3,4,'၁။ ရုန်းသည်။ ရုန်းကန်သည်။','ခစာန်ကၠောန် = အားစိုက်လုပ်ကိုင်သည်။')
,(2087,3,1,'ချဉ်ပေါၚ်။','ခစေပ်ဇုက်၊ ဂစေပ်ဇုက် = လျှော်ချဉ်ပေါၚ်။')
,(2088,3,4,'ပလုတ်ပလောင်းစားသည်။',null)
,(2089,3,1,'၁။ ကောက်စိုက်စူး၊ ဆေးထိုးစုတ်တံ။','၂။ ခစိုမ်စပုၚ် = ထမင်းစားသောခက်ရင်း။')
,(2090,3,1,'အကြေး။','ခစေဟ်က = ငါးအကြေး။')
,(2090,3,1,'အကြေး။','(ကြိ) ခြစ်ထုတ်သည်၊ ခွါထုတ်သည်။')
,(2090,3,1,'အကြေး။','ခစေဟ်ချောဲ = မြက်များကို (ပေါက်တူးဖြင့်) ပေါက်ထုတ်ပစ်သည်။')
,(2090,3,1,'အကြေး။','ခစေဟ်က = ငါးအကြေးသင်သည်။')
,(2091,3,1,'ပေါင်ဒါမှုန့်။','ဂစေအ်စၠန် = အမွှေးနံ့သာမှုန့်၊ သနပ်ခါးမှုန့်။')
,(2092,3,1,'ကြစုသီး။',null)
,(2093,3,1,'သပေါ့ပင်။',null)
,(2094,3,4,'(လုံချည်၊ ထဘီစသည်) နိမ့်နိမ့်ဝတ်ထားသည်။','“ဗိုက်လဝ်ဂၠိက်ဂှ် ခဇေအ် စိုပ်ဒၟံၚ်တိရ။” = “လုံချည်ဝတ်ထားသည်မှာ နိမ့်လွန်း၍ မြေသို့ပင်ရောက်နေသည် (ဒယဉ့်တိုက် နေသည်)။”')
,(2094,3,4,'(လုံချည်၊ ထဘီစသည်) နိမ့်နိမ့်ဝတ်ထားသည်။','ခဇေအ်လဝ်ဂၠိက်၊ ဂဇေအ်လဝ်ဂၞိန် = လုံချည်၊ ထဘီကို ခပ်နိမ့်နိမ့်ဝတ်ထားသည်။')
,(2095,3,4,'ကာမစပ်ရှက်သည်။ ညှောင့်သည်။ ကိုယ်ကို ရှေ့တိုးနောက်ၚၚ်လှုပ်ရှားသည်။',null)
,(2096,3,4,'ဟိန်းဟောက်သည်။ မာကြောစွာပြောဆိုသည်။','“အယုက်ဗှ်ေဍောတ်နူအဲ ဏီ၊ ဗှ်ေလ္ပကၠုၚ်ခညက်ဒၟံၚ်ကဵုအဲ။” = “မင်းငါ့ထက်အသက်ငယ်တယ်၊ မင်းငါ့ကို ဟိန်းလား ဟောက်လား လာမလုပ်နေနဲ့။”')
,(2097,3,16,'‘ထညက်ထညောန်’ ရှု။',null)
,(2098,3,4,'ကြိမ်းမောင်းအော်ေငါက်သည်။',null)
,(2099,3,4,'တွန့်လိမ်ကြေမွသည်။',null)
,(2100,3,4,'(စပါးနှံစသည်) ငိုက်ကျသည်။ အောက်သို့စိုက်ကျသည်။','ခညံက်စှ်ေ = ငိုက်စိုက် ကျသည်။')
,(2101,3,4,'ကျုံ့သည်။ တွန့်ရှုံ့သည်။','“မၞိဟ်ဗျု မုက်ခညောတ်ဒၟံၚ်ရ။” = “လူအိုမျက်နှာ တွန့်ရှုံ့နေသည်။”')
,(2102,3,4,'(မျက်နှာ)ရှုံ့မဲ့သည်။ မျက်မှောင်ကြုတ်သည်။','“ဍေံစပၞဴ ပၞဴဖျးလောန် တုဲ မုက်ဍေံခညောန်ဒၟံၚ်ရ။” = “သူသံပုရာသီးစားစဉ် သံပုရာသီးချဉ်လွန်းသောကြောင့် သူ့ မျက်နှာရှု့ံမဲ့နေသည်။”')
,(2103,3,4,'(သွားဖုံးဖြင့်) ကြိတ်ဝါးသည်။',null)
,(2104,3,4,'တွန့်သည်။ တွန့်ခေါက်သည်။ တွန့်လိမ်သည်။',null)
,(2105,3,4,'ပြေသည်။ ပြန့်သည်။','‘မတ်စောက်သည်’ ၏ဆန့်ကျၚ်ဘက်။')
,(2105,3,4,'ပြေသည်။ ပြန့်သည်။','“ကၟဳဏအ်ခ္ဍာအာ ရ။” = “ဤခေါၚ်မိုးသည် (မမတ်စောက်ဘဲ) ပြေပြန့်လွန်းသည်။”')
,(2106,3,1,'နှပ်ချို (ဆေးဖက်ဝင်အပင်)',null)
,(2107,3,1,'ငှက်တော်။','ခ္ဍိဂြၚ်၊ ထဍိဂြၚ် = ငှက်တော်အမြီးနှစ်ခွ။')
,(2108,3,4,'‘ထဍဳ','ထဍဳလျတ်’ ရှု')
,(2109,3,1,'ဝါခေါၚ်လ။','‘သွန်’ ဟုလည်းခေါ်သည်။')
,(2110,3,3,'ခြေခွၚ်သော။ ဆွံ့သော။','ဇိုၚ်ခ္ဍဴ = ခြေခွၚ်သည်။ ခြေထော့နဲ့ဖြစ်သည်။')
,(2110,3,3,'ခြေခွၚ်သော။ ဆွံ့သော။','“(ချေံမ္ၚဵုသၟိၚ်ဂှ်) ဒဒှ်ဍေံမဒ္ဂေတ်ဗက်အာ ဂမာချေံခ္ဍဴတုဲ ဍေံမခ္ဍဴအာ ဗောဓိသတ်တီတုဲ—။” (ဇ— ၁၈၄။ အစွောံ။) = “မင်း၏မၚ်္ဂလာမြင်းသည် ခြေခွၚ်သောမြင်းထိန်းကို အတုလိုက်၍ ခြေခွၚ် သွားသောအဖြစ်ကို ဘုရားလောင်းသိ၍။”')
,(2110,3,3,'ခြေခွၚ်သော။ ဆွံ့သော။','“တြုံကုန်ခဍဴယုတ်မာတဴဂှ် ကဵုကၠောန်ၜိုတ်ကဵုကောန် ဗြဴသၟိၚ်ဂှ် နွံမွဲကီု။” (ဇ—၅၃၆။ အစွောံ။) = “မင်းသမီးကို လုပ်ကျွေးစေသော ခြေခွၚ်သော ယုတ်မာသော ကုန်းသောၚကုန်းတစ်ယောက်ရှိ၏။”')
,(2110,3,3,'ခြေခွၚ်သော။ ဆွံ့သော။','“(သေဋ္ဌဳမွဲ) ဣလိသဂးယၟု၊— နွံကဵုဒုဟ်တြုံ ဇိုၚ်ထဍဴ တဲလဍိုဟ် မတ်ဟွံသၟဟ်—။” (ဇ—၇၈။ အစွောံ။) = “ထိုဣလ္လိသသူဌေးသည် ယော ကျာ်းယုတ်တို့၏ အပြစ်နှင့်ပြည့်စုံ၏။ ခွၚ်သောခြေရှိ၏၊ ကောက်သောလက်ရှိ၏၊ စွေသောမျက်စိ ရှိ၏။” (ညောင်ကန်)')
,(2110,3,3,'ခြေခွၚ်သော။ ဆွံ့သော။','“ဗြဴမကြောအ်လောန် ဗမဴတှ်မ္ဂး ဇိုၚ်ကောန်ၚာ်ဂဍဴအာ။” (ဇ—တေမဳ။ အစွောံ။) = “ဆူဖြိုးလွန်းသောမိန်းမ နို့တိုက်လျှင် ကလေးခြေဆွံ့သွားလိမ့်မည်။”')
,(2111,3,4,'လုံးသည်။ ဝိုင်းသည်။ လုံးဝန်းသည်။',null)
,(2112,3,4,'အလွန်လုံးဝိုင်းသည်။ ဝိုင်းစက်သည်။','“မုက်ဖမ်ဂှ် ခ္ဍမ်ပက်ဒၟံၚ်ရ။” = “အိုးစည်၏မျက်နှာပြင်သည် ဝိုင်းစက်နေသည်။”')
,(2113,3,4,'ချောင်းဆိုးသည်။','ယဲခ္ဍက် = ချောင်းဆိုးရောဂါ။')
,(2113,3,4,'ချောင်းဆိုးသည်။','‘သ္ဍက်’ ဟုလည်း အရေး ရှိသည်။')
,(2114,3,4,'ချောင်းဟန့်သည်။ ချောင်းညံ့သည်။','“ပ္ဍဲကၠာဒတိုန်အရှိုန်ဂှ် ကျာ်တြဲပြာပ်အာ ဒတဴဒၟံၚ်ပ္ဍဲတရၚ်ဝစ္စကုဋဳဂှ်တုဲ ခ္ဍက်ကဟေမ်တိုန်ရ။ ရာဟုလလေဝ် ခ္ဍက်ကဟေမ် တိုန် အပ္ဍဲတေံကီုရ။ ‘ညးဂှ်ရော’ ကျာ်တြဲသၟာန်ရ။ ‘အဲဍိက်ရာဟုလရောၚ်အဴ’ ရာဟုလဂး။”(ဇ— ၁၆။ အစွောံ။)= “သဗ္ဗညုမြတ်စွာဘုရားသည် အရုဏ်မတက်မီလျှင် ဝစ္စကုဋီတံခါး­ရပ်၍ချောင်း ညံ့၏။ ရှင်ရာဟုလာသည်လည်း (အတွင်းမှ)ချောင်းညံ့၏။ ‘ဤသူကား အဘယ်သူနည်း’ ဟုမေး တော်မူ၏။ ‘ဘုန်းတော်ကြီးသောအရှင်ဘုရား၊ အကျွန်ုပ်ရာဟုလာပါတည်း’ ဟု ထွက်၍ရှိခိုး၏။” (ညောင်ကန်။) (ဝစ္စကုဋီ = အိမ်သာ)')
,(2115,3,4,'ချောင်းဟန့်သည်။ ချောင်းဆိုးသံပြုသည်။',null)
,(2116,3,1,'သလိပ်ကောင်းစွာမထွက်သော ချောင်းဆိုးနာ။ ချောင်းခြောက်။',null)
,(2117,3,1,'ချောင်းဆိုးသွေးပါ။ အဆုတ်နာ။',null)
,(2118,3,1,'ကျီးကန်း။ ကျီးငှက်။ (ပါဠိ—ကာက)','ခ္ဍာ်ဂြိုပ်၊ ခဍာ်ဗၞံၚ်၊ ခ္ဍာ်ရာံ(ခ္ဍာ်သၟိၚ်ရာံ) = ကျီးအ။ တောကျီးကန်း။ (ပါဠိ—ဒေါဏကာက)')
,(2118,3,1,'ကျီးကန်း။ ကျီးငှက်။ (ပါဠိ—ကာက)','‘ဂဍာ်’ ဟုလည်းကောင်း၊ ‘က္ဍာ်’ ဟုလည်း ကောင်း အရေးရှိသည်။')
,(2119,3,1,'ဆီမီးခွက်။ မီးအိမ်။','‘ထဍေက်’ ဟုလည်းရေးသည်။')
,(2120,3,1,'ငါးပူတင်း။','ခဍော်ကျာ = ငါးပူတင်းအသေးစားတစ်မျိုး။ (လေစီပေါင်းငါးပူ တင်း။)')
,(2120,3,1,'ငါးပူတင်း။','‘ထဍော်’ ဟုလည်းရေးသည်။')
,(2121,3,4,'၁။ တီးခေါက်သည်။ ထုသည်။','“ဍေံခ္ဍံက်စုတ်က္ဍိုပ်အဲရ။” = “ငါ့ခေါင်းကို သူခေါက်ထည့်လိုက်သည်။”')
,(2121,3,4,'၁။ တီးခေါက်သည်။ ထုသည်။','ခ္ဍံက်ကဵုလေံဍံက် = တူနှင့်ထုသည်။')
,(2121,3,4,'၁။ တီးခေါက်သည်။ ထုသည်။','၂။ စာဖတ်သည်။ စာအံသည်။ စာလုံးပေါင်းပြီး ရွတ်ဆိုသည်။')
,(2121,3,4,'၁။ တီးခေါက်သည်။ ထုသည်။','‘ထဍံက်’ ဟုလည်းရေးသည်။')
,(2122,3,4,'(မကျေနပ်၍) တောက်ခေါက်သည်။',null)
,(2123,3,4,'စားလုံးပေါင်းရွတ်ဆိုသည်။ စာအံသည်။ စာရွတ်ဖတ်သည်။',null)
,(2124,3,4,'စျေးမြှင့်သည်။ စျေးတၚ်သည်။','ခ္ဍၚ်ပ္တိုန်ၚုဟ်ဗၞိက် = ကုန်စျေးနှုန်းမြှင့်တၚ်သည်။')
,(2124,3,4,'စျေးမြှင့်သည်။ စျေးတၚ်သည်။','(ကြိဝိ) သာ၍။ ပို၍။')
,(2124,3,4,'စျေးမြှင့်သည်။ စျေးတၚ်သည်။','“သီုဗှ်ေအာကီုမ္ဂး ခိုဟ်က္ဍၚ်ရ။” = “နၚ်ပါသွားလျှင် ပို၍ကောင်းသည်။”')
,(2124,3,4,'စျေးမြှင့်သည်။ စျေးတၚ်သည်။','‘က္ဍၚ်’ ဟုလည်းရေးသည်။')
,(2125,3,4,'စျေးနှုန်းမြှင့်သည်။ စျေးနှုန်းတၚ်သည်။',null)
,(2126,3,1,'သစ်ကြံပိုး။',null)
,(2127,3,1,'ၚဖုံးဆေး။ (ဆေးဖက်ဝင်အပင်)',null)
,(2128,3,1,'ကြက်ခြေခတ်ပုံ။ ထောင့်ဖြတ်ပုံသဏူဌာန်။','ခ္ဍာၚ်န = တောင်း၏အောက်ခြေရှိ ထောင့်ဖြတ်ကြက်ခြေခတ်ပုံ တပ်ဆင်ထားသော ဝါးချွန်ငယ်နှစ်ချောင်း။')
,(2129,3,4,'ခလုတ်တိုက်သည်။','ခ္ဍိၚ်ဒးဓဂဵုဆု၊ ထဍိၚ်ဒးဓဂဵုဆု = သစ်ၚုတ်ကို ခလုတ်တိုက်မိသည်။')
,(2129,3,4,'ခလုတ်တိုက်သည်။','‘ထဍိၚ်’ ဟုလည်းရေးသည်။')
,(2130,3,4,'လိုက်သည်။ နောက်မှ မှီအောင်လိုက်သည်။','ခ္ဍေၚ်ဗက် = ပြေးလိုက်သည်။')
,(2130,3,4,'လိုက်သည်။ နောက်မှ မှီအောင်လိုက်သည်။','ခ္ဍေၚ်ရပ် = လိုက်ဖမ်းသည်။')
,(2130,3,4,'လိုက်သည်။ နောက်မှ မှီအောင်လိုက်သည်။','ခ္ဍေၚ်တက် = လိုက်ရိုက်သည်။')
,(2130,3,4,'လိုက်သည်။ နောက်မှ မှီအောင်လိုက်သည်။','‘ထဍေၚ်’ ဟုလည်းရေးသည်။')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်ဍုၚ်လီု = မြို့ပျက်ခရမ်း။')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်ဇိုၚ်ကၠဵု = မြေပုံခ ရမ်း။ (ဆေးဖက်ဝင်အပင်)')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်ဂလာ = မြို့ပျက်ခရမ်း။ ခရမ်းကဇော့။')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်တာ = ဆင်ခရမ်း (ခရမ်းသီးအကြီးစားတစ်မျိုး)။')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်ပရောမ် = ခရမ်းကြွပ်သီး။')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်အိက်ကၞိ = မြို့ပျက်ခရမ်း။ ခရမ်းကဇော့။')
,(2131,3,1,'ခရမ်းသီး။','ခ္ဍောၚ်မတ်စာၚ် = ကြက်မျက်စေ့ခရမ်း။ (ဆေးဖက်ဝင်)')
,(2132,3,1,'လည်ချောင်း။',null)
,(2133,3,1,'ခရမ်းကစော့။ (ပင်စောက်ကြီးတစ်မျိုး။ ရှေးခေတ်ဘုရင်များက အိုး စည်ပြုလုပ်ရာတွင် သုံးသည်။)','ဖမ်ခ္ဍောၚ်ကၞိ = ဤအပင်၏အသားဖြင့်လုပ်ထားသော ရန်သူကိုအောင်နိုင်သည်ဆိုသောအိုးစည်။')
,(2134,3,4,'ခရမ်းချဉ်သီး။',null)
,(2135,3,1,'၁။ မျက်လုံး။ မျက်စိ။','၂။ (ဥပစာ) မျက်ရှု။')
,(2135,3,1,'၁။ မျက်လုံး။ မျက်စိ။','ကောန်ဖျုန်ဂြိုဟ် ခ္ဍောၚ်မတ် = ရင်သွေးမျက်ရှုသားသမီး။')
,(2136,3,1,'နံငယ်။ ရေလဲ။','ခ္ဍံၚ်ဟုံဍာ် = ရေချိုးရာတွင်ဝတ်သောနံငယ်။')
,(2137,3,4,'၁။ (ရေ)ပန်းထွက်သည်။','ခ္ဍိုၚ်ဏမ် = သေးပန်းထုတ်သည်။')
,(2137,3,4,'၁။ (ရေ)ပန်းထွက်သည်။','၂။ လွင့်စဉ်စေသည်။ လွင့်တက်စေသည်။')
,(2137,3,4,'၁။ (ရေ)ပန်းထွက်သည်။','ခ္ဍိုၚ်ပ္တိုန် = လွင့်အောင်ပစ်တၚ်သည်။')
,(2137,3,4,'၁။ (ရေ)ပန်းထွက်သည်။','‘က္ဍိုၚ်—၂’ (ကြိ) လည်းရှု။')
,(2138,3,1,'မြောက်ပန်းလှန်သည်။',null)
,(2139,3,1,'အနာအဖု။ အဖုအပိန့်။','‘သဍတ်’ လည်းရှု။')
,(2139,3,1,'အနာအဖု။ အဖုအပိန့်။','(ကြိ) (ကြက်ဥဘဲဥစသည်) သားပေါက်လာအောင်ဖောက်သည်။ ဥပေါက်သည်။')
,(2139,3,1,'အနာအဖု။ အဖုအပိန့်။','ခ္ဍတ်စာၚ် = သားပေါက်လာအောင် ကြက် သားဖောက်သည်။')
,(2139,3,1,'အနာအဖု။ အဖုအပိန့်။','‘က္ဍတ်’ (ကြိ) လည်းရှု။')
,(2140,3,4,'လက်ဖျောက်တီးသည်။ လက်ဖျစ်တီးသည်။','“(လၟ)အာဂၠာဲနၚ်မြာ်ဗြဴမွဲတုဲ ပ္ကေၚ်ပ္ကတ် ခ္ဍတ်တဲတုဲ ကဵုမြာ်ဗြဴဂြဴရ။” (ဇ—၁၅၉။ အစွောံ။) = “မုဆိုးသည် တစ်ခုသောဥဒေါင်းမကို ရှာယူလာပြီးလျှင် လက်ဖျစ်တီး၍ ဥဒေါင်းမ တွန်ရန် လေ့ကျင့်ပေး၏။”')
,(2140,3,4,'လက်ဖျောက်တီးသည်။ လက်ဖျစ်တီးသည်။','(န) လက်ဖျောက်တီး သံ။')
,(2140,3,4,'လက်ဖျောက်တီးသည်။ လက်ဖျစ်တီးသည်။','မွဲခ္ဍတ်တဲ = လက်တစ်ဖျောက်တီးအချိန်။')
,(2141,3,4,'လည်ပတ်စေသည်။ လှည့်လည်စေသည်။','ဝေၚ်ခ္ဍိတ်ကရောဲ = ကျၚ်လှည့်ကစားသည်။')
,(2142,3,4,'ကျီစယ်သည်။ ကျီးစားသည်။ စသည်။',null)
,(2143,3,4,'ကျီစားသည်။ ကျီစယ်သည်။',null)
,(2144,3,4,'နောက်ပြောင်သည်။ ပြောင်ချော်ချော်လုပ်သည်။',null)
,(2145,3,1,'အစေ့အဆန်။','“မသိၚ်ဃဵုဂှ် ပိုဲစခ္ဍန်ဍေံရ။” = “သီဟိုဠ်စေ့အဆန်ကို ငါတို့စား ကြ၏။”')
,(2145,3,1,'အစေ့အဆန်။','ဖ္ဍန်ခၟာဲစာၚ် = ကြက်ဥအဆန်။ ကြက်ဥအနှစ်။')
,(2146,3,4,'ကျဉ်းအောင်လုပ်သည်။ အကျဉ်းချုံးသည်။ ချုံ့သည်။','“လိက်ဍေံချူလဝ်ဂှ် ဒှ်မ သုန်မုက်လိက် ဂၠိၚ်လောန်အာတုဲ အ္စာကဵုဍေံခ္ဍန်ဖျေံကၠေံ ဗၞတ်ပိမုက်လိက်ရ။” = “သူရေးထား သောစာသည် ငါးမျက်နှာရှိရာ ရှည်လွန်းသဖြင့် သုံးမျက်နှာခန့်ဖြစ်အောင် ဆရာကသူ့ကို ချုံး ခိုင်းသည်။”')
,(2146,3,4,'ကျဉ်းအောင်လုပ်သည်။ အကျဉ်းချုံးသည်။ ချုံ့သည်။','“နအနုဘဴပါရမဳဗောဓိသတ်ဂှ် ဒေဝတဴတံခ္ဍန်ကၠေံတိတုဲ ပ္ဍဲတ္ၚဲဂှ်ဟေၚ် အာစိုပ်တမ်ဇိုၚ် အာစာရ။” (ဇ—၁၆၃။ အစွောံ။) = “ဘုရားလောင်း၏အာနုဘော်အားဖြင့် နတ်တို့၏မြေကိုချုံ့ ခြင်းကြောင့် တနေ့ခြင်းဖြင့်သာလျှင် (ဆရာ့ထံသို့ရောက်၏။)” (ညောင်ကန်)')
,(2146,3,4,'ကျဉ်းအောင်လုပ်သည်။ အကျဉ်းချုံးသည်။ ချုံ့သည်။','‘က္ဍန်’ (ကြိ) လည်းရှု။')
,(2147,3,1,'လင်ပန်း။ နှီးဗျပ်ငယ်။','ခ္ဍေန်ဒုၚ်ဒါန် = အလှူခံရန်လင်ပန်း။')
,(2148,3,4,'(တံတား၊ ဝါးလုံး၊ ကြိုးစသည်ပေါ်­) သတိနှင့်လျှောက်သည်။','ခ္ဍောန်ဇုက် = ကြိုးတန်းပေါ်တွင် သတိနှင့်လျှောက်သည်။')
,(2148,3,4,'(တံတား၊ ဝါးလုံး၊ ကြိုးစသည်ပေါ်­) သတိနှင့်လျှောက်သည်။','ခ္ဍောန်ဒဒန် = တံတားလျှောက်ကူးသည်။')
,(2149,3,4,'ဖြတ်ကူးသည်။ လျှောက်ကူးသည်။',null)
,(2150,3,4,'ခေါက်သည်။','ခ္ဍပ်စက္ခူ = စက္ကူခေါက်သည်။')
,(2151,3,1,'(ဝါး)လက်ခုပ်။ (တူရိယာ)','ခဍေဝ်ကဵုခဍာပ် = စည်းနှင့်ဝါး။')
,(2151,3,1,'(ဝါး)လက်ခုပ်။ (တူရိယာ)','(ကြိ) ကပ် ထည့်သည်။ စပ်ထည့်သည်။')
,(2151,3,1,'(ဝါး)လက်ခုပ်။ (တူရိယာ)','“တၞးစက္ခောသာ်ဍာဲဂှ် ခ္ဍာပ်စုတ် လတူတၞးစက္ခောသာ်ဗုဂှ်ညိ။” = “အနီရောၚ်စက္ကူရွက်ကို အဖြူရောၚ်စက္ကူရွက်ပေါ်တွင် ကပ်ထားလိုက်ပါ။”')
,(2152,3,4,'၁။ ကုပ်နေသည်။ ငြိမ်နေသည်။','“ကောန်ၚာ်ဂှ် ဒးတက်လဝ်တုဲ ခ္ဍေပ်ဒၟံၚ်ရ။” = “ထိုကလေးသည် ရိုက်ခံထိထား၍ ကုပ်နေသည်။”')
,(2152,3,4,'၁။ ကုပ်နေသည်။ ငြိမ်နေသည်။','“ဟိုတ်ဒုဟ်ဍေံနွံ ဍေံဒးခဍေပ်ဒၟံၚ်ရ။” = “သူ့မှာအပြစ်ရှိသောကြောင့် သူကုပ်နေရသည်။”')
,(2152,3,4,'၁။ ကုပ်နေသည်။ ငြိမ်နေသည်။','၂။ ညှပ်ယူသည်။')
,(2152,3,4,'၁။ ကုပ်နေသည်။ ငြိမ်နေသည်။','“(နကဵုဣဓိဘဒ္ဒဇိ ထေရ်ဂှ်) တၞုၚ်ဓုပ်ပြကာပြာသာဒ် (မၞုံဗၞတ်သမၠုၚ် ၜါဣသုန်ယောဇနာ)ဂှ် ခဍေပ်ကဵုၝောံဇိုၚ် က လာၚ်တိုန် လတူအကာသရ။” (ဇ—၂၆၄။ အစွောံ။) = “(ဘဒ္ဒဇိမထေရ်သည်) တန်ခိုးအစွမ်း ဖြင့်သွား၍ ပြာသာဒ်ထုပိကာကို ခြေချောင်းဖြင့်ညှပ်၍ နှစ်ဆဲ့ငါးယူဇနာရှိသော ပြာသာဒ်ကိုယူ၍ ကောင်းကင်သို့ပျံ၏။” (ညောင်ကန်)')
,(2153,3,4,'ဖွင့်ဖြန့်ထားရာမှ ပြန်၍ပိတ်သည်။ ခေါက်သွင်းသည်။ တွန့်ကျုံ့သွားသည်။','“ဗြဲဍးအာတုဲရ၊ ခ္ဍောပ်ထောံက္ဍိုၚ်ဂှ်ညိ။” = “မိုးစဲသွားပြီ၊ ထီးကို ပြန်ပိတ်လိုက်ပါ။”')
,(2153,3,4,'ဖွင့်ဖြန့်ထားရာမှ ပြန်၍ပိတ်သည်။ ခေါက်သွင်းသည်။ တွန့်ကျုံ့သွားသည်။','“ပ္ကဴ ရာၚ်မံၚ်ဂှ် ကလေၚ်ခဍောပ်အာရ။” = “ပွင့်နေသောပန်းသည် အပွင့်ပြန်ပိတ်သွားသည် (ပြန်ငုံ သွားသည်)။”')
,(2153,3,4,'ဖွင့်ဖြန့်ထားရာမှ ပြန်၍ပိတ်သည်။ ခေါက်သွင်းသည်။ တွန့်ကျုံ့သွားသည်။','“ဒွအ်ကျာဂမ္တဴကီု ဒးဓါတ်ဂမ္တဴတ္ၚဲကီုတုဲ ဇွစိၚ်ဂှ် သကှ်ဂဍောပ်အာရ။”= “လေပူ အတွေ့ကြောင့်၄င်း နေပူခြင်းကြောင့်၄င်း ဆင်သေကောင်သည် ခြောက်၍တွန့်ကျုံ့သွား၏။”')
,(2154,3,4,'၁။ ကွေးသည်။ ကွေးထားသည်။','“ဗြန်မွဲဂှ် ဍေံဂဍောပ် ကဝေန်လဝ်ဗတ။” (ဇ—၅၂၈။ အစွောံ။) = “တစ်ခုသောကျားသစ်သည် အမြီးကိုကွေးထားသည်။”')
,(2154,3,4,'၁။ ကွေးသည်။ ကွေးထားသည်။','၂။ (သဒ္ဓါတရား၊ စေတနာစသည်) လျော့ပါးပျက်ပြားသည်။ တွန့်တိုသည်။')
,(2154,3,4,'၁။ ကွေးသည်။ ကွေးထားသည်။','“အ ဃောမကဵုဒါန်ဂှ် ၜိုန်ရသဒ္ဓါစေတနာ ဍိုက်ပေၚ်ကီုလေဝ် ကာလကြဴနူကဵုဒါန်တုဲ စိုတ်ဓဝ်သဒ္ဓါစေ တနာ ခ္ဍောပ်ကဝေန်တဴမ္ဂး ဒါန်သာ်ဂှ် အနိဿံသဖဵုဟွံဇၞော်ရ။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ) = “အလှူဒါနပြုသောကာလ­ စေတနာသဒ္ဓါတရားနှင့် ပြည့်စုံသော်လည်း အလှူဒါနပေးပြီးနောက် ကာလ­ စေတနာသဒ္ဓါစိတ် ပြန်လည်လျော့ပါးတွန့်တိုပါက ထိုအလှူဒါနသည် အကျိုးအာနိသင် မကြီး။”')
,(2154,3,4,'၁။ ကွေးသည်။ ကွေးထားသည်။','၃။ တွန့်ဆုတ်သည်။ ဆုတ်နစ်သည်။')
,(2154,3,4,'၁။ ကွေးသည်။ ကွေးထားသည်။','‘မၞုံလွဳပရာမဇၞော် မဟွံမွဲကဵုခ္ဍောပ်ကဝေန်’ = ‘ဆုတ်နစ်ခြင်းမရှိသော လုံ့လဝီရိယရှိသည်။’')
,(2154,3,4,'၁။ ကွေးသည်။ ကွေးထားသည်။','‘မၞုံစိုတ်ဟွံခ္ဍောပ်ကဝေန် ပ္ဍဲမကတ်ကွတ်။’ = ‘အ တတ်သၚ်ခြင်း­ မတွန့်မဆုတ်သောစိတ်ရှိသည်။’')
,(2155,3,4,'မျက်နှာရှုံ့သည်။ မျက်မှောင်ကြုတ်သည်။','“(ကၞုဲကာလ ဗာဟုဂှ်) ဍေံကသဳကတောဝ်ကီု ဍေံခဍောပ်မုက်မတ်ဍေံကီု ဍေံပတုဲ ဍေံဗဟေက်ကောန်သၟိၚ်တံဂှ် ရ။” (ဇ—၃၂၉။ အစွောံ။) = “ကာဠဗာဟုမျောက်သည် နားကိုလှုပ်လှက်၏။ မျက်မှောင်ကြုတ် ခြင်းကို ပြု၏။ ရုတ်ချည်းရုတ်ချည်း မင်းသားငယ်တို့ကို လန့်စေ၏။” (ညောင်ကန်)')
,(2156,3,4,'၁။ ငိုက်ကျသည်။','၂။ ချိုးခေါက်သည်။')
,(2156,3,4,'၁။ ငိုက်ကျသည်။','“စက္ခောဂှ် ခ္ဍိုပ်ထောံၜါခ္ဍိုပ်ညိ။” = “စက္ကူကို နှစ်ခေါက်ချိုးခေါက်လိုက်ပါ။”')
,(2157,3,4,'ကလော်သည်။ ကော်သည်။ ဆွသည်။',null)
,(2158,3,1,'သံလွၚ်။ စည်း။ (တူရိယာပစ္စည်း။)','(ကြိ) ပြားသည်။')
,(2158,3,1,'သံလွၚ်။ စည်း။ (တူရိယာပစ္စည်း။)','(နဝိ) ပြားသော။')
,(2158,3,1,'သံလွၚ်။ စည်း။ (တူရိယာပစ္စည်း။)','ပ္ၚာန်ခဍေဝ် = ပန်းကန်ပြား။')
,(2159,3,1,'၁။ စည်းနှင့်ဝါးလက်ခုပ်။','၂။ ဝါးလက်ခုပ်သီး။ (အပင်)')
,(2160,3,4,'ကလော်သည်။ ကော်သည်။','“ဇြုံဇာတ်ဂှ် လ္ပခ္ဍဟ်ကဵုလေံညိ။” = “မြွေဟောက်ကို တုတ်နှင့်မကလော်ပါနှင့်။”')
,(2161,3,4,'စိတ်ဆိုးသည်။ အမျက်ထွက်သည်။ (?) (ပါဠိ—ရောသက)',null)
,(2162,3,4,'ချုပ်ချယ်သည်။ (?)',null)
,(2163,3,4,'သွားကြားထိုးသည်။',null)
,(2164,3,4,'ခေါက်သည်။ ထိပ်ခေါက်သည်။ ဦးခေါင်းခေါက်သည်။',null)
,(2165,3,4,'(ရေစစ်ဖြင့်) စစ်သည်။','“ဍာ်ဂှ် ခ္ဍိုဟ်တုဲသုၚ်ညိ။” = “ရေကို စစ်ပြီး သောက်ပါ။”')
,(2165,3,4,'(ရေစစ်ဖြင့်) စစ်သည်။','(န) = ရေစစ်။')
,(2165,3,4,'(ရေစစ်ဖြင့်) စစ်သည်။','‘သဍိုဟ်’ ဟုလည်းရေးသည်။')
,(2166,3,1,'၁။ အစ်။','ခ္ဍအ်ဇဗၠု = ကွမ်းအစ်။')
,(2166,3,1,'၁။ အစ်။','၂။ အခွံ။ (ဂဏန်းခွံ၊ ခရုခွံ၊ လိပ်ခွံစသည်)')
,(2166,3,1,'၁။ အစ်။','“ကၞုဟ်ဒတုံစှ်ေ ပ္ဍဲဒေါဝ်ပုရိသာတ်ဂမၠိုၚ်တုဲ ခဍအ်ကၞုဟ်ဂှ် ပြောပ်အာ—။” (ဇ—၂၁၅။ အစွောံ။) = “လိပ်သည် ပရိသတ်များအလယ်­ ပြုတ်ကျ၍ လိပ်ခွံသည် ကွဲကြေ၏။”')
,(2166,3,1,'၁။ အစ်။','“စိၚ် ဂမၠိုၚ် ဗိုၚ်ထနိက်လနိန်တုဲ ခဍအ်ဂတာံဂှ် ပြောပ်ပါ်အာတုဲ ဂတာံဂှ် ဒးပကာဂစိုတ်ရ။” (ဇ— ၂၆၇။ အစွောံ။) = “ဆင်များသည် ဝိုင်း၍ကန်ကျောက်နင်းပစ်ကြရာ ပုစွန်အခွံသည် ကွဲကြေ၍ ထိုပုစွန်သည် သေရလေ၏။”')
,(2166,3,1,'၁။ အစ်။','‘ထဍအ်’ ဟုလည်းရေးသည်။')
,(2167,3,1,'၁။ ခဏ။ တစ်ခဏ။ ချက်ချင်း။','၂။ (၄)နရနှင့်ညီသော အချိန်အတိုင်းအတာ။ (၁) နရ = (၁ဝ) မျက်တောင်ခတ်အကြာ အချိန်အပိုင်းအခြား။)')
,(2167,3,1,'၁။ ခဏ။ တစ်ခဏ။ ချက်ချင်း။','၃။ မီးတောက်မီးလျှံ။')
