,(2238,3,1,'၁။ အပြား။ အချပ်။','“သြန်စှ်ခတှ်ေဂှ် ပ္ဍဲခေတ် ကာလတ္ၚဲဏအ် ဟွံစကာရ။” = “ပိုက်ဆံဆယ်ပြားတန်ကို ယခုခေတ်တွင် မသုံးတော့ပါ။”')
