,(2238,3,1,'၁။ အပြား။ အချပ်။','ဍိုတ်ၜါ ခတှ်ေ = အုတ်နှစ်ချပ်။')
,(2238,3,1,'၁။ အပြား။ အချပ်။','ဂၠိက်မွဲခတှ်ေ၊ ဂၞိန်ၜါခတှ်ေ၊ ပလောအ်ပိခတှ်ေ = လုံချည်တစ်ထည်၊ ထဘီနှစ်ထည်၊ အင်္ကျီသုံးထည်။')
,(2239,3,4,'သစ်ပင်အမြစ်ရင်းမှဖြစ်စေ၊ ဖြတ်ထားသောသစ်ၚုတ်မှဖြစ်စေ အညွန့်အတက်ထွက်သည်။ (“ဗၠိုၚ်ခတိုဟ်” ဟူ၍သုံးသည်။)',null)
,(2240,3,1,'ငါးခုံတွင်း။ (ငါးဖမ်းနည်းတစ်မျိုး)',null)
,(2241,3,1,'ခပေါင်းနွယ်။ (ဆေးဖက်ဝင်အပင်)',null)
,(2242,3,4,'ထုသည်။ ထောင်းသည်။ ဆောင့်သည်။','ခဒုတိ = မြေကြီးကိုထုထောင်းသည်။')
,(2243,3,4,'ခြေဆောင့်သည်။',null)
,(2244,3,4,'ရၚ်ထုသည်။',null)
,(2245,3,4,'ရိုက်သည်။ ဆော်သည်။','“ကမၠတ်ဂှ် ညးရပ်ဂွံတုဲ ညးခဒဲကဵုလေံၜဝ် ဂၠိုၚ်ကဵုလ စုတ်ရ။” = “သူခိုးကို ဖမ်းမိပြီး ကြိမ်လုံးဖြင့် အချက်ပေါင်းများစွာ ရိုက်ဆော်ပေးလိုက်သည်။”')
,(2246,3,1,'အိမ်ရှိအခန်း။','“ကောန်ဗြဴသေဋ္ဌဳမွဲ —— တန်တဴဒၟံၚ် ပ္ဍဲဗဒမ်ကျာ်သြဳ ပ္ဍဲဂၠးလ တူပြာသာဒ်ထပှ်ဘုံတေံရ။” (သုဓမ္မဒေသနာ။ ပ—၁၃၉။ ဂရိုက်သာံ။) = “တစ်ယောက်သောသူ ဋ္ဌေးသမီးသည် ပြာသာဒ်ခုနစ်ဘုံအထက် ကျက်သရေတိုက်ခန်းထဲ­ နေ၏။”')
,(2247,3,1,'စတုတ်။ (စပါး၊ ဆန်စသည်တို့ကို ဇလား၊ တောင်း၊ တင်းတို့နှင့် ခြၚ်ရာတွင် ညှိရသောတုတ်တံ။)','ခဒုက်ဒုန် = ဝါးစတုတ်။')
,(2248,3,1,'နံရံ။ ထရံ။',null)
,(2249,3,1,'ဒုတိယတိုက်အုပ် (စာသၚ်တိုက်)။ လက်ထောက်တိုက်အုပ်။ လက်ထောက် ကျောင်းထိုၚ်။ သီတင်းကြီး။',null)
,(2250,3,1,'ပခုံး။',null)
,(2251,3,1,'၁။ အမြစ်ပျဉ်း။','ခဒါၚ်ဆု = သစ်ပင်အမြစ်ပျဉ်း။')
,(2251,3,1,'၁။ အမြစ်ပျဉ်း။','၂။ ဒိုင်းလွှားတစ်မျိုး။')
,(2252,3,1,'ကျောက်စွန်းပါးပျဉ်း။ ေငါထွက်နေသောကျောက်အစွန်း။',null)
,(2253,3,1,'အငူ။ အစွန်း။','ခဒုၚ်ကုန်၊ ဂဒုၚ်ကုန် = ကုန်းအငူ။ ကုန်းအစွန်း။')
,(2253,3,1,'အငူ။ အစွန်း။','ခဒုၚ်တၟအ်၊ ဂဒုၚ်တၟအ် = ကျောက်အငူ။ ကျောက်အစွန်း။')
,(2254,3,1,'ဒိုင်း။ လွှား၊ ကာ။',null)
,(2255,3,1,'ကတွတ်သီး။','ယိုဟ်ကဒေါတ် = ကတွတ်ယို။')
,(2256,3,1,'ကတိုး။ (အပင်)',null)
