,(2259,3,1,'၁။ (အရည်လောင်း) ကတော့။','၂။ အဖူး။ (ငှက်ပျောစသည်)')
,(2260,3,1,'ပညာအငုံအဖူး။ (တၚ်စားသုံးနှုန်းခြင်း။ ရူပကအလင်္ကာ။)','“ကာ လဂဒအ်ပညာဗောဓိသတ် ဟွံဂွံကြံၚ်ဍုဟ်ဏီ။” = “ဘုရားလောင်း၏ပညာအငုံအဖူး မရင့်ကျက် သေးမီကာလ။”')
,(2261,3,1,'၁။ (အပင်မှ)ငှက်ပျောဖူး။','၂။ ခြေသလုံး။')
,(2261,3,1,'၁။ (အပင်မှ)ငှက်ပျောဖူး။','၃။ ငှက်ပျောဖူး။ (စေတီထီးတော်အောက်ရှိ အစိတ်အပိုင်း)')
,(2262,3,1,'အငယ်ဆုံး။ အထွေးဆုံး။','ကောန်ခဒေအ်၊ ကောန်ဒဒေအ် = သားထွေးသ မီးထွေး။')
,(2263,3,1,'၁။ ကူးတို့။ ကူးတို့သမား။','၂။ နောက်ဖေးအိုး။ (ထၟာဲဂဒိုအ်)')
,(2264,3,1,'မီးဇာ။',null)
,(2265,3,1,'မီးဇာ။',null)
