,(2267,3,4,'၁။ ညက်အောင်ထောင်းသည်။','၂။ တံတောင်နှင့်တွက်သည်။ တံတောင်နှင့်ထောင်းသည်။')
,(2268,3,1,'အမှုန့်။','ခၞိက်မြေက် = ၚရုပ်သီးမှုန့်။')
,(2268,3,1,'အမှုန့်။','ခနိက်တိ = မြေမှုန့်။')
,(2268,3,1,'အမှုန့်။','ခနိက် ခပဵု = ထုံးမှုန့်။')
,(2268,3,1,'အမှုန့်။','ခနိက်ဂဥုဲ = ဆေးမှုန့်။')
,(2268,3,1,'အမှုန့်။','ခၞိက်ၜဲ = ပဲမှုန့်။')
,(2269,3,1,'ခြေတွင်ကပ်သောမြေမှုန့်။',null)
