,(2270,3,1,'၁။ ခလောက်။','၂။ ကုလားတက်။')
,(2270,3,1,'၁။ ခလောက်။','ခနုက်ကၚ် = ကင်းစောင့်ကုလားတက်။')
,(2270,3,1,'၁။ ခလောက်။','ၜုၚ်ခနုက် = ကုလားတက်တီးသည်။')
,(2271,3,1,'၁။ အခွံ။','‘သၞံက်’ ရှု။')
