,(2276,3,5,'နည်းနည်းချင်း။ ဖြည်းဖြည်းချင်း။','ခနေဟ်စ = နည်းနည်းချင်းစားသည်။ ဖြည်းဖြည်းချင်းစားသည်။')
,(2276,3,5,'နည်းနည်းချင်း။ ဖြည်းဖြည်းချင်း။','ခနေဟ်ဖျေံ = နည်းနည်းချင်းချသည်။ ဖြည်းဖြည်းချင်းချသည်။')
,(2277,3,1,'၁။ မီးတောက်မီးလျှံ။ (သၞပၟတ်)','၂။ (တောင်းစသည်၏) အကွပ်။')
,(2277,3,1,'၁။ မီးတောက်မီးလျှံ။ (သၞပၟတ်)','‘ခနှန’ = ‘တောင်းအကွပ်’')
,(2277,3,1,'၁။ မီးတောက်မီးလျှံ။ (သၞပၟတ်)','၃။ (ဝါး)အကြော။')
,(2277,3,1,'၁။ မီးတောက်မီးလျှံ။ (သၞပၟတ်)','ခနှဒုန် = ဝါးအကြော။ (ဝါးပင်၏အမာဆုံး အပေါ်ယံ အကြော။')
,(2278,3,4,'လင်းလက်သည်။ တောက်ပသည်။',null)
