,(2280,3,4,'၁။ (အမြင်)မှုန်ဝါးသည်။','၂။ (မျက်စိ)ကျိန်းသည်။')
,(2280,3,4,'၁။ (အမြင်)မှုန်ဝါးသည်။','မတ်ခပါ၊ မတ်သပါ = မျက်စိကျိန်းသည်။')
,(2280,3,4,'၁။ (အမြင်)မှုန်ဝါးသည်။','“ရံၚ်တ္ၚဲမ္ဂး မတ်ခပါရောၚ်။” = “နေကိုကြည့်လျှင် မျက်စိကျိန်းလိမ့် မည်။”')
,(2281,3,3,'မှုန်မှုန်ဝါးဝါးဖြစ်သော။','“ရံၚ်နူသ္ၚောဲသ္ၚောဲ ဂွံညာတ်ခပါခပါရ။” = “အ ဝေးမှကြည့်သော် မှုန်မှုန်ဝါးဝါးမြင်ရသည်။”')
,(2282,3,4,'နေရောၚ်ထိုး၍ မျက်စိကျိန်းစပ်သည်။',null)
,(2283,3,1,'ဖရုံသီး။ ကျောက်ဖရုံ။ (ပါဠိ—ကုမ္ဘဏ္ဍ)',null)
,(2284,3,1,'ရွှေဖရုံသီး။',null)
,(2285,3,1,'ကျောက်ဖရုံသီး။',null)
,(2286,3,1,'လွန်ပူ။ လွန်သွား။','(ကြိ) ၁။ လှည့်သွင်းသည်။ ထိုးသွင်းသည်။')
,(2286,3,1,'လွန်ပူ။ လွန်သွား။','ခပူကတောဝ် = နားကျပ်သည်။')
,(2286,3,1,'လွန်ပူ။ လွန်သွား။','၂။ လွန်ပူဖြင့်လှည့်သွင်းသည်။')
,(2286,3,1,'လွန်ပူ။ လွန်သွား။','“ဆုဂှ် ခပူပထောၚ်ထောံ နကဵုခပူညိ။” = “ထိုသစ်ကို လွန်ပူဖြင့် ဖောက်ထွင်းလိုက်ပါ။”')
