,(2287,3,4,'၁။ (ထမင်းစသည်) ပျော့သည်။','“ပုၚ်ဂွံခပေက်အာဂှ် ဍေံဍုန်ပုၚ်ဟွံ လေပ်ဟာ။” = “ထမင်းပျော့သွားရသည်မှာ သူထမင်းမချက်တတ်၍လား။”')
,(2287,3,4,'၁။ (ထမင်းစသည်) ပျော့သည်။','၂။ သူငယ်ပြန်သည်။')
,(2287,3,4,'၁။ (ထမင်းစသည်) ပျော့သည်။','“အပါနော်ပိုဲ ဂွံအယုက်ဒစာံစှ်ောပြင်ဂှ် ခပေက်ဒၟံၚ်ဣရ။” = “အသက်ရှစ်ဆယ်ကျော် သော ငါတို့အဘိုးသည် သူငယ်ပြန်နေပြီ။”')
