,(2293,3,1,'အသိုက်။ အသိုက်အမြုံ။','ခပေဲါဂစေံ = ငှက်သိုက်။')
,(2294,3,1,'ရောဂါဖြစ်တည်ရာ။ ရောဂါအသိုက်အမြုံ။','“ကာယမဟွံသ္အး မဒှ်ဂပေဲါယဲ မဒှ်ဗွဝ်ဇွ—။” (ဇ—၂၉၃။ အစွောံ။) = “ဤခန္ဓာသည်ကား မစင်ကြယ်၊ ရောဂါ၏ဖြစ်တည်ရာအ သိုက်အမြုံဖြစ်၍ အကောင်ပုပ်မျှသာတည်း။”')
,(2295,3,4,'ကွင်းရှောင်သည်။ ကွေ့ပတ်သည်။','ဂပဝ်အာ = ကွင်းရှောင်ပြီးသွားသည်။')
,(2296,3,1,'ကျူထရံ။ ကျူဖျာ။','တာန်ခပေဝ် = ကျူထရံရက်သည်။')
,(2297,3,1,'၁။ ထုံး။','၂။ တံပိုး။ (လေမှုတ်တူရိယာ)')
