,(2306,3,1,'၁။ အိမ်ခါးပန်း။','၂။ ရွာရိုး။ တာရိုး။')
,(2306,3,1,'၁။ အိမ်ခါးပန်း။','ခဗာန်ကွာန် = ရွာရိုး။')
,(2306,3,1,'၁။ အိမ်ခါးပန်း။','ခဗာန်ဝါ = ကွင်းတာရိုး။')
