,(2309,3,1,'နဖားကြိုး။ နဖားပေါက်။','စၚ်ခဗာဲ = နဖားထိုးသည်။')
,(2309,3,1,'နဖားကြိုး။ နဖားပေါက်။','သာတ်ခဗာဲ = နဖား ကြိုးချွတ်သည်။')
,(2310,3,1,'သစ်နဖားပေါက်။',null)
,(2311,3,1,'ဘန့်ဘွေးပင်။',null)
,(2312,3,1,'ကျစ်စာ။','ခဗိုဟ်ကၞိ = ကြွက်တွင်းကျစ်စာ။')
,(2312,3,1,'ကျစ်စာ။','ခဗိုဟ်ကြုတ်တိ = တီကောင်ကျစ်စာ။')
,(2312,3,1,'ကျစ်စာ။','(ကြိ) (ကြွက်၊ ပိုးကောင်စသည်) တွင်းတူးသည်။')
,(2313,3,1,'ခမည်း။ ခမည်းပေးသော လက်ဆောင်ပစ္စည်းဥစ္စာ။','ကဵုခမ = ခမည်းပေးသည်။ နာဖျားမကျန်းရှိနေသော ကလေးသူငယ်အတွက် ပစ္စည်းဥစ္စာတစ်ခုခုကို ပေးသည်။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','ခမဳပုထုဇန် = ပုထုဇဉ်ရဟန်း။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','ခမဳအရဳ = အရိယာ ရဟန်းသံဃာ။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','ခမဳသၚ် = ရဟန်းသံဃာ။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','ခမဳဣသိ = ရသေ့ရဟန်း။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','၂။ ပဥ္ဇင်းရဟန်းနှင့် သာမဏေများကိုပါ ခြုံ၍ခေါ်ဆိုသောအသုံးအနှုန်း။ (ပဥ္ဇင်းလည်းဖြစ်နိုင်သလို သာမဏေ')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','ကိုရၚ် လည်းဖြစ်နိုင်သည်။)')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','“ကုမာရကဿပ အာယုက်ဒှ်ထပှ်သၞာံဂှ် တိတ်ပကၠေံခမဳ ဇရေၚ်ကျာ်တြဲရ။ ပေၚ်အာယုက်ၜါစှ်ောသၞာံတုဲ ဂွံဒှ်ပယၚ်ရ။” (ဇ—၁၂။ အစွောံ။) = “ကုမာရကဿပသည် ခုနစ် နှစ်ရှိလတ်သောအခါ­ မြတ်စွာဘုရားအထံတော်ဝယ် သာမဏေပြု၍ အသက်နှစ်ဆယ်ပြည့်လတ် သော် ပဥ္ဇင်းအဖြစ်ကိုရ၍—။” (ညောင်ကန်)')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','(ကြိ) သာမဏေပြုပေးသည်။ ရဟန်းပြုပေးသည်။ ဘုန်းကြီးဝတ်ပေးသည်။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','“ယွံတဳလမၞုံပိုန်ကျာ်တြဲ၊ ခမဳကၠေံအဲဍိက်ညိရအဴ” သမ္ၚေဟ်ဂး—။ (ဇ—၁၇၁။ အစွောံ။) = “ဘုန်းတော်ကြီးတော်မူသော မြတ်စွာဘုရား၊ တပည့်တော်အား ရဟန်း ပြုပေးတော်မူပါဘုရား” သူကြွယ်ဆို၏။')
,(2314,3,1,'၁။ ရဟန်း။ ပဥ္ဇင်း။','“ခမဳဗျုဂှ်တုန် ခမဳကၠေံကောန်ၚာ်မွဲရ။ သာမဏဳဂှ် ကၠောန်ၜိုတ်ဥပ္ပကာခမဳဗျုဂှ် နကဵုဂဇေဟ်ဟေၚ်ရ။” (ဇ—၃၇၂။ အစွောံ။) = “ထိုရဟန်းကြီးသည် တစ်ယောက်သောသူငယ်ကို သာမဏေပြုသတတ်။ သာမဏေသည် ထိုရဟန်းကြီးကို ရိုသေစွာ လုပ်ကျွေး၍—။” (ညောင်ကန်)')
,(2315,3,4,'ကြောက်လန့်တုန်လှုပ်သည်။',null)
,(2316,3,4,'ထိတ်လန့်တုန်လှုပ်သည်။ ကြက်သီးမွေးညင်းထသည်။','“မိၚ်ဒးပရိုၚ်ဍေံဂှ် အဲခမုဇ ကုရ။” = “သူ့သတင်းကို ကြားရသည်မှာ ငါအလွန်ထိတ်လန့်တုန်လှုပ်သည်။”')
,(2317,3,1,'အလိပ်။','ခမူဒကဝ် = ဖျာလိပ်။')
,(2317,3,1,'အလိပ်။','(စည်း) အလိပ်စသည်ကို ရေတွက်ရာတွင် သုံးသော စကားလုံး။')
,(2317,3,1,'အလိပ်။','ဒကဝ်ၜါခမူ = ဖျာနှစ်လိပ်။')
,(2317,3,1,'အလိပ်။','(ကြိ) လိပ်သည်။')
,(2317,3,1,'အလိပ်။','ခမူၜံက် = ဆေးလိပ်လိပ်သည်။')
,(2318,3,1,'မျက်နှာပေါ်တွင်ဖြစ်ပေါ်သော ညိုမည်းသောအပြောက်။ တင်းတိပ်။',null)
,(2319,3,1,'(ကြက်ငှက်၊ ကျွဲနွား၊ ခွေးဝက်စသည်၏) နှုတ်သီး။',null)
