,(2327,3,1,'၁။ အခေါင်းပေါက်။','ကမှံက်’ ဟုလည်းရေးသည်။')
,(2327,3,1,'၁။ အခေါင်းပေါက်။','ခမော် ဆု = သစ်ခေါင်းပေါက်။')
,(2327,3,1,'၁။ အခေါင်းပေါက်။','၂။ ခမောက်။ ပက္ကလာ။')
