,(2330,3,1,'ပါးချိတ်ရောၚ်နာ။',null)
,(2331,3,1,'အဘိုးအခ။','လိၚ်ခမာၚ် = ငှားရမ်းခ။ အဘိုးအခ။')
,(2332,3,4,'(ဦးခေါင်းကို) ရစ်ပတ်သည်။ ခေါင်းပေါင်းပေါင်းသည်။',null)
,(2333,3,1,'ခေါင်းပေါင်း။ ဦးရစ်။','(ကြိ) ခေါင်းပေါင်းပေါင်းသည်။')
,(2334,3,4,'ဆင်တူသည်။ ခပ်ဆင်ဆင်တူသည်။','“သၟတ်တြုံဏအ် ရုပ်သာ်ခမုၚ်ဒၟံၚ် ကဵုဒေံအဲရ။” = “ဤသူငယ်သည် ကျွန်တော့်ညီနှင့် ရုပ်ချင်းဆင်တူသည်။”')
,(2335,3,1,'ပုရွက်ဆိတ်။',null)
,(2336,3,1,'အဆုပ်။ လက်တစ်ဆုပ်။','ပုၚ်မွဲခမောတ် = ထမင်းတစ်ဆုပ်။')
,(2336,3,1,'အဆုပ်။ လက်တစ်ဆုပ်။','(ကြိ) ဆုပ် လုံးသည်။')
,(2336,3,1,'အဆုပ်။ လက်တစ်ဆုပ်။','“ခမောတ်လဝ် ပုၚ်စှ်ခမောတ်။” = “ထမင်းဆယ်ဆုပ် ဆုပ်လုံးထားသည်။”')
,(2337,3,1,'ကမ္ဗောဒီးယားလူမျိုး။',null)
,(2338,3,1,'မေး။ မေးစေ့။',null)
,(2339,3,1,'၁။ အငုံ။ အဖူး။','ခၟောံမၠဵု = စပယ်ငုံ၊ စပယ်ဖူး။')
,(2339,3,1,'၁။ အငုံ။ အဖူး။','၂။ ကြယ်သီး။')
,(2339,3,1,'၁။ အငုံ။ အဖူး။','ခၟောံပ လောအ် = အင်းကျီကြယ်သီး။')
,(2339,3,1,'၁။ အငုံ။ အဖူး။','(ကြိ) ပါးစပ်စူသည်။ (တစ်စုံတစ်ခုကို သဘောမကျ၍ဖြစ်လာ သော ပါးစပ်အမူအရာ။)')
,(2340,3,1,'ချီသောလက်အုပ်။',null)
,(2341,3,1,'ရေပွက်။',null)
,(2342,3,1,'ဥ။','ခၟာဲစာၚ် = ကြက်ဥ။')
,(2342,3,1,'ဥ။','ခၟာဲကြဴ = ပိန်းဥ။')
,(2342,3,1,'ဥ။','(ကြိ) ဥဥသည်။')
,(2343,3,1,'ဖားဥ။ စိုထိုင်းမှုကြောင့် အဝတ်အထည်တွင် ဖြစ်ပေါ်သောအမည်းစက်များ။','ဒှ်ခမှာဲၚဴ = ဖားဥတက်သည်။ ဖားဥစွဲသည်။ မှိုတက်သည်။')
,(2344,3,1,'နှပ်ချေး။',null)
,(2345,3,3,'ကောင်းစားသော။ စီးပွားဖြစ်ထွန်းသော။ ကြွယ်ဝသော။ အကောင်းစားဖြစ်သော။ အမြတ်စားဖြစ်သော။',null)
,(2346,3,1,'သူတော်ကောင်း။ ဂုဏ်သရေရှိလူကြီး။ ကောင်းစားသောသူ။ လူကုံထံ။',null)
,(2347,3,1,'နက္ခတ်ကောင်း။ (ဇ—၄၉။ အစွောံ။)',null)
,(2348,3,1,'အကောင်းစားအဝတ်ပုဆိုး။ ပြေပြစ်သောအဝတ်။','“သေဋ္ဌဳဗာ ရာဏသဳဂှ် စရံက်လစိန် ဗိုက်ယာတ်ကၠေဟ်ယာတ်ကမှိဟ် မတိုန်သဳကၠဳ(သၟိၚ်)—။” (ဇ—၅၃။ အစွောံ။) = “ဗာရာဏသီသူဌေးသည် လက်စွပ်ကိုဝတ်၍ ကောင်းသောအဝတ်ပုဆိုးကိုဝတ်၍ မင်း ကိုခစားရန်သွား၏။”')
,(2348,3,1,'အကောင်းစားအဝတ်ပုဆိုး။ ပြေပြစ်သောအဝတ်။','“ယာတ်ခမှိဟ်လေဝ်မွဲ—။” (ဇ—၂၅၄။ အစွောံ။) = “ပုဆိုးကောင်း လည်းတစ်ထည်။”')
,(2349,3,1,'ကောင်းသောစိတ်။ စိတ်ကောင်း။','“ကဵုဍိုက်ပေၚ်တဴစိုတ်ဂမှိဟ်ညိ။” (သၠပတ် ဒ္ၚောဝ်သၜောံ) = “ကောင်းသောစိတ်နှင့် ပြည့်စုံသည်ဖြစ်ပါစေ။”')
,(2350,3,1,'အကောင်းစားရွှေ။ ရွှေစင်။ ရွှေစစ်စစ်။',null)
,(2351,3,1,'အကောင်းစားသံ။ သံမဏိ။',null)
,(2352,3,1,'ကောင်းသောလယ်ယာမြေ။',null)
,(2353,3,1,'အကောင်းစားအရက်။','“သူရာမ္ဂးဝွံ ခမဳသ္ဇိုၚ်ဂွံလောန်သန်” သၟိၚ်ဂးတုဲ သူရာဂ မှိဟ်မဂၠိုၚ်ဟေၚ် ကဵုကုဣသိတံရ။ (ဇ—၈၁။ အစွောံ။) = “အရက်ကောင်းမည်သည်ကို ရသေ့ တို့ ရခဲကုန်၏” ဟု မင်းသည် များစွာသော အကောင်းစားအရက်ကို ရသေ့တို့အားပေး၏။')
,(2354,3,1,'ဥဿဘနွားကောင်း။','“ဟိုတ်နူမပြဟ်ပြေဟ်လောန်ဂှ် ချေံသိန္ဓဴတၠဂကူ ညးမ ဂွံတီရောၚ်။ ဟိုတ်နူမယိုက်မသ္ဇိုၚ်လောန်နူဗၞတ်ဂှ် ဂၠဴဥဿဘဂမိဟ် ညးမဂွံတီရောၚ်။” (ဇ—၅၁၅။ အစွောံ။) = “လျင်မြန်ခြင်းဖြင့် မြင်းကောင်းကို သိရကုန်၏။ နွားကောင်းကိုလည်း လေးသော ဝန်ကို ရွက်ဆောင်ရာ­ သိရကုန်၏။”')
,(2355,3,3,'မသီးမပွင့်သော။ မြုံသော။ သားသမီးမထွန်းကားသော။',null)
,(2356,3,1,'ကြက်လျှာစွန်း။ သန်လျက်စွန်း။ (မြေပုံစံ)',null)
,(2357,3,1,'(ကြိ) ‘ခၟာဲ’ ရှု။',null)
,(2358,3,4,'အောက်ကျို့သည်။ ခယသည်။','‘ခယအောပ်မာဇအ်သဝ်။’ (ဇ—၁၂၅။ အစွောံ။) = ‘ခယဝပ်တွားအောက်ကျို့သည်။’')
,(2358,3,4,'အောက်ကျို့သည်။ ခယသည်။','“ယွံၝောံ၊ သ္တိက်ကၠေံတြဟာ” ဗမၞးဂး။ ဗြဴဂှ်မိၚ်ဗက် ဍေံပ လိုတ်ကၠေံပၟတ်တုဲ ဍေံပ္တိတ်လဝ်တြုံသ္ကဲဍေံ မ္ၚးတရၚ်ဂှ်တုဲ ဍေံလုပ်ပ္ဍေန်ပၟတ်ပၠန်တုဲ ဍေံဟီုခယသၠာံဗဇး စိုတ်ဗမၞး။ (ဇ—၄ဝ၂။ အစွောံ။) = “ရှင်မ၊ အိပ်နှင့်ပြီလော” ဟုပုဏ္ဏားဆို၏။ ထိုပုဏ္ဏေးမ ကြားသည်နှင့် မီးကိုငြိမ်းလိုက်ပြီးနောက် မိမိ၏သယောက်လင်ကို တံခါးပြင်သို့ထုတ်၍ ပြန်ဝင်လာကာ မီးကိုပြန်ထွန်းပြီးလျှင် ပုဏ္ဏားအား ခယသောစကားဖြင့် ပြောဆိုနှစ်သိမ့်၏။')
,(2359,3,4,'မှန်းဆသည်။ ထင်မှတ်သည်။ ထင်မြင်ယူဆသည်။','“အဲခယျညးနွံဒၟံၚ်ဏီ အ ခြၚ်ညးချိုတ်အာဂှ် အဲဟွံဂွံတီရောၚ်။” = “သူရှိနေသေးသည်ဟု ကျွန်တော်ထင်သည်၊ သူသေ ဆုံးသွားမှန်း ကျွန်တော်မသိရပါ။”')
,(2360,3,1,'ခါးပန်းကြိုး။','‘ကာယဗန်’ ရှု။')
,(2361,3,1,'၁။ ကျင်ငယ်။ ဆီး။','‘သမျာ’ ရှု။')
,(2361,3,1,'၁။ ကျင်ငယ်။ ဆီး။','၂။ အခ။ အဘိုး။ တန်ဖိုး။')
,(2361,3,1,'၁။ ကျင်ငယ်။ ဆီး။','(ကြိ) ပူ ဆာသည်။ နွဲ့ဆိုးဆိုးသည်။')
,(2362,3,1,'သမားတော်ကို ပေးပူဇော်ရသော ခြေကြွခ။',null)
,(2363,3,1,'အနာ။ ဒဏ်ရာ။',null)
,(2364,3,1,'၁။ အကွာအဝေး။','“ကွာန်တေံကဵုကွာန်ဏအ် ခရာနွံၜါတိုင်ရ။” = “ဟိုရွာနှင့်ဒီရွာ နှစ်မိုၚ်အကွာအဝေးရှိသည်။”')
,(2364,3,1,'၁။ အကွာအဝေး။','၂။ ခရာ။ လေမှုတ်တူရိယာ။')
,(2364,3,1,'၁။ အကွာအဝေး။','ခရာတမ္ၚူ = ခရာအဖြောင့်။')
,(2364,3,1,'၁။ အကွာအဝေး။','ခရာတမ္ၚံက် = ခရာအကောက်။')
,(2364,3,1,'၁။ အကွာအဝေး။','၃။ (၁၂)ခဏနှင့်တူညီသော အချိန်အတိုင်းအတာ။')
,(2364,3,1,'၁။ အကွာအဝေး။','(ကြိ) ခွါထားသည်။ ကားသည်။ ချဲသည်။')
,(2364,3,1,'၁။ အကွာအဝေး။','“မၞာ်ၜါတၞုၚ်ဏအ် ခရာလဝ်ပိၝောံတဲညိ။” = “ဤသံနှစ် ချောင်းကို သုံးလက်မခွါထားပါ။”')
,(2364,3,1,'၁။ အကွာအဝေး။','‘ခရာလဝ်ဒဳ’ = ‘ပေါၚ်ကားထားသည်’')
,(2364,3,1,'၁။ အကွာအဝေး။','‘ခရာလဝ်ဇိုၚ်’ = ‘ခြေကားထားသည်’')
,(2365,3,1,'လုံးကြီးတၚ်။ အက္ခရာအထက်တွင်ရေးသော ဣသရသၚ်္ကေတ။ —ိ ။',null)
,(2366,3,1,'အက္ခရာ၏နောက်တွင် မွန်(အး)သရသံရအောင် သၚ်္ကေတအဖြစ်ရေး သော အစက်အပြောက်နှစ်ခု။ —း။',null)
,(2367,3,4,'ခြစ်သည်။ ခြစ်ရာပေးသည်။',null)
,(2368,3,1,'မီးခြစ်။',null)
,(2369,3,4,'၁။ သိမ်းကြုံးသည်။ ခြုံယူသည်။','၂။ ကြော်လှော်သည်။')
,(2370,3,4,'ဖြတ်သည်။ ခုတ်ဖြတ်သည်။ ခုတ်ပိုင်းသည်။','“လၟုဟ်လၟကေတ်ဏာပိုဲကဵု သၟိၚ်တုဲ — ဖျုန်ပိုဲ သၟိၚ်ကဵုဂြောဝ်ဒန်ခရိက်တုဲ ပိုဲမဒးပကာဂစိုတ်ရ။” သၟိၚ်ၜိုပ်ထဝ်ဂး။ (ဇ—၅၃၄။ အစွောံ။) = “ယခုမုဆိုးသည် ငါတို့ကို မင်းဆီယူဆောင်၍ ငါတို့၏အသားကို မင်းသည် စား တော်ချက်အား ခုတ်ဖြတ်စေ၍ ငါတို့သည် သေရလတ္တံ့” ဟုရွှေဟၚ်္သာမင်းဆို၏။')
,(2370,3,4,'ဖြတ်သည်။ ခုတ်ဖြတ်သည်။ ခုတ်ပိုင်းသည်။','“——၊ စိုပ် သၟိၚ်တုဲ သော်သၞေၚ်ထဝ်ပိုဲဂှ် သၟိၚ်ပိုက်ကေတ်တုဲ ဖျုန်ပိုဲဂှ် သၟိၚ်ပအပ်တဲဂြောဝ်တုဲ ဂြောဝ်ဒန်ကဵုဒၞန် တုဲ ဂြောဝ်သရိက်ထောံ ကဵုသၟိၚ်စရ” သၟိၚ်ၜိုပ်ထဝ်ဂး။ (ဇ—၅၃၄။ အစွောံ။) = “မင်းထံရောက် ၍ ငါတို့၏ရွှေအတောင်တို့ကို မင်းသည်နှုတ်ယူပြီးလျှင် ငါတို့၏အသားကို မင်းသည် စားတော် ချက်လက်သို့အပ်၍ စားတော်ချက်သည် စဉ်းနှီးတုံးဖြင့်ခုတ်ပိုင်း၍ မင်းကိုစားစေလတ္တံ့” ဟုရွှေ ဟၚ်္သာမင်းဆို၏။')
,(2371,3,1,'၁။ ပန်းကန်းခွက်။ (ပါဠိ—ဘာဇန)','“(ထေရ်ဂှ်) သ္ၚာပံၚ်သကူညးတံဂှ် ဂိုၚ်ကေတ်တုဲ ဗဗေၚ်သီုခရော် ဂိုၚ်ကေတ်တုဲ ပ္ဍိုက်ယာန်ကွဳတုဲ ကလေၚ်စဴအာဘာဇေတဝန်ရ။” (ဇ—၂၉၆။ အစွောံ။) = “(ထိုရဟန်းကြီးသည်) ထိုရဟန်းတို့၏ သၚ်္ကန်းကိုယူ၍ ထိုရဟန်းတို့၏ နှစ်သက် ဘွယ်ရှိသော သပိတ် ခွက်တို့ကိုယူ၍ လှည်းကိုပြည့်စေ၍ ဇေတဝန်ကျောင်းတော်သို့ လာ၏။” (ညောင်ကန်)')
,(2371,3,1,'၁။ ပန်းကန်းခွက်။ (ပါဠိ—ဘာဇန)','၂။ ရှေးခေတ်စစ်လှေကြီးတစ်မျိုး။ ကူရွပ်။')
,(2372,3,1,'တၚ်ပါးခွက်။ တၚ်ပါးချိုင့်။ (ပါဠိ—ကုကုန္ဒရ) (= ခလံက်ထာၚ်တကေတ်)',null)
,(2373,3,1,'လုံ။ မီးခံခွက်။',null)
,(2374,3,4,'စိုက်ထူသည်။ ထောၚ်လျက်ထားသည်။','‘သြံက်’ (ကြိ)ရှု။')
,(2374,3,4,'စိုက်ထူသည်။ ထောၚ်လျက်ထားသည်။','“ထေရ်သာရိပိုတ်ညာတ် ကၞာၚ်ကြေၚ် ပြဘာတ်တံမခရံက်လဝ်ဂှ်တုဲ—။” (ဇ—၃ဝ၁။ အစွောံ။) = “အရှင်သာရိပုတ္တရာမ ထေရ်သည် ပရိဗိုဇ်တို့စိုက်ထောၚ်ထားသော သပြေခက်ကိုမြင်၍—။”')
,(2375,3,1,'ငါးပိ။',null)
,(2376,3,1,'ဝင်ကစွပ်ကောင်။',null)
,(2377,3,1,'ပုခက်။',null)
,(2378,3,4,'ရှုပ်ထွေးပြန့်ကျဲသည်။',null)
,(2379,3,4,'(သစ်ပင်စသည်) အကိုင်းကျိုးအရွက်မဲ့ဖြစ်သည်။',null)
,(2380,3,1,'၁။ လှောင်အိမ်။ လှောင်ချိုင့်။ (အ ၚအဂေ)','ခရိုၚ်တ္ၚေက် = ကြက်တူရွေးလှောင်အိမ်။')
,(2380,3,1,'၁။ လှောင်အိမ်။ လှောင်ချိုင့်။ (အ ၚအဂေ)','၂။ ကျွဲ၊ နွား၊ ဝက်စသည်) လှောင်ရာခြံ။ (အ ပနေ)')
,(2380,3,1,'၁။ လှောင်အိမ်။ လှောင်ချိုင့်။ (အ ၚအဂေ)','ခရိုၚ်ဂၠဴ = နွားခြံ။ (အ ငံဝပြနေ)')
,(2380,3,1,'၁။ လှောင်အိမ်။ လှောင်ချိုင့်။ (အ ၚအဂေ)','ခရိုၚ် ကၠိက် = ဝက်ခြံ။')
,(2380,3,1,'၁။ လှောင်အိမ်။ လှောင်ချိုင့်။ (အ ၚအဂေ)','“ပ္ဍဲဗ္တံဂှ် ကမၠတ်ဗပါ်ကၠေံခရိုၚ်တုဲ ဂၠဴဍေံဂွံဏာရ။” (ဇ—၂၅၇။ အစွောံ။) = “ခိုးသူသည် ညဉ့်­ ခြံကိုဖောက်၍ ထိုနွားတို့ကိုလျှင် ခိုး၏။” (ညောင်ကန်)')
,(2381,3,1,'ထိခိုက်တတ်သော လက်နက်ပါသည့် လူထောၚ်ချောက်။',null)
,(2382,3,1,'စရိတ်။','ခရိတ်ၜံက် = ဆေးလိပ်ဖိုး။')
,(2382,3,1,'စရိတ်။','(ကြိ) ၁။ (အရွက်၊ ဟင်းရွက်) သင်သည်။')
,(2382,3,1,'စရိတ်။','ခရိတ်ကပေါဝ် = ကင်ပွန်းရွက်သင်သည်။')
,(2382,3,1,'စရိတ်။','၂။ ပွတ်တိုက်သည်။')
,(2382,3,1,'စရိတ်။','“ယွံတလပညာ၊ မူတၟံတံဝွံ ရောအဴ” ညးဂမၠိုၚ်ဂး။ “ဣဝွံဒှ်ထဝ်၊ သြန်၊ ဗိုတ်၊ မြ၊ သိန်လှာဖအိုတ်ရမၞးတံ” ဗောဓိသတ်ဂး၊ ညးဂမၠိုၚ်မိၚ်တုဲ ဍေံတံခရိတ်ရံၚ် တီညာတ်ကေတ်အိုတ်(ရ။) (၅၅ဝ။ ဇ—၄၆၃။ ၇—၁၃၉။ အစွောံ။) = “ပညာရှိ၊ ဤကျောက်တို့သည် အဘယ်မည်သောကျောက်နည်း” ဟု လူအများမေး ကုန်၏။ “ဤသည်တို့မှာ ရွှေ၊ ငွေ၊ စိန်၊ မြ၊ သန္တာတို့တည်း” ဟု ဘုရားလောင်းဆိုသည်ကို ကြား၍ လူတို့သည် ပွတ်ကြည့်သည်ရှိသော် သိမြင်ကြရကုန်၏။')
,(2383,3,1,'အသုံးအဆောင် ပစ္စည်းပစ္စယ။',null)
,(2384,3,1,'စရိတ်စက။',null)
,(2385,3,1,'ခရစ်တော်။','သက္ကရာတ်ခရေတ် = ခရစ်သက္ကရာဇ်။')
,(2385,3,1,'ခရစ်တော်။','‘ယေသုခရေတ်’ လည်းရှု။')
,(2385,3,1,'ခရစ်တော်။','(ကြိ) ပိုးသည်။ ချစ်ကြိုက်ပိုးပန်းသည်။')
,(2386,3,1,'ခရစ်ယာန်ဘာသာဝင်။',null)
,(2387,3,4,'အပျိုပိုးပန်းသည်။',null)
,(2388,3,14,'(န) ခရစ်တော်မွေးနေ့ အထိမ်းအမှတ်အဖြစ် ဒီဇၚ်ဘာ(၂၅)ရက်နေ့ တွင် ကျင်းပသော ခရစ်ယာန်ဘာသာရေးပွဲ။ ခရစ္စမတ်ပွဲတော်။ (္ၚဟရိစတမအစ)',null)
,(2389,3,4,'၁။ ရှူသွင်းသည်။ ရှိုက်သွင်းသည်။','ခရောတ်ဂဥုဲ = ဆေးရှူသည်။')
,(2389,3,4,'၁။ ရှူသွင်းသည်။ ရှိုက်သွင်းသည်။','ခရောတ် သၟောဝ် = နှပ်ရည်ရှိုက်သွင်းသည်။')
,(2389,3,4,'၁။ ရှူသွင်းသည်။ ရှိုက်သွင်းသည်။','၂။ စုပ်သွင်းသည်။ စုပ်သောက်သည်။')
,(2389,3,4,'၁။ ရှူသွင်းသည်။ ရှိုက်သွင်းသည်။','ခရောတ်ဍာ်ဂမ္တဴ = ရေနွေးပူပူကို စုပ်သောက်သည်။')
,(2390,3,4,'၁။ ယားကျိကျိဖြစ်သည်။','“ကောန်ၚာ်ဂှ် မုဟ်ဍေံခရန်တုဲ ကၠေက်ဒၟံၚ်မုဟ်ရ။”= “ထို ကလေးသည် နှာခေါင်းယားကျိကျိဖြစ်၍ လက်ဖြင့် နှာခေါင်းကိုပွတ်နေသည်။”')
,(2390,3,4,'၁။ ယားကျိကျိဖြစ်သည်။','၂။ အသည်း ယားသည်။')
,(2390,3,4,'၁။ ယားကျိကျိဖြစ်သည်။','“ကောန်ၚာ်ဂှ် ကွာ်ထဍောန်ဒၟံၚ် လတူကၞာၚ်ဆုဂှ် ဖေက်ဍေံဒတုံစှ်ေ အဲခရန်ကွေံရ။” = “ထိုကလေးသည် သစ်ကိုင်းပေါ်တွင် လျှောက်ကူးသွားနေသည်၊ သူပြုတ်ကျမည်စိုး၍ ကျွန် မတကယ်အသည်းယားသည်။”')
,(2390,3,4,'၁။ ယားကျိကျိဖြစ်သည်။','၃။ (မျက်နှာပြင်) ကြမ်းသည်။')
,(2391,3,4,'အိုးကင်းဖြင့်လှော်သည်။','ခရောန်မ္ၚာန်၊ ခရောန်တမ္ၚာန် = မုန့်ဆန်းကို အိုး ကင်းဖြင့်လှော်သည်။')
,(2392,3,1,'ရွှ့ံညွန်၊ ရွှ့ံဗွက်။',null)
,(2393,3,1,'သရဲ။',null)
,(2394,3,1,'ချူ။ ခေါင်းလောင်းငယ်။',null)
,(2395,3,1,'အဆစ်များလှုပ်ရှားမှုကို လွယ်ကူချောမွေ့စေရန် ကူညီပေးသောအချွဲ။ ချောဆီ။ အစေး။',null)
,(2396,3,1,'ရဟန်းမဟုတ်သော လူပုဂ္ဂိုလ်။ လူဝတ်ကြောင်။','“တၠပညာမန်ဂမၠိုၚ်ခမဳ ခရှ်။” = “မွန်ရဟန်းရှင်လူပညာရှင်များ။”')
,(2397,3,4,'ခုသည်။ အောက်ခံပြုသည်။',null)
,(2398,3,1,'ဘီး။','ခလှာကွဳ = လှည်းဘီး။')
,(2398,3,1,'ဘီး။','(ကြိ) လမ်းလျှောက်သွားလာသည်။ လမ်းသ လားသည်။')
,(2398,3,1,'ဘီး။','“အဲညာတ်ဍေံခလှာဒၟံၚ်ပ္ဍဲဂၠံၚ်ရ။” = “သူလမ်းသလားနေသည်ကို ငါမြင်ခဲ့ရသည်။”')
,(2399,3,4,'၁။ မွှေနှောက်သည်။','၂။ ဆေးသည်။ ကျင်းသည်။')
,(2399,3,4,'၁။ မွှေနှောက်သည်။','ခလုပါၚ် = ပလုတ်ကျင်းသည်။')
,(2399,3,4,'၁။ မွှေနှောက်သည်။','၃။ မလိမ့်တပတ်လှည့်သည်။')
,(2399,3,4,'၁။ မွှေနှောက်သည်။','“လ္ပကၠုၚ်ခလုဒၟံၚ်အဲ အစောံဗှ်ေဂှ် အဲတီဒၟံၚ်ရ။” = “ငါ့ကို လာပြီးမလိမ့်တပတ်လုပ်မနေနှင့်၊ မင်းအစွမ်းကို ငါသိနေတယ်။”')
,(2400,3,4,'နယ်သည်။','“ကဂှ် ခလဴလဝ်ကဵုၜဵုတုဲရ။” = “ငါးကို ဆားနှင့်နယ်ထားပြီးပြီ။”')
,(2401,3,1,'ချိုင့်။','(ကြိ) ၁။ ချိုင့်သည်၊ ပိန်ချိုင့်သည်။')
,(2401,3,1,'ချိုင့်။','“ကလာပသဲဂှ် ခ လံက်အာရ။” = “သံသေတ္တာ ချိုင့်သွားသည်။”')
,(2401,3,1,'ချိုင့်။','၂။ လျော့ကျသည်။ လျော့ပါးသည်။ လျော့ နည်းသည်။')
,(2401,3,1,'ချိုင့်။','“ကၟာမွဲမၞုံဇမၠိၚ်အနာံ မွဲမွဲယောဇနာ ဍာ်မပေၚ်တဴဂှ် ပ္ဍဲဒေါဝ်ကၟာဂှ် ကၠံကၠံသၞာံမွဲဗြံက် ကီု ကဵုတုက်ဂိုၚ်ကေတ်ဂှ် ဍာ်ဒေါဝ်ကၟာ ဒၞာဲမတုက်ကေတ်ဂှ် ဍေံခလံက်ဒၟံၚ်ကီုဟာ။” (အဓါန်မသုန်')
,(2401,3,1,'ချိုင့်။','အစွောံ) = “အလျားအနာံ တစ်ယူဇနာစီရှိသော ရေပြည့်နေသောကန်­ အနှစ်တစ်ရာ အနှစ် တစ်ရာတိုင်း ထိုရေကန်လယ်ရှိရေကို တစ်ခွက်တစ်ခွက်စီခပ်ထုတ်သော် ထိုခပ်ထုတ်လိုက်သော ကန်လယ်ရှိရေသည် လျော့ကျသွားမည်လော။”')
,(2402,3,1,'တၚ်ပါးခွက်။ တၚ်ပါးချိုင့်။ (ပါဠိ—ကုကုန္ဒရ)',null)
,(2403,3,1,'ချိုင့်ခွက်။','“ဂၠံၚ်ဏအ် ခလံက်ဒနက်ဂၠိုၚ်ကွေံရ။” = “ဤလမ်းသည် ချိုင့်ခွက်အလွန်များသည်။”')
,(2403,3,1,'ချိုင့်ခွက်။','(ကြိ) (လမ်းခရီး) မညီမညွတ် ချိုင့်များဖြစ်နေသည်။')
,(2403,3,1,'ချိုင့်ခွက်။','“ဒၞာဲ တြဴခလံက်ဒနက်တံဂှ် ဂွံဗဝ်သတးကၠေံတုဲ ဗွဲသွာပိုဲသ္ဂောံအာရ။” = “လမ်းခရီး­ တွင်းချိုင့်များ ဖြစ်၍ မညီမညွတ်ရာနေရာတို့­ ညီညွတ်အောင် ဖို့ညှိလိုက်ပါက လွယ်ကူစွာ ငါတို့သွားနိုင်လိမ့် မည်။”')
,(2404,3,4,'လျော့နည်းသည်။ လျော့ကျသည်။ ယုတ်လျော့သည်။','“သၟိၚ် ကဵုဒၟံၚ်ဒါန်ရိုဟ်ဟ်တ္ၚဲဂှ်လေဝ် နကြဳဇှ်ဒြဟတ်ကုသဵုစိုတ်ဂှ်တုဲ ပ္ဍဲတိုက်တေံလေဝ် ဒြပ်တံဂှ် ဟွံဂွံခ လှံက်ယုတ်အာဟေၚ်။” (၅၅ဝ။ ဇ—၄၆၈။ ၇—၁၅၉။ အစွောံ။) = “မင်းသည် နေ့တိုင်းနေ့ တိုင်း အလှူပေးနေသော်လည်း ကုသိုလ်စိတ်၏ အစွမ်းအာနုဘော်ကြောင့် မင်း၏ဥစ္စာတိုက်မှ ဥစ္စာတို့သည်ကား မယုတ်လျော့သွားပေ။”')
,(2404,3,4,'လျော့နည်းသည်။ လျော့ကျသည်။ ယုတ်လျော့သည်။','‘ယုတ်ခလှံက်’ နှင့်အတူတူ။')
,(2405,3,4,'လှစ်ပြသည်။ လှန်ပြသည်။','ခလိုက်ဂၠိက် = လုံချည်လှန်သည်။')
,(2406,3,4,'၁။ စိတ်ရွှၚ်လန်းသည်။','မိပ်သလောၚ် = စိတ်ပျော်ရွှၚ်ကြည်နူးသည်။')
,(2406,3,4,'၁။ စိတ်ရွှၚ်လန်းသည်။','၂။ ပိုးပန်းသည်။')
,(2406,3,4,'၁။ စိတ်ရွှၚ်လန်းသည်။','“မဂဳဗျုဗျု သလောၚ်ကဵုဗၠာဲ” = “အဖွားကြီးအိုအို လူပျိုကလေးကို ပိုး ပန်းသည်။”')
,(2407,3,4,'ပျော်ရွှၚ်ကြည်နူးသည်။ ကြည်သာရွှၚ်ပျသည်။',null)
,(2408,3,4,'၁။ ကြမ်းကျွံသည်။','“ဍေံလိုန်ကွာ်အာ ပ္ဍဲလ္တူကၞဳဒုန်သမ်အိုဟ်ဂှ်တုဲ ဇိုၚ်ဍေံခလိုၚ်စှ်ေအာရ။” = “ဆွေးမြည့်သော ဝါးကြမ်းပြင်ပေါ်တွင် သူနင်းလျှောက်သွားရာ သူ့ ခြေကျွံကျသွားသည်။”')
,(2408,3,4,'၁။ ကြမ်းကျွံသည်။','၂။ နယ်ကျွံသည်။ ကျူးကျော်သည်။')
,(2408,3,4,'၁။ ကြမ်းကျွံသည်။','“ဒပ်ပၞာန်ပိုဲမွဲဒပ် ခလိုၚ်လုပ်အာ ပ္ဍဲဗွိုၚ်တိဍာ်ဒပ်ပၞာန်သၞရ။” = “ငါတို့၏စစ်တပ်တစ်တပ်သည် ရန်သူ့နယ်မြေအတွင်းသို့ နယ်ကျွံ ဝင်ရောက်သွားသည်။”')
,(2409,3,1,'ကွက်လပ်မြေ။ ကွင်းပြင်။','ခလာတ်က္ၜၚ်ကျာ = လေယာဉ် ကွင်း။')
,(2409,3,1,'ကွက်လပ်မြေ။ ကွင်းပြင်။','(ကြိ) ဘာမျှမရှိပဲ ပြောင်သည်။')
,(2409,3,1,'ကွက်လပ်မြေ။ ကွင်းပြင်။','က္ဍိုပ်ခလာတ် = ဦးခေါင်းပြောင်သည်။')
,(2410,3,1,'ခေါင်းပြောင်သူ။ ခေါင်းတုံးသူ။ ဆံပင်မရှိသူ။','“အဲဒှ်ကောန် သၟိၚ် ဍေံတံဟွံလ္ၚောဝ်၊ ခမဳခလှာတ်က္ဍိုပ်ဂှ် ဍေံလ္ၚောဝ်ဟာ” ကောန်သၟိၚ်ဂး။ (ဇ—၂၂ဝ။ အစွောံ။) = “မင်းသားဖြစ်သောငါ့ကို သူတို့မရှိခိုးဘဲ ၚခေါင်းတုံးရဟန်းကို ရှိခိုးရသလော” ဟု မင်းသားဆို၏။')
,(2411,3,4,'၁။ (ဖိနပ်၊ အင်းကျီစသည်) ချွတ်သည်။','ခလှောတ်ပ လောအ် = အင်းကျီချွတ်သည်။')
,(2411,3,4,'၁။ (ဖိနပ်၊ အင်းကျီစသည်) ချွတ်သည်။','ကလှောတ်ဒၞပ် = ဖိနပ်ချွတ်သည်။')
,(2411,3,4,'၁။ (ဖိနပ်၊ အင်းကျီစသည်) ချွတ်သည်။','၂။ ကျွတ်သည်။')
,(2411,3,4,'၁။ (ဖိနပ်၊ အင်းကျီစသည်) ချွတ်သည်။','“ဂၠိက်ခလောတ်စှ်ေအာ။” = “လုံချည်ကျွတ်ကျသွားသည်။”')
,(2411,3,4,'၁။ (ဖိနပ်၊ အင်းကျီစသည်) ချွတ်သည်။','“ၜုန်ဏအ် တဝ်ဍေံကလှောတ် တိတ်အာဣရ။” = “ဤဓါးသည် ဓါးရိုးကျွတ်ထွက်သွားပြီ။”')
,(2412,3,4,'၁။ မြှိုက်သည်။ မီးမြှိုက်သည်။','ခလာန်စာၚ် = ကြက်မွေးကိုမီးမြှိုက်သည်။')
,(2412,3,4,'၁။ မြှိုက်သည်။ မီးမြှိုက်သည်။','၂။ ပူစပ်သည်။ ပူလောင်သည်။ (အပူဒဏ်စသည်)')
,(2413,3,4,'၁။ ချွဲသည်။ ချွဲကျိသည်။','၂။ ကလက်သည်။ ကျီစယ်သည်။ နောက်ပြောင်သည်။')
,(2413,3,4,'၁။ ချွဲသည်။ ချွဲကျိသည်။','‘ကလှိန်’ ရှု။')
,(2414,3,4,'အချွဲကျသည်။ (ကျွဲနွားတိရစ္ဆာန်များ သားကျတော့မည့် နိမိတ်လက္ခဏာ)',null)
,(2415,3,4,'မျက်စိနောက်သည်။',null)
,(2416,3,4,'လျှောသည်။','“ဍာ်ဗြဲသလောန်စှ်ေ နူသၠကြဴ” = “မိုးရေသည် ပိန်း ရွက်မှ လျှောကျလာသည်။”')
,(2417,3,4,'ခေါက်သည်။ ခေါက်ချိုးသည်။','(န) အခေါက်အရာ။ ခေါက်ချိုးအရာ။')
,(2417,3,4,'ခေါက်သည်။ ခေါက်ချိုးသည်။','“တၞး စက္ခောဂှ် ခလပ်ထောံပိခလပ်ညိ။” = “ထိုစက္ကူရွက်ကို သုံးချိုးခေါက်လိုက်ပါ။”')
,(2418,3,1,'၁။ ခဲလံကျည်တောက်။ ကောက်ညှင်းကျည်တောက်။','၂။ (ပိုက်ဆံ) အပြား ဝိုင်း။ အပြားစေ့။ အကြွေစေ့။')
,(2418,3,1,'၁။ ခဲလံကျည်တောက်။ ကောက်ညှင်းကျည်တောက်။','ခလာံမွဲမး = တစ်မတ်စေ့။')
,(2418,3,1,'၁။ ခဲလံကျည်တောက်။ ကောက်ညှင်းကျည်တောက်။','ခလာံၜါမး = ငါးမူးစေ့။')
,(2418,3,1,'၁။ ခဲလံကျည်တောက်။ ကောက်ညှင်းကျည်တောက်။','ခလာံ မွဲဒကေဝ် = တစ်ကျပ်စေ့။')
,(2419,3,4,'တံတောင်နှင့်တွက်သည်။',null)
,(2420,3,3,'စိတ်မနှံ့သော။',null)
,(2421,3,4,'ဖောက်ထွင်းသည်။ ထိုးဖောက်သည်။ စူးဝင်သည်။','‘ကလှၚ်’ ရှု။')
,(2422,3,1,'ခဝါသည်။',null)
,(2423,3,4,'ဆောင့်အောင့်သည်။',null)
,(2424,3,4,'လွှင့်ပစ်သည်။','“ဂၠိက်ယာတ်အဲတအ်ဂှ် ဟိုတ်နူအဲဟွံကဆံၚ်ဂှ်ရ မိထေဲတုဲ ခဝေၚ်ထောံကၠေံရ။” = “ကျွန်တော့်အဝတ်အစားများကို ကျွန်တော်မလျှော်ဖွပ်သောကြောင့် အ မေစိတ်ဆိုးပြီး လွှင့်ပစ်လိုက်သည်။”')
,(2425,3,4,'မျက်နှာလွှဲသည်။',null)
,(2426,3,1,'ခြစ်ရန်ကရိယာ။','ခဝါတ်သတ်ဗြဴ = အုန်းခြစ်။')
,(2426,3,1,'ခြစ်ရန်ကရိယာ။','ခဝါတ်ကတ်စဳ = သၚ်္ဘောခြစ်။')
,(2426,3,1,'ခြစ်ရန်ကရိယာ။','ခဝါတ်ဇၜိိုတ် = ရော်ဘာခြစ်ရန်ဓါး။')
,(2427,3,1,'ခဝဲသီး။',null)
,(2428,3,4,'လွင့်သည်။','“ခဝဝ်ဒၟံၚ်လတူကျာ” = “လေထဲတွင်လွင့်နေသည်။”')
,(2429,3,1,'ကောက်ညှင်းကျည်ထောက်။ ခဲလံကျည်တောက်။',null)
,(2430,3,4,'ပသသည်။','ခၜဗဇဴ = ပသပူဇော်သည်။ (နတ်၊ ရိုးရာနတ်)')
,(2431,3,4,'‘ဂၜမ်’ ရှု။',null)
,(2432,3,1,'၁။ ချွန်း။','၂။ ပေါက်တူး။')
,(2432,3,1,'၁။ ချွန်း။','“(ဗောဓိသတ်) ရပ်ကေတ်ခၜံက် ၜံက်တိဂူတုဲ တဵုသၞေဝ် —။” (ဇ—၇ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် ပေါက်တူးကိုကိုၚ်လျက် ယာမြေကိုပေါက်၍ ဟင်းသီးဟင်းရွက်စိုက်ပျိုး၏။”')
,(2433,3,1,'ပေါက်တူး။',null)
,(2434,3,1,'ကောက်ဆွ။ (စပါးနယ်ရာတွင် ကောက်ပြန့်ကို စပါးနှင့်ကောက်ရိုး တခြားစီဖြစ် အောင် ထိုးဆွမြှောက်ကော်ရသော အဖျားကောက်ဝါးတုတ်။)',null)
,(2435,3,1,'ကျုံး။','ထၜိုၚ်ဍုၚ် = မြို့ပတ်လည်ကျုံး။')
,(2436,3,4,'ပြားချပ်သည်။','ဗုၚ်ခၜါတ် = ဝမ်းဗိုက်ပြားချပ်သည်။')
,(2437,3,1,'မာလာဖူး။','(ကြိ) မြည်တွန်သည်။ နားပူနားဆာလုပ်သည်။')
,(2438,3,4,'စုပ်သည်။','မခၜေတ် = သကြားလုံး။')
,(2439,3,1,'အစေး။','ဗၜိုတ်ပၞဟ် = ပိနနဲအစေး။')
,(2439,3,1,'အစေး။','(ကြိ) စေးကပ်သည်။')
,(2440,3,1,'သစ်စေး။ (ဘုရားရွှေချရန်သုံးသည်)',null)
,(2441,3,1,'ပန်းကန်။ ခွက်။','“သတ်ဗဒဝ်စုတ်ပ္ဍဲခၜိုန်ထဝ်တုဲ သၟိၚ်စတဴရ။” (ဇ—၃ဝ၆။ အစွောံ။) = “မင်းသည် ရွှေခွက်­ထည့်၍ ဆီးသီးကိုစားလျက် နေ၏။” (ညောင်ကန်) (ဂံလဒနေ ဒိစဟ)')
,(2441,3,1,'ပန်းကန်။ ခွက်။','(ကြိ) ဝင့်ကြွားသည်။ မောက်မာသည်။')
,(2441,3,1,'ပန်းကန်။ ခွက်။','“ဣဗြဴဏအ် ဟီုအရေဝ်ခၜိုန်ကွေံကွေံ။” = “ဤမိန်းမ စကားပြောမောက်မာသည်။”')
,(2442,3,1,'အလုံး၊ အချောင်း။','ဒုန်မွဲထၜောမ် = ဝါးတစ်ချောင်း၊ ဝါးတစ်လုံး။')
,(2442,3,1,'အလုံး၊ အချောင်း။','ကြုက်ၜါထၜောမ် = သရက်သီးနှစ်လုံး။')
,(2443,3,1,'အလုံးအထည်။ အလုံးအဖန်။',null)
,(2444,3,4,'စွေစောင်းအောင်လုပ်သည်။',null)
,(2445,3,1,'ချိုးစိမ်း။',null)
,(2446,3,4,'စုစည်းသိမ်းကြုံးယူသည်။',null)
,(2447,3,4,'ဖဲ့သည်။ ခွါသည်။ ဖြဲသည်။ ဟစေသည်။','“ကွာၚ်ဂှ် ခၜိဟ်ကဵုအဲမွဲကရေက် ညိ။” = “မုန့်ကို ငါ့အား တစ်ခြမ်းဖဲ့ပေးပါ။”')
,(2447,3,4,'ဖဲ့သည်။ ခွါသည်။ ဖြဲသည်။ ဟစေသည်။','“ဒူရေန်မ္ဂးဂှ် ခၜိဟ်တုဲဒးစရောၚ်။” = “ဒူး ရင်းသီးကို ဖြဲခွါပြီးစားရသည်။”')
,(2448,3,1,'အမြှုပ်။',null)
,(2449,3,1,'ရေမြှုပ်။',null)
,(2450,3,4,'အမြှုပ်ထသည်။ အမြှုပ်တက်သည်။',null)
,(2451,3,4,'(လူနာ)ပါးစပ်မှ အမြှုပ်ထွက်သည်။',null)
,(2452,3,4,'စကားထစ်သည်။ စကားမပီမသဖြစ်သည်။','“ၚာ်တြုံဂှ် ဟီုအရေဝ်ခအဒၟံၚ်ရ။” = “ထို သူငယ်သည် စကားပြောမပီ စကားထစ်နေသည်။”')
,(2453,3,16,'‘ဂအဳ’ ရှု။',null)
,(2454,3,4,'၁။ ချီးမွမ်းသြဘာပေးသည်။','‘ဖအဴ’ ရှု။')
,(2454,3,4,'၁။ ချီးမွမ်းသြဘာပေးသည်။','၂။ လှော်သည်။')
,(2454,3,4,'၁။ ချီးမွမ်းသြဘာပေးသည်။','ခအော ပ္ၚာန်')
,(2454,3,4,'၁။ ချီးမွမ်းသြဘာပေးသည်။','တမ္ၚာန် = မုန့်ဆန်းလှော်သည်။')
,(2455,3,1,'ညှင်း။ (အရေပြားယားနာတစ်မျိုး)',null)
,(2456,3,1,'ဆင်ညှင်း။ (တစ်ကိုယ်လုံး အပြားလိုက်ဖြစ်သောညှင်း)',null)
,(2457,3,1,'နို့ညှင်း။ (နို့စို့ကလေးငယ်­ဖြစ်သောညှင်း)',null)
,(2458,3,4,'ငိုရှိုက်သည်။','ခအိက်ယာံ၊ ယာံခအိက် = ရှိုက်ကြီးတၚၚ်ငိုသည်။')
,(2459,3,4,'ချိသည်။','ဂၞိၚ်ခအိုက် = ခါးချိသည်။')
,(2460,3,1,'ကင်သည်။','ခအၚ်ကွာၚ် = မုန့်ကင်သည်။')
,(2461,3,1,'အိမ်မြေနေရာ။ မြေကွက်။','ခအာၚ်သ္ၚိ = အိမ်မြေကွက်။')
,(2461,3,1,'အိမ်မြေနေရာ။ မြေကွက်။','ခအာၚ်ကၠအ် = ခြံမြေကွက်။')
,(2462,3,1,'စိတ်နှလုံး။ နှလုံးအိမ်။',null)
,(2463,3,1,'ရောဂါမျိုးစုံတို့၏ ဖြစ်တည်ရာခန္ဓာကိုယ်။ (ဂအာၚ်ယဲဗွဝ်ဇွ ခန္ဓသမ်အုဲ)',null)
,(2464,3,1,'ရေငန်စပ်နေ ပုစွန်လုံးတစ်မျိုး။','(ကြိ) စွေစောင်းစေသည်။')
,(2465,3,4,'အောင့်သည်။ နာသည်။','ဗုၚ်ခအံၚ် = ဗိုက်အောင့်သည်။ ဗိုက်နာသည်။')
,(2465,3,4,'အောင့်သည်။ နာသည်။','စးခအံၚ် = ကျောအောင့်သည်။')
,(2466,3,1,'ခိုအောင်းရာ။ ကျက်စားရာ။','ခအံၚ်ပြေၚ်၊ ဖအံၚ်ပြေၚ် = ကျွဲတို့ကျက်စားရာ နေရာ။')
,(2467,3,4,'ကပ်စေးနှဲသည်။ တွန့်တိုသည်။',null)
,(2468,3,4,'ကပ်စေးနှဲသည်။ တွန့်တိုသည်။',null)
,(2469,3,4,'အလွန်စေးနှဲသည်။ (ကျောက်စရစ်ခဲကိုပင် ရေထွက်အောင် ညှစ်ထုတ် ရလောက်အောင် အလွန်စေးနှဲသည်။)',null)
,(2470,3,4,'အလွန်စေးနှဲသည်။ (မျက်ချေးကိုပင် နှမြောသည်။ နှမြောတွန့်တိုခြင်း တွင် ကမ်းကုန်သည်။)',null)
,(2471,3,4,'၁။ ကျက်လောက်ရုံ အပုပ်လွတ်ရုံ ကင်သည်','ချက်သည်။')
,(2471,3,4,'၁။ ကျက်လောက်ရုံ အပုပ်လွတ်ရုံ ကင်သည်','ခအောတ်က = အ ပုပ်လွတ်ရုံ ငါးချက်သည်')
,(2471,3,4,'၁။ ကျက်လောက်ရုံ အပုပ်လွတ်ရုံ ကင်သည်','ကင်သည်။')
,(2471,3,4,'၁။ ကျက်လောက်ရုံ အပုပ်လွတ်ရုံ ကင်သည်','ခအောတ်ပရာၚ် = အပုပ်လွတ်ရုံကင်သည်။')
,(2471,3,4,'၁။ ကျက်လောက်ရုံ အပုပ်လွတ်ရုံ ကင်သည်','၂။ (ခြောက် လုခါနီး၍) ကျုံ့ဝင်သည်။ ကျဉ်းဝင်သည်။')
,(2471,3,4,'၁။ ကျက်လောက်ရုံ အပုပ်လွတ်ရုံ ကင်သည်','“စဲလဝ်ကတအ်ဂှ် ခအောတ်စှ်ေအာ ကြပ်ကှ်ရ။” = “ငါးများနေလှန်းထားသည်မှာ ကျုံ့ကျသွားပြီး ခြောက်ခါနီးပြီ။”')
,(2472,3,1,'(အိပ်ချင်၍) သန်းသည်။',null)
,(2473,3,4,'(သော့စသည်ဖြင့် အသေမပိတ်ဘဲ) စေ့ထားသည်။','“တရၚ်ဂှ် ခအေပ်လဝ်ညိ။” = “တံခါးကို စေ့ထားပါ။”')
,(2474,3,4,'မျက်စိမှိတ်သည်။',null)
,(2475,3,4,'၁။ (အဝတ်အစား၊ စားသုံးကုန်ပစ္စည်းစသည်) စိုထန်းထန်းဖြစ်သည်။ အစိုငွေ့ ရှိသည်။ အစိုပြန်သည်။ စိုထိုင်းစများသည်။','“ဂၠိက်ဂှ် စဲလဝ်တ္ၚဲကှ်ဟွံခိုဟ် ခအိုပ်ဒၟံၚ်ရ။” = “ထိုလုံချည်ကို နေလှန်းထားသည်မှာ ကောင်းကောင်းမခြောက်ဘဲ အစိုငွေ့ရှိနေသည်။”')
,(2475,3,4,'၁။ (အဝတ်အစား၊ စားသုံးကုန်ပစ္စည်းစသည်) စိုထန်းထန်းဖြစ်သည်။ အစိုငွေ့ ရှိသည်။ အစိုပြန်သည်။ စိုထိုင်းစများသည်။','၂။ (ချွေး) စို့သည်။')
,(2475,3,4,'၁။ (အဝတ်အစား၊ စားသုံးကုန်ပစ္စည်းစသည်) စိုထန်းထန်းဖြစ်သည်။ အစိုငွေ့ ရှိသည်။ အစိုပြန်သည်။ စိုထိုင်းစများသည်။','“မၞိဟ်ယဲဂှ် ပလက်ခအိုပ်ဒၟံၚ်ရ။” = “လူနာသည် ချွေးစို့နေသည်။”')
,(2476,3,4,'ညှီသည်။ ညှီစော်နံသည်။','ခအီကၠဵု = ခွေးအနံ့ညှီသည်။')
,(2476,3,4,'ညှီသည်။ ညှီစော်နံသည်။','ခအီသၟူဇကု = ကိုယ်အနံ့ညှီသည်။')
,(2477,3,4,'ချောင်းဟန့်သံပြုသည်။','‘ကဟေမ်’ ဟုလည်းရေးသည်။')
,(2478,3,4,'၁။ စောင်းအောင်လုပ်သည်။','၂။ နွမ်းအောင်လုပ်သည်။')
,(2478,3,4,'၁။ စောင်းအောင်လုပ်သည်။','“ကြုက်ၜှ်လဝ်ဂှ် လ္ပဖအေဲထောံညိ။” = “ခူးထားသောသရက်သီးကို မနွမ်းပါစေနှင့်။”')
,(2478,3,4,'၁။ စောင်းအောင်လုပ်သည်။','၃။ (မျက်စိ)မှိတ်သည်။')
,(2478,3,4,'၁။ စောင်းအောင်လုပ်သည်။','“ဖအေဲလဝ်မတ်မွဲဒိုဟ်” = “မျက်စိတစ်ဖက်မှိတ်ထားသည်။”')
,(2479,3,4,'နှာချေသည်။','‘တအှ်’ ရှုပါ။')
,(2480,3,1,'ချွေးမ။','“ခအှ်ောအဲမွဲဂှ် သၞေက်မၞိဟ်သီုအပေါတ်ကယိုၚ်ဂှ် ဍေံဒးဂၞပ်ရ။” (ဇ— ၂၈၉။ အစွောံ။) = “အကျွန်ုပ်၏ချွေးမသည် ပတ္တမြားနားဍောင်းနှင့် အဆင်တန်ဆာတို့ကို အလို ရှိ၏။”')
,(2480,3,1,'ချွေးမ။','‘ဂအှ်’ ရှု။')
,(2481,3,4,'ပြည့်လျှံသည်။ မိုမောက်သည်။','သြိုဟ်ဂအုဟ်တဴ = ရၚ်သားမိုမောက်သည်။')
,(2482,3,4,'ညှီသည်။ ညှီစော်နံသည်။','“ကထမၞေက်ဏအ် ခအေဟ် ကွေံရ။” = “ဤငါးစိမ်းသည် အလွန်ညှီသည်။”')
,(2483,3,4,'အန်သည်။','(န) အန်ဖတ်။')
,(2483,3,4,'အန်သည်။','စအအ်ကဇၞော် = ငါးကြီးအန်ဖတ်။')
,(2484,3,4,'လေချဉ်တက်သည်။ လေအန်သည်။',null)
,(2485,3,1,'အခြၚ်။ အမိုးတၚ်သည့်တန်း။',null)
,(2486,3,4,'လေချဉ်တက်သည်။ လေအန်သည်။',null)
,(2487,3,1,'ဟင်းနုနွယ်ပင်။','ခါဇလ = ဆူးဟင်းနုနွယ်။ ဟင်းနုနွယ်အရိုင်း။')
,(2487,3,1,'ဟင်းနုနွယ်ပင်။','(ကြိ) ခြစ်သည်။')
,(2487,3,1,'ဟင်းနုနွယ်ပင်။','“ပုၚ်သ္ၚေက်ဂတာထၟာဲဂှ် ခါပ္တိတ်ကဵုဇန်ညိ။” = “အိုးရင်း­တူးကပ်နေသော ထမင်းချိုးကို ဇွန်းဖြင့် ခြစ်ခွါထုတ်လိုက်ပါ။”')
,(2488,3,16,'သောအခါ။ အကယ်၍။','“ဝတ္ထုဝွံ (ပိဏ္ဍပါတ်ဝွံ) ခါရအဲထောံကၠေံ လတူတိဝွံ လေဝ် ကၠဵုခဍာ်လပှ်စဒၟံၚ် ပွအဲဝွံပြာကတ်အာရ။ ခါအဲသကိုဟ်ထောံ ပ္ဍဲဍာ်ဂှ်လေဝ် ကၠေၚ်သွဟ်တံဝွံ ကဝေၚ်ဒၟံၚ် ညးညာတ်စုတ်ပၠန်ရ” ခမဳဂှ်ချပ်။ (ဇ—၄၁။ အစွောံ။) = “ဤဃနာဆွမ်းကို အကယ် ၍မြေပေါ်­ ငါစွန့်ပစ်သည်ရှိသော် ခွေး၊ ကျီးအစရှိသည်တို့စား၍ ငါ့အမှုသည် ထင်ရှားလတ္တံ့။ အကယ်၍ရေထဲသို့ သွန်ပစ်လျှင်လည်း ဤထောပတ်တို့သည် အဆီဝင်းသဖြင့် လူတို့မြင်ကုန်ပြန် ရာ၏” ဟုထိုရဟန်းတွေး၏။')
,(2488,3,16,'သောအခါ။ အကယ်၍။','“(ကၞိဂှ်) စၞခါမအောန် ဍောၚ်ၜိုတ်ဇြေဟ်ဇြာဲ အောန်အာဖျုန်ဆီ ရ။” (ဇ—၁၃၇။ အစွောံ။) = “ထိုကြွက်သည် အစာနည်းသောအခါ ပင်ပန်းပိန်လှီ၍ အသွေးအ သားနည်းသွားလေ၏။”')
,(2488,3,16,'သောအခါ။ အကယ်၍။','“ပ္ဍဲဇြပ်ဂှ် ခါရဒးဂၞပ် အာဒီုဂွံရ။” (ဇ—၁၅၅။ အစွောံ။) = “ထိုဇရပ်­ အကယ်၍နှစ်သက်ပါက သွား၍တည်းခိုနိုင်ပါသည်။”')
,(2489,3,1,'မၚ်္ဂလာမရှိသူ၊ —ခြင်း။ ကျက်သရေမရှိသူ၊ —ခြင်း။ သူယုတ်။ ယုတ်ညံ့သောအရာ။','“ကွာန်ပိုဲဝွံ မၞိဟ်ခါခဏဳနွံမွဲရ။” (ဇ—၄၁။ အစွောံ။) = “ငါတို့၏အတွင်း­ တယောက်သော သူ ယုတ်ရှိသည်ဖြစ်ရာ၏။”(ညောင်ကန်)')
,(2489,3,1,'မၚ်္ဂလာမရှိသူ၊ —ခြင်း။ ကျက်သရေမရှိသူ၊ —ခြင်း။ သူယုတ်။ ယုတ်ညံ့သောအရာ။','“ယွံတၠညး၊ ကောန်ဗြဴသေဋ္ဌဳဂှ် ဗြဴကျာ်သြဳဟွံသေၚ်၊ လက် သန်ခါခဏဳရောၚ်အဴ” ဗမၞးတံဂး။ (ဇ—၅၂၇။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ထိုသူဌေးသမီးသည် ကျက်သရေရှိသော မိန်းမမဟုတ်၊ သူယုတ်မ၏လက္ခဏာတည်း” ဟုပုဏ္ဏားတို့ဆို၏။')
,(2489,3,1,'မၚ်္ဂလာမရှိသူ၊ —ခြင်း။ ကျက်သရေမရှိသူ၊ —ခြင်း။ သူယုတ်။ ယုတ်ညံ့သောအရာ။','“ယာတ်ဝွံဂှ် (ကၞိကိတ်စုတ်တုဲ) ဍေံဒှ်အမၚ်္ဂလတုဲရ ဍေံဟွံဒှ်မ္ၚဵုရ။ ဍေံဒှ်အာခါခဏဳ မယုတ်မာ လောန်တုဲရ။” (ဇ—၈၇။ အစွောံ။) = “ဤအဝတ်သည် ကြွက်ကိုက်လိုက်သဖြင့် မၚ်္ဂလာမရှိ တော့၊ အမၚ်္ဂလာဖြစ်သွားပြီ၊ အလွန်ယုတ်ညံ့သောအရာဖြစ်သွားပြီ။”')
,(2489,3,1,'မၚ်္ဂလာမရှိသူ၊ —ခြင်း။ ကျက်သရေမရှိသူ၊ —ခြင်း။ သူယုတ်။ ယုတ်ညံ့သောအရာ။','“ဂစေံခါခဏဳဝွံဂှ် ဍေံဂဗး စုတ်မုက်အဲတုဲရ” လၟဂး။ (ဇ—၂ဝ၆။ အစွောံ။) = “ဤငှက်ယုတ်မာသည် ငါ့မျက်နှာကို ပုတ် ခတ်ခဲ့လေပြီ” ဟုမုဆိုးဆို၏။')
,(2490,3,4,'အားလုံးတစ်ခုမကျန် ကုန်သွားသည်။ ပြောင်တလင်းခါသည်။ (ပလိုင်းမှလည်း ကောင်း တောင်းမှလည်းကောင်း အကုန်လုံးထုတ်ယူသည်။)',null)
,(2491,3,1,'ခါးဗန်းကြိုး။ ရဟန်းခါးပတ်ကြိုး။',null)
,(2492,3,1,'လေးတင်းဝင်ဆန့်သော အခြၚ်အတွယ်။ (တစ်ဆယ့်ခြောက်ဒေါဏနှင့် ညီမျှသည်။)',null)
,(2493,3,1,'သရက်ထည်မျိုးပိတ်ချော။ ခါသာပိတ်။ (မူဆလင်အမျိုးသားများဝတ်သော အဝတ်ပါး တစ်မျိုး။)',null)
,(2494,3,1,'ခါးပတ်ကြိုး။ ခါးသိုင်းကြိုး။',null)
,(2495,3,1,'ခယ်မ။ မယား၏ညီမ။ (ပါဠိ—ပဇာဝတဳ)',null)
,(2496,3,1,'ဇွန်းဖြင့်ခြစ်၍ရသော မနုလွန်း မရင့်လွန်းသောအုန်းသီး။ ဇွန်းခြစ်။','‘ဍာ်ပေၚ်သတ် ပေၚ်’ လည်းရှု။')
,(2497,3,11,'(န) သၚ်ဓုန်းစက်။ (ပါဠိ—ခုရစက္က)','“မၚ်ဗၠာဲမိတ္တဝိန္ဒကဂှ် ဟိုတ်ဒးထၞိက်စုတ်မိ မဒှ်သောတာပန်ဂှ်တုဲ ဟိုတ်သရာံပါပ်ဂှ်ရ ဒးယဵုခုရစက် ဂျိုၚ်ဂျိၚ်ဒးနရက်ရ။” = “မိတ္တဝိန္ဒကလု လင်သည် သောတာပန်ဖြစ်သောမိခင်အား ကန်ကျောက်မိသည့် မကောင်းမှုကြောင့် သၚ်ဓုန်းစက် ကိုရွက်လျက် အရှင်လတ်လတ် ငရဲခံရ၏။”')
,(2498,3,1,'နှင်းခူ။ ခူနာ။','ခူစိၚ် = ဆင်နှင်းခူ။')
,(2499,3,10,'(န) ဘေးဒုက္ခကုန်ရာ ငြိမ်းရာနိဗ္ဗာန်။ ခေမာ။',null)
,(2500,3,1,'ကေသရာခြင်္သေ့။',null)
,(2501,3,4,'ဆွဲတၚ်သည်။ မြှင့်တၚ်သည်။ လိပ်တၚ်သည်။ ခေါက်တၚ်သည်။','ခဲဂၠိက် = လုံချည်မြှင့် တၚ်သည်။')
,(2501,3,4,'ဆွဲတၚ်သည်။ မြှင့်တၚ်သည်။ လိပ်တၚ်သည်။ ခေါက်တၚ်သည်။','ခဲဂၞိန် = ထဘီမြှင့်တၚ်သည်။')
,(2501,3,4,'ဆွဲတၚ်သည်။ မြှင့်တၚ်သည်။ လိပ်တၚ်သည်။ ခေါက်တၚ်သည်။','ခဲတဲပလောအ် = အင်္ကျီလက်ခေါက်တၚ်သည်။')
,(2502,3,1,'ကော်ဇော။','‘ကောဇဴ’ နှင့်အတူတူ။')
,(2503,3,1,'တောင်းငယ်။ နတ်ပသရန်ခေါခွက်။','“(ဒဂိုတ်မဇြာဲသကှ်ဒၟံၚ်ဂှ်) လၟဂိုၚ်ပတိတ်နူခံတုဲ စွံလဝ်လတူဂတာတဲရ။” (ဇ—၁၁၈။ အစွောံ။) = “ထိုပိန်ခြောက်နေသောငုံးကို မုဆိုးသည် တောင်းငယ်မှထုတ်၍ လက်ဖဝါးပြင်­ ထား၏။”')
,(2504,3,4,'(လက်ဖြင့်) ခံယူသည်။ ဖမ်းယူသည်။','“(မၚ်ဗၠာဲဂှ်) လတိုၚ်ဝေၚ်နုၚ်ဂှ်တုဲ ခမ် ကေတ်ရ။ လတိုၚ်ၜါဝါပိဝါဂှ် ခမ်ဂွံရ။ လတိုၚ်မွဲဝါပၠန်ဂှ် ခမ်ဟွံဂွံ—။” (ဇ—၂၉၁။ အစွောံ။) = “လုလင်သည် အိုးကို ကောင်းကင်သို့ မြှောက်ကစား၍ (လက်ဖြင့်)ဖမ်းယူ၏။ နှစ်ကြိမ်သုံးကြိမ် မြှောက်သော် ဖမ်း၍ရ၏။ နောက်တစ်ကြိမ်မြှောက်ပြန်သော် ဖမ်း၍မရ။”')
,(2505,3,4,'မိမိကိုယ်ကို မလဲသွားအောင် အရှိန်အဟုန်ကိုထိန်းသည်။ အဟုန်ကိုတန့်စေသည်။','“(ဇာဒိသိုၚ်)ဂအတ်ရမျှာၚ်တုဲ သီုဒြဟတ်စလာ်စှ်ေ ဒြာဲမိၚ်ဗရုဖေက်တုဲ ဒြေပ်ဒဴအာ၊ ဇာဒိ သိုၚ်ခမ်ဇကုဟွံမာန်တုဲ ဂၠက်စှ်ေအာပ္ဍဲသရီုဂှ်—။” (ဇ—၁၅၇။ အစွောံ။) = “(သမင်ကိုဖမ်းရန် ခြင်္သေ့သည် ဟိန်းဟောက်သံပြု၍ တစ်အားကုန် ခုန်အုပ်လိုက်ရာ သမင်ကြောက်၍ ပြေးရှောင် ၏။) ခြင်္သေ့သည် အဟုန်တန့်စိမ့်သောငှာ မတတ်နိုင်သည်ဖြစ်၍ ညွန်အပြင်­ကျ၍ နစ်၏။” (ညောင်ကန်)')
,(2506,3,4,'(ကျောက်စရစ်ဖြင့်) ဇယ်ခွံသည်။',null)
,(2507,3,4,'ဆီးကြိုလက်သင့်ခံယူသည်။',null)
,(2508,3,1,'နံနံရွက်။','ခံဗံသေံ = ရှမ်းနံနံရွက်။')
,(2508,3,1,'နံနံရွက်။','ခံဗံကြုက် = တရုတ်နံနံရွက်။')
,(2509,3,4,'၁။ ချိတ်သည်။ ငြိသည်။ တစ်သည်။','ခက်ဇုတ် = လည်ချောင်းအရိုးစူးသည်။')
,(2509,3,4,'၁။ ချိတ်သည်။ ငြိသည်။ တစ်သည်။','ခက် ဇလ = ဆူးငြိသည်။')
,(2509,3,4,'၁။ ချိတ်သည်။ ငြိသည်။ တစ်သည်။','ခက်ကအ် = လည်ပင်းတစ်သည်။ လည်ချောင်းတစ်သည်။')
,(2509,3,4,'၁။ ချိတ်သည်။ ငြိသည်။ တစ်သည်။','ခက်ဇုတ် = အရိုးစူးသည်။')
,(2509,3,4,'၁။ ချိတ်သည်။ ငြိသည်။ တစ်သည်။','၂။ အဆင်မပြေဖြစ်သည်။ အခက်အခဲဖြစ်သည်။')
,(2509,3,4,'၁။ ချိတ်သည်။ ငြိသည်။ တစ်သည်။','“ကိစ္စတၞဟ်သ္အာၚ်အိုတ်သီုဂှ် ပြေပြံၚ်ဒၟံၚ်ဖအိုတ်ရ၊ ဆကိစ္စသြန်မွဲဟေၚ် ခက်ဒၟံၚ်ညိရ။” = “အခြားသောကိစ္စအားလုံး အဆင် ပြေနေပါသည်။ ငွေရေးကြေးရေးကိစ္စတစ်ခုသာ အနည်းငယ် အခက်အခဲဖြစ်နေသည်။”')
,(2510,3,4,'အခက်အခဲဖြစ်သည်။ အကျပ်အတည်းဖြစ်သည်။',null)
,(2511,3,4,'သလိပ်ဟက်သည်။','ခါ်ပ္တိတ်သၠေဟ် = သလိပ်ဟက်ထုတ်သည်။')
,(2512,3,4,'၁။ သလိပ်ဟက်ပြီး ထွေးပစ်သည်။','၂။ (ဥပစာ) မနှစ်မြို့ဖြစ်သည်။ ရွံ မုန်းသည်။ ရွံရှာကြောင်းပြသည်။')
,(2512,3,4,'၁။ သလိပ်ဟက်ပြီး ထွေးပစ်သည်။','“ဍေံပလီုလဝ်ကောန်သမ္ဘာညးတုဲ အလုံကွာန်မွဲ က္ဍုဟ်မၠေအ် ချဟ်ခါ်တဴဍေံအိုတ်ရ။” = “သူမုဒိန်းကျင့်ထား၍ တစ်ရွာလုံးက သူ့ကို ရွံမုန်းတံတွေးထွေးနေကြသည်။”')
,(2513,3,5,'တခုတ်ခုတ်ဖြင့် ချောင်းဆိုသံပြုလျက်။','“ဟိုတ်နူဣသိဂှ် ခ္ဍက်ဒၟံၚ်ခုက်ခုက်တုဲ ဣ သိခုက် ညးမကော်ရ။” = “ထိုရသေ့သည် တခုတ်ခုတ်ဖြင့် ချောင်းဆိုးနေသောကြောင့် သူ့ကို ‘ရသေ့ခုတ်’ ဟုခေါ်ကြသည်။”')
,(2514,3,5,'တခစ်ခစ်ဖြင့် ရယ်မောလျက်။','“ကောန်ၚာ်ဂှ် ဂြိုၚ်တဴဒၟံၚ်ခေက်ခေက်ရ။” = “ထိုကလေးသည် တခစ်ခစ်ရယ်မောနေသည်။”')
,(2515,3,1,'ခွက်။','ထၟာဲပ္ၚာန်ခေါ်ခရော် = အိုးခွက်ပန်းကန်များ။')
,(2516,3,1,'လက်ကတီး။ ချိုင်းကြား။',null)
,(2517,3,1,'ပေါၚ်ခြံ။ ပေါၚ်ရင်းအတွင်းဖက်ပိုင်း။',null)
,(2518,3,1,'မျက်ကွင်း။',null)
,(2519,3,1,'မီးခွက်။ ဆီမီးခွက်။',null)
,(2520,3,1,'လယ်ကွက်။','(ကြိ) စျေးပိုပေးသည်၊ တိုးပေးသည်။')
,(2520,3,1,'လယ်ကွက်။','ခံက်ကဵုၚုဟ် = စျေးနှုန်းတိုးမြှင့် ပေးသည်။')
,(2520,3,1,'လယ်ကွက်။','ခံက်ရာန် = စျေးနှုန်းတိုးပေး၍ဝယ်သည်။')
,(2521,3,1,'လယ်ကွက်အလတ်စား။',null)
,(2522,3,1,'တလင်းလုပ်ထားသောလယ်ကွက်။',null)
,(2523,3,1,'ရေနက်လယ်ကွက်။',null)
,(2524,3,1,'လက်ခုပ်။',null)
,(2525,3,1,'တစ်ဆစ်ချိုးလယ်ကွက်။',null)
,(2526,3,4,'တစ်ဖက်သားစိန်ခေါ်သည်ကို လက်ခံကြောင်းပြန်ပြောသည်။ ယှဉ်ပြိုင်ရန် သ ဘောတူသည်။ (?)',null)
,(2527,3,1,'ကြဲခင်းလယ်ကွက်။',null)
,(2528,3,1,'စိုက်ခင်းလယ်ကွက်။',null)
,(2529,3,1,'လယ်ကွက်။',null)
,(2530,3,1,'ပျိုးခင်းလယ်ကွက်။ မျိုးကြဲလယ်ကွက်။',null)
,(2531,3,5,'ထိုကဲ့သို့။ ထိုအတိုင်း။',null)
,(2532,3,5,'ဤကဲ့သို့။ ဤအတိုင်း။',null)
,(2533,3,16,'ဘယ်ကဲ့လို။ ဘယ်လို။',null)
,(2534,3,4,'သံသယဖြစ်သည်။',null)
,(2535,3,1,'ချည်ခင်။',null)
,(2536,3,1,'ချည်ခင်ရစ်ဘီးဝင်ရိုး။',null)
,(2537,3,1,'အခန်း။ အဆောင်ခန်း။',null)
,(2538,3,13,'(န) ခုံ။ စားပွဲ။','ခုၚ်ဂ္ဇအ် = ထိုၚ်ခုံ။')
,(2538,3,13,'(န) ခုံ။ စားပွဲ။','ခုၚ်ဝိုၚ် = စားပွဲဝိုင်း။')
,(2538,3,13,'(န) ခုံ။ စားပွဲ။','ခုၚ်စပုၚ် = ထ မင်းစားပွဲ။')
,(2538,3,13,'(န) ခုံ။ စားပွဲ။','ခုၚ်ဒလာဲ = အမှီရှိသောထိုၚ်ခုံ။ ကုလားထိုၚ်။')
,(2539,3,4,'မညီမညာဖြစ်သည်။ အဖုအထစ်ဖြစ်သည်။',null)
,(2540,3,4,'သန်သည်။ ကျွမ်းကျင်သည်။','“ဗှ်ေခံၚ်တဲပုၚ်ဟာ ခံၚ်တဲပါဲဟာ။” = “မင်းဗယ်လက် သန်သလား၊ ညာလက်သန်သလား။”')
,(2540,3,4,'သန်သည်။ ကျွမ်းကျင်သည်။','“အဲဟီုအရေဝ်ဗၟာ ဟွံခံၚ်ကွေံကွေံရ။” = “ငါမြန်မာစ ကားပြော သိပ်မကျွမ်းကျင်ဘူး။”')
,(2541,3,4,'ခိုၚ်သည်။ မြဲမြံသည်။',null)
,(2542,3,4,'ခိုင်ခံ့သည်။','“ပြတရၚ်ဍုၚ်တက္ကသဵုဂှ် ခိုၚ်ကၠိုက်ဗိုန်က္ညန်သန်—။” (ဇ—၂၂၉။ အစွောံ။) = “တက္ကသိုလ်ပြည်၏ မြို့တံခါးမျှောၚ်စင်သည် အလွန်ခိုင်ခံ့မြဲမြံ၏။”')
,(2543,3,4,'ခိုင်မြဲသည်။',null)
,(2544,3,1,'ကြွေ။','ခတ်တမၠိုဟ် = ကြွေပေါက်။')
,(2544,3,1,'ကြွေ။','(ကြိ) (အရည်)ပျစ်သည်။')
,(2544,3,1,'ကြွေ။','“ဍာ်ကဝ်ဏအ်ခတ် လောန်အာရ။” = “ဤထန်းလျက်ရည်သည် ပျစ်လွန်းသည်။”')
,(2545,3,4,'၁။ ကြပ်တည်းသည်။','၂။ ရှားပါးသည်။')
,(2546,3,1,'ကတ်ကြေး။',null)
,(2547,3,10,'(န) မင်းမျိုး။ ခတ္တိယအနွယ်။',null)
,(2548,3,10,'(န) မင်းမျိုးမင်းနွယ်ဖြစ်သောသတို့သမီး။ မင်းသမီး။',null)
,(2549,3,1,'ကြွေအန်။','ဝေၚ်ခတ်ပး = ကြွေအန်ကစားသည်။')
,(2550,3,1,'(အိပ်ရန်) ခုတၚ်။','(ကြိ) (လုံချည်၊ ထဘီသည်) မြှင့်တၚ်၍ဝတ်သည်။ ခါးတောင်း ကျိုက်သည်။')
,(2550,3,1,'(အိပ်ရန်) ခုတၚ်။','ခါတ်လဝ်ဂၞိန် = ထမီကိုမြှင့်တၚ်ပြီး ဝတ်ထားသည်။')
,(2550,3,1,'(အိပ်ရန်) ခုတၚ်။','‘ကောန်ထပိုဲဂှ် ခါတ်လဝ် သပိုၚ်။’ = ‘ထိုကိုရၚ်လေးသည် သင်းပိုၚ်ကို တိုတိုဝတ်ထားသည်။’')
,(2551,3,4,'(လုံချည်) ခါးတောင်းကျိုက်သည်။',null)
,(2552,3,10,'(န) ကုန်းသောအထိန်းတော်မ။ ခါးကုန်းမ။','‘ပြဘာဝတဳကဵုခုဇ္ဇာ’ = ‘ပဘာဝတီမင်းသ မီးနှင့် ခါးကုန်းသောအထိန်းတော်မ။’')
,(2553,3,4,'၁။ ခေါ်တွင်သည်။ ခေါ်ဝေါ်သည်။ အမည်ပေးသည်။','၂။ (အလိုမပြည့်၍)စိတ်ကောက်သည်။')
,(2553,3,4,'၁။ ခေါ်တွင်သည်။ ခေါ်ဝေါ်သည်။ အမည်ပေးသည်။','“ကောန်ၚာ်ဂှ် ယာဲဍေံဟွံရာန်ကဵုကောန်ရုပ်ပွေၚ်တုဲ ခုတ်ဒၟံၚ်ကဵုယာဲဍေံရ။” = “ထိုက လေးငယ်သည် သူ့အမေက ကစားစရာအရုပ်မဝယ်ပေး၍ သူ့အမေကို စိတ်ကောက်နေသည်။”')
,(2554,3,4,'သမုတ်သည်။ ခေါ်တွင်သည်။ ခေါ်ဝေါ်သည်။',null)
,(2555,3,11,'(န) ခုဒ္ဒကနိကာယ်။ (သုတ္တန်ပိဋကတ်တော်အပိုင်းငယ်)',null)
,(2556,3,11,'(န) ခုဒ္ဒကပါဋ္ဌ်။ (သုတ္တန်ပိဋကတ်တော်အပိုင်းငယ်)',null)
,(2557,3,4,'အမည်ပေးသည်။ အမည်မှည့်သည်။','“မဟာသဳလဝ မိကဵုမခုတ်လဝ်ယၟု (ဗောဓိသတ်)ရ။” (ဇ—၅၁။ အစွောံ။) = “ဘုရားလောင်းအား မိဘတို့သည် မဟာသီလဝဟူ သောအမည်ကို မှည့်ကုန်၏။”')
,(2557,3,4,'အမည်ပေးသည်။ အမည်မှည့်သည်။','“ပဥ္စာဝုဓကုမာ ခုတ်ခဴလဝ်ယၟုဗောဓိသတ်ရ။” (ဇ—၅၅။ အ ေ')
,(2558,3,16,'ပဥ္စာဝုဓမင်းသားဟူသော အမည်ကိုမှည့်၏။” (ညောင်ကန်)',null)
,(2559,3,10,'(ကြိဝိ) ခဏ။ ခေတ္တ။',null)
,(2560,3,11,'(န) ၁။ ခေတ်ကာလ။','ခေတ်အေၚ်္ဂလိက် = မြန်မာပြည်ကို အၚ်္ဂလိပ်မင်းအုပ်စိုး သောခေတ်။')
,(2560,3,11,'(န) ၁။ ခေတ်ကာလ။','ခေတ်ဂျပါန် = မြန်မာပြည်ကို ဖက်ဆစ်ဂျပန်အုပ်စိုးသောခေတ်။')
,(2560,3,11,'(န) ၁။ ခေတ်ကာလ။','၂။ ဒေသနယ် ပယ်။ နယ်ပယ်အပိုင်းအခြား။ (ဇာတိခေတ်၊ အာဏာခေတ်၊ ဝိသယခေတ်ဟူ၍ သုံးပါးရှိသည်။)')
,(2561,3,1,'ယခင်ခေတ်။ ရှေးခေတ်။',null)
,(2562,3,1,'ခေတ်သစ်။',null)
,(2563,3,1,'ခေတ်ဟောင်း။',null)
,(2564,3,1,'ယနေ့ခေတ်။',null)
,(2565,3,1,'လေးဒေါဏရှိအခြၚ်အတွယ်။','‘ဒြိုန်’ ရှု။')
,(2566,3,11,'(န) အပိုင်း။ အခဏ်း။ (ပါဠိ—ခဏ္ဍ)',null)
,(2567,3,4,'၁။ (ရေစသည်) နောက်သည်။ နောက်ကျိသည်။ မကြည်။','“အဃောဍာ်ခန် လ္ပတုက် ဍာ်သွုၚ်ညိ။” = “ရေနောက်နေစဉ် သောက်ရေမခပ်ပါနှင့်။”')
,(2567,3,4,'၁။ (ရေစသည်) နောက်သည်။ နောက်ကျိသည်။ မကြည်။','၂။ (သွေးစသည်) စေးပျစ်သည်')
,(2567,3,4,'၁။ (ရေစသည်) နောက်သည်။ နောက်ကျိသည်။ မကြည်။','“ပ္ဍဲကာလဂှ် သၟတ်ဗြဴဒိဋ္ဌမၚ်္ဂလိကာဂှ် ဆီဥတုဆဒးဗၞတ် ဟွံခန်လောန် ဟွံဆာလောန်မဒှ်ရ။” (၅၅ဝ။ ဇ—၄၉၇။ ၇—၃၅၉။ အစွောံ။) = “ထိုကာ လ­ ဒိဋ္ဌမၚ်္ဂလိကာ သူငယ်မသည် ရာသီ သွေးအနေတော် မစေးပျစ်လွန်း မကျဲလွန်းဖြစ်၏။”')
,(2568,3,4,'ညစ်ပေနောက်ကျိသည်။',null)
,(2569,3,10,'(န)သည်းခံခြင်း။ ခန္တီ။',null)
,(2570,3,10,'(န) ၁။ (သတ္တဝါ၏) ခန္ဓာကိုယ်။','၂။ (ရုပ်နာမ်တရား) အစု။ (ရူပက္ခန္ဓာ၊ ဝေဒနက္ခန္ဓာ၊ သညက္ခန္ဓာ၊ သၚ်္ခါရက္ခန္ဓာ၊ ဝိညာဏက္ခန္ဓာဟူ၍ ငါးပါးရှိသည်။)')
,(2571,3,1,'ဒေသ။ နယ်ပယ်။','ခန်လွာဍုၚ်မန် = မွန်နယ်ပယ်။ မွန်ပြည်နယ်။')
,(2571,3,1,'ဒေသ။ နယ်ပယ်။','ခန်လွာမၞိဟ် = လူ့ရပ်ရွာ။ လူ့ရပ်ဋ္ဌာနေ။')
,(2571,3,1,'ဒေသ။ နယ်ပယ်။','“ယွံသုမုခ၊ ဋ္ဌာန်ခန်လွာမၞိဟ်တေံဂှ် မၞိဟ်တံဂှ် မၞုံကဵုဥပ္ပါဲဂၠိုၚ်သန်” ဗောဓိသတ်(သၟိၚ်ၜိုပ်ထဝ်)ဂး။ (ဇ—၅၃၄။ အစွောံ။) = “(ဟၚ်္သာစစ်သူကြီး)သုမုခ၊ လူ့ရပ်ရွာ ဋ္ဌာနေ­ လူတို့သည် များသောဥပါယ်တံမျဉ်ရှိကုန်၏” ဟုရွှေဟၚ်္သာမင်းဆို၏။')
,(2571,3,1,'ဒေသ။ နယ်ပယ်။','“သၟိၚ်မပိုၚ်ဇမ္မု ဒိတ်ဂှ် ကလိဂွံကောန်တြုံစှ်၊ ပ္ဍဲတ္ကအ်ဇမ္မုဒိတ် ပစှ်စွံ ပရအ်ကဵုကောန်တြုံစှ်ဂှ်။ — (ကောကဵုဒေံတံ ဂှ်) လအ်ညိအယုက်ဇၞော် အာဟွံဒှ်ရ။ အဲဒၟံၚ်ခန်လွာအဲ ညးဒၟံၚ်ခန်လွာညးရ။” (ဓမ္မသာတ်။ ၟဓထ Vဳဳြ၁ျ ပအဂြေ၃၁၃) = “ဇမ္ဗူဒိပ်ကိုပိုၚ်သောမင်းသည် သားယောကျာ်းဆယ်ယောက်ရ၏။ ဇမ္ဗူဒိပ်ကျွန်းကို ဆယ်စုခွဲ၍ သားဆယ်ယောက်တို့ကို ဝေငှပေး၏။ ထိုညီနောင်တို့သည် ကာ လကြာလတ်သော် အသက်ကြီး၍ မသွားနိုင်ကြတော့။ မိမိတို့၏နယ်ပယ်များ­သာ တသီးတခြား နေကြကုန်၏။”')
,(2572,3,1,'ဆရာ့ဆရာအတွက်ရည်စူး၍ တၚ်မြှောက်သော အုန်းငှက်ပျောမပါ ကွမ်းသီးကွမ်းရွက် စသည်တို့သာ ထည့်သောပွဲငယ်။','တၚ်ခါန် = ဆရာစားပွဲငယ်တၚ်သည်။')
,(2573,3,4,'(စစ်အင်အား) ပြင်ဆင်သည်။ စုဆောင်းသည်။ စုစည်းသည်။ စုရုံးစေသည်။','ညးစှ် ကောကဵုဒေံ ခါန်ကေတ်ဗဵုလဗးတုဲ “ပ္ဍဲဂၠးဇမ္ဗုဒိပ်ဝွံ ပိုဲအာဗတိုက်ကေတ်ညိ” ဂးတုဲ ဇက်တိတ်အာ နူဍုၚ်ရ။ (ဇ—၄၅၄။ အစွောံ။) = ထိုတစ်ကျိပ်သော မင်းညီနောင်တို့သည် စစ်တပ်ဗိုလ်ပါအၚ် အားစုစည်း၍ “ဇမ္ဗူဒိပ်ကျွန်းအလုံးကို တိုက်ယူကုန်အံ့” ဟု မြို့မှထွက်ချီကြကုန်၏။')
,(2573,3,4,'(စစ်အင်အား) ပြင်ဆင်သည်။ စုဆောင်းသည်။ စုစည်းသည်။ စုရုံးစေသည်။','“သၟိၚ် ကဵုခါန်မၞိဟ် သီုလွဟ်ဗၞုဟ်သ္ဇၚ်တုဲ ဗိုၚ်စၠောံလဝ်သုသာန် ဋ္ဌာန်ကလော်ဒမြိုဟ်ဂှ်ရ။” (ဇ—၅၁၃။ အစွောံ။) = “မင်းသည် လူများကိုစုရုံးစေပြီးလျှင် ဓါးလှံလက်နက်များနှင့်တကွ ထိုဘီလူးဆိုးရှိ ရာသုသာန်ကို ဝန်းရံစေ၏။”')
,(2574,3,4,'(ရာထူး)ခန့်အပ်သည်။ အလုပ်ခန့်သည်။','“သၟိၚ်ခါန်ကၞက်လဝ်ဗောဓိသတ် ပ္ဍဲဒဒှ် သေနာပတိရ။” = “ဘုရားလောင်းကို ဘုရင်က စစ်သေနာပတိအရာ­ ရာထူးခန့်အပ်ထားသည်။”')
,(2575,3,1,'ပွဲငယ်။ ဆရာစားပွဲငယ်။',null)
,(2576,3,4,'စစ်ပြင်ဆင်သည်။ စစ်အင်အားစုစည်းသည်။',null)
,(2577,3,1,'ဖြုတ်ကောင်တစ်မျိုး။','ခုန်ကိတ် = ဖြုတ်ကိုက်သည်။')
,(2577,3,1,'ဖြုတ်ကောင်တစ်မျိုး။','(ကြိ) စိုက်သည်။')
,(2577,3,1,'ဖြုတ်ကောင်တစ်မျိုး။','ခုန်လေံ = တုတ်စိုက်သည်။')
,(2577,3,1,'ဖြုတ်ကောင်တစ်မျိုး။','ခုန်ဒယိုၚ် = တိုင်စိုက်သည်။')
,(2578,3,3,'ညီညာသော။ တညီတညာတည်းဖြစ်သော။','(ကြိ) ညီညာအောင် ခုတ်ထစ်အနားသတ်သည်။')
,(2579,3,3,'အားလုံးသော။ အလုံးစုံသော။ ခပ်သိမ်း။',null)
,(2580,3,4,'ပဲ့သည်။','မြခိပ်အာ = ဓါးပဲ့သွားသည်။')
,(2580,3,4,'ပဲ့သည်။','ၚေက်ခိပ် = သွားကျိုးပဲ့သည်။')
,(2580,3,4,'ပဲ့သည်။','မြေၚက်ခိပ် = အသွားပဲ့နေသောဓါး။ (အခိပ် = ၚသွားကျိုး။')
,(2580,3,4,'ပဲ့သည်။','ဣခိပ် = သွားကျိုးမ။ မ သွားကျိုး။)')
,(2581,3,4,'(ကတ်ကြေးစသည်ဖြင့်)ညှပ်သည်။','ခေပ်ယာတ် = အဝတ်စကို ကတ်ကြေးဖြင့် ညှပ်သည်။')
,(2581,3,4,'(ကတ်ကြေးစသည်ဖြင့်)ညှပ်သည်။','ခေပ်သတ် = ကွမ်းသီးကို ကွမ်းညှပ်ဖြင့်ညှပ်သည်။')
,(2581,3,4,'(ကတ်ကြေးစသည်ဖြင့်)ညှပ်သည်။','ခေပ်သော် = ဆံပင်ညှပ်သည်။')
,(2581,3,4,'(ကတ်ကြေးစသည်ဖြင့်)ညှပ်သည်။','ခေပ်သၞေမ်တဲ = လက်သည်းညှပ်သည်။')
,(2582,3,3,'ညစ်ပေသော။ ညစ်နွမ်းသော။','ယာတ်ခမၞက် = ညစ်နွမ်းသောအဝတ်။')
,(2582,3,3,'ညစ်ပေသော။ ညစ်နွမ်းသော။','“(ကောန် သေဋ္ဌဳဂှ် ဆဝေၚ်ဂြိုၚ်သုၚ်စဂှ် ဒြပ်တံဂှ်အိုတ်အာတုဲ) ဒိုက်ဒိန်ကၠၚ်ကၠောန်အာရ။ ဒးသပိုၚ်ယာတ် ခမၞက် ကြိုၚ်တဴရ။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုသူဌေးသားသည် ပျော်ပါးသောက်စားခြင်းဖြင့် သာလျှင် ဥစ္စာတို့သည်ကုန်၍ ဆင်းရဲအထီးကျန်သည်ဖြစ်၍ ပုဆိုးနွမ်းကိုဝတ်လျက် သွားရ၏။”')
,(2583,3,1,'ထိခိုက်ခံစားလွယ်သောစိတ်။ (?)',null)
,(2584,3,1,'အကျဉ်း။ အကျဉ်းချုပ်။',null)
,(2585,3,5,'အကျဉ်းအားဖြင့်။','“ယွံခမဳတံ၊ အဲဟီုဗွဲခမၞောန်တုဲ ဗွဲတရး သာရိပိုတ် ဂွံတိတ်ဟီုတွံကဵုညးဂှ် ဆလၟုဟ်ဝွံဟွံသေၚ်၊ နူမတုဲတေံရ” ကျာ်တြဲဂး။ (ဇ—၉၉။ အစွောံ။) = “ရဟန်းတို့၊ သာရိပုတ္တရာသည် ယခုအခါ­သာလျှင် ငါဘုရားသည် အကျဉ်းအားဖြင့် ဟော တော်မူအပ်သောစကားကို အကျယ်အားဖြင့် ဆိုသည်မဟုတ်သေး။ ရှေး­လည်း ဆိုဘူးသလျှင်က တည်း။” (ညောင်ကန်)')
,(2585,3,5,'အကျဉ်းအားဖြင့်။','“ပ္ဍဲဒၞာဲဝွံ ဗွဲခမၞန် ပိုဲသ္ဂးကဵုရ။” (ဇ—၂၈၅။ အစွောံ။) = “ဤနေရာ­ အကျဉ်းအားဖြင့်ဆိုအံ့။”')
,(2586,3,1,'‘ကမၞုဲ’ ရှု။',null)
,(2587,3,1,'ယောက္ခမ။',null)
,(2588,3,1,'ယောက္ခမယောကျာ်းသူ။ ယောက္ခမယောကျာ်း။',null)
,(2589,3,1,'မိဘကဲ့သို့ ရိုသေအပ်သော ယောက္ခမများ။',null)
,(2590,3,1,'ယောက္ခမမိန်းမသူ။ ယောက္ခမမိန်းမ။',null)
,(2591,3,1,'ယောက္ခမအချင်းချင်း တော်စပ်ပုံ။ ခမည်းခမက်။',null)
,(2592,3,1,'လှေသၚ်္ဘောကုန်းပတ်။',null)
,(2593,3,4,'တူးသည်။','ခါဲတိ = မြေကြီးတူးသည်။')
,(2593,3,4,'တူးသည်။','ခါဲကမၠိုၚ် = ရေတွင်းတူးသည်။')
,(2593,3,4,'တူးသည်။','ခါဲကတိုၚ် = တွင်းတူးသည်။')
,(2593,3,4,'တူးသည်။','ခါဲမြံၚ် = မြောင်းတူးသည်။')
,(2593,3,4,'တူးသည်။','ခါဲဥမၚ် = ဥမၚ်လိုဏ်ခေါင်းတူးသည်။')
,(2593,3,4,'တူးသည်။','ခါဲသိုက် = သိုက်တူးသည်။ ရတနာသိုက်တူးသည်။')
,(2594,3,4,'လက်ယပ်ခေါ်သည်။',null)
,(2595,3,1,'နူနာရောဂါ။ နူနာရောဂါသည်။',null)
,(2596,3,1,'အကျည်။ တံခါးကျၚ်။ ကန့်လန့်ကျၚ်။ (တံခါးကိုပိတ်ရသော အချောင်း၊ အတံ။) (ပါဠိ —မိဍ္ဎိကာ)','မုဟ်ခါဲဗန် = အတွင်းနံရံအကျည်စွန်း။ (ပါဠိ—မိဍ္ဎန္တ)')
,(2596,3,1,'အကျည်။ တံခါးကျၚ်။ ကန့်လန့်ကျၚ်။ (တံခါးကိုပိတ်ရသော အချောင်း၊ အတံ။) (ပါဠိ —မိဍ္ဎိကာ)','“ဘိက္ခဝေ။ ယွံ(ခမဳတံ)။ မိ ဍ္ဎန္တေ။ ပ္ဍဲမုဟ်ခါဲဗန် (ပ္ဍဲမုဟ်ထၞဲလေဝ်ဂး။ ပ္ဍဲမုဟ်ထၞဲအာဠိန္ဒလေဝ်ဂး။ ပ္ဍဲမုဟ်ခါဲဗန် ဗွဲအပ္ဍဲဗဒၚ်လေဝ် ဂးရ။) ပတ္တော။ န်ဗဗေၚ်။ နနိက္ခိပိတဗ္ဗော။ စိုန်ဟွံဂပ်ဂဝ်စွံ။”(တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅ဝ၆။ စန္ဒိမာမဟာထေရ်။) (ခါဲဗန် = ထၞဲ)')
,(2597,3,1,'ခဲ။ ခဲမဖြူ။ သလွဲစင်။ သလွဲဖြူ။ (ပါဠိ—တိပု)','“(ညးဗၞိက်တံဂှ်) ခါဲစှ်ေကမၠိုၚ်ဂှ် လၟေၚ် လၟေၚ်တုဲ ဂွံခါဲမဒမျိုၚ် ဂွံခါဲမဗတာၚ် ခါဲစှ်ေဂွံသၠုဲဒမျိုၚ် ဂွံသၠုၚ်ဗကေတ် ဂွံသြန်ဂွံမၞိက်ဝေလုတုဲ—။” (ဇ—၂၅၆။ အစွောံ။) = “(ထိုကုန်သည်တို့သည်) တူးကုန်လတ်သော် အစဉ်သဖြင့် သလွဲစင်၊ သလွဲပုပ်၊ ကြေးပုပ်၊ ကြေးနီ ကြောင်မျက်ရွဲအပေါင်းတို့ကို ရကုန်၏။” (ညောင်ကန်)')
,(2598,3,1,'သလွဲပုပ်။ သလွဲမည်း။ ခဲမပုပ်။ ခဲမနက်။ (ပါဠိ—သဳသ)','“သဳသမယော။ ဍေံမတၟုဲ တဴနကဵုခါဲမဒမျိုၚ်။ (ဒကောဝ်ဒမျိုၚ်စိဂး။)” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅ဝ၃။ စန္ဒိမာမဟာ ထေရ်။) = “သလွဲမည်းဖြင့်ပြီးသော။ ခဲမပုပ်ဖြင့်ပြီးသော။” (ခါဲမဒမျိုၚ် = ဒကောဝ်ဒမျိုၚ်)')
,(2599,3,1,'သလွဲစင်။ ခဲမဖြူ။ သံဖြူ။ (ပါဠိ—တိပု)','“တိပုမယော။ ဍေံမတၟုဲတဴနကဵုခါဲမဗ္တာၚ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅ဝ၃။ စန္ဒိမာမဟာထေရ်။) = “ခဲမဖြူဖြင့်ပြီးသော။”')
,(2600,3,1,'ခါးပန်းကြိုး။',null)
,(2601,3,4,'ရွဲ့စောင်းသည်။ တစ်ဖက်စောင်းသည်။','“ဍေံဇိၚ်လဝ်ပလောအ်ဂှ် ခေဲါအာရ။” = “သူချုပ်ထားသောအင်္ကျီသည် တစ်ဖက်ရွဲ့စောင်းသွားသည်။”')
,(2602,3,1,'ငှက်ပျောရွက်ဖြင့် လုပ်ထားသော ခေါစာကျွေးသောခွက်။ ခေါခွက်။','ခဝ်စက္ခော =စက္ကူ ကတော့ခွက်။')
,(2602,3,1,'ငှက်ပျောရွက်ဖြင့် လုပ်ထားသော ခေါစာကျွေးသောခွက်။ ခေါခွက်။','ပုၚ်ခဝ် = ခေါစာပစ်ထမင်း။')
,(2602,3,1,'ငှက်ပျောရွက်ဖြင့် လုပ်ထားသော ခေါစာကျွေးသောခွက်။ ခေါခွက်။','(ကြိ) ၁။ ခေါစာခွက်လုပ်သည်။ ခွက်ကတော့ လုပ်သည်။')
,(2602,3,1,'ငှက်ပျောရွက်ဖြင့် လုပ်ထားသော ခေါစာကျွေးသောခွက်။ ခေါခွက်။','၂။ စဉ်းစားသည်။ တွေးတောသည်။ တွေးခေါ်သည်။ (‘တုဲခဝ်’၊ ‘ချပ်ခဝ်’ စသည် ဖြင့် တွေ့ရသည်။)')
,(2603,3,1,'အဖူးအငုံ။ ပန်းဖူးပန်းငုံ။ (?)','‘ဇဵုမုဟ်ညံၚ်ခဝ်ဇဝ်။’ = ‘ပန်းအဖူးအငုံကဲ့သို့သောနှာ တံ။’ (?)')
,(2604,3,4,'အတင်းဝင်လာသည်။ (ဒေါသမာန်ဖြင့်) ချဉ်းကပ်လာသည်။ အလျင်စလိုသွားသည်။','“ဂၠဴ ဒမျိုၚ်ပန်ဂှ် ဍေံသၟိက်ဇဵုဂးတုဲ ပ္ဍဲမုက်ရၚ်သၟိၚ်ဂှ် နူဒိုဟ်ပန်ဍေံခဵုကၠုၚ်တုဲ ဍေံဟွံဇဵုပၠန်တုဲ စ္ဍးအာကၠေံ ရ။” (လ္ပအ်သၟိၚ်ပဿိုန်) = “မျက်စင်းညိုအဆင်းရှိသော နွားနက်ဥဿဘလေးခုတို့သည် ဝှေ့ ကုန်အံ့ဟု အရပ်လေးမျက်နှာတို့မှ မင်းရင်ပြင်သို့ ဒေါသမာန်ဖြင့် လာလတ်ကုန်၍ မဝှေ့ဘဲ ဖဲခွါ ကုန်၏။” (ကောသလမင်းအိပ်မက်)')
,(2604,3,4,'အတင်းဝင်လာသည်။ (ဒေါသမာန်ဖြင့်) ချဉ်းကပ်လာသည်။ အလျင်စလိုသွားသည်။','“ညံၚ်ဇြုံဇာတ်မခဵုကၠုၚ်ကိတ်ညးဂှ်ရ ညးသ္ဍိုက်ဇြုံဇာတ်ဂှ်ဟွံ မွဲရ။” (ဇ—၁၄၉။ အစွောံ။) = “ကိုက်အံ့သောငှာ ရန်မူ၍ဝင်လာသော မြွေဟောက်ကဲ့သို့ ထို မြွေဟောက်ကို ချစ်နှစ်သက်သောသူမရှိ။”')
,(2604,3,4,'အတင်းဝင်လာသည်။ (ဒေါသမာန်ဖြင့်) ချဉ်းကပ်လာသည်။ အလျင်စလိုသွားသည်။','“လဗြဴဂှ် ခဵုတိုန်ၜှ်သၞေဝ် ပ္ဍဲလတူခြုံမွဲဂှ်တုဲ လောဒတုံ စှ်ေပ္ဍဲတိရ။” (ဇ—၅၂ဝ။ အစွောံ။)= “ထိုမိန်းမအိုသည် ဟင်းရွက်ခူးရန် ချုံတစ်ခုပေါ်သို့ အလျင် စလိုတက်လတ်သော် လိမ့်လျက်မြေ­ကျ၏။”')
,(2604,3,4,'အတင်းဝင်လာသည်။ (ဒေါသမာန်ဖြင့်) ချဉ်းကပ်လာသည်။ အလျင်စလိုသွားသည်။','“(တြုံမလုန်လန်ဂှ်) ဍေံခိုဝ်လုပ်အာတုဲ ပုၚ်မွဲ လၟံက် ဍေံၜိုတ်ကေတ်ပ္ဍဲထးထဝ်သၟိၚ်ဂှ်တုဲ ဍေံချအ်ပၠောပ်ဏာပါၚ်ဍေံရ။” (ဇ—၂၆ဝ။ အစွောံ။) = “ထိုလော်လည်သောယောကျာ်းသည် အလျင်အမြန်ဝင်သွားကာ မင်း၏စားတော်ရွှေခွက်မှ ထမင်း တစ်လုတ်ကို နှိုက်ယူပြီးလျှင် မိမိပါးစပ်ထဲ ထည့်သွင်း၍စား၏။”')
,(2605,3,4,'ကောင်းသည်။','(နဝိ) ကောင်းသော။')
,(2606,3,4,'ကောင်းစားသည်။','“အယုက်အဲလောန်အာမသုန်စှ်ောတုဲ အဲဂွံခိုဟ်စရောၚ် အ္စာဗေ ဒၚ်တွံလဝ်ရ။” = “ငါ့အသက်ငါးဆယ်ကျော်ပြီးလျှင် ငါကောင်းစားလိမ့်မည်ဟု ဗေဒၚ်ဆရာဟော ထားသည်။”')
,(2607,3,16,'(ကြိ) စိတ်ကောင်းထားသည်။ စိတ်ထားကောင်းစေသည်။','“ဖအောန် လောဘဒေါသညိ၊ ဖျဝ်မာနညိ၊ ခိုဟ်စိုတ်ညိ။” = “လောဘဒေါသကို လျှော့ပါ၊ မာနကို နှိမ့်ချ ပါ၊ စိတ်ကောင်းထားပါ။”')
,(2608,3,4,'ကောင်းသင့်သလောက်ကောင်းသည်။ (စကား) ကောင်းသားပဲ။',null)
,(2609,3,4,'ကောင်းမွန်သည်။',null)
,(2610,3,4,'ကောင်းမွန်သည်။','“(ဗမၞိဟ်ဗြဴဂှ် ဒှ်)ယဲကျာမ္ဂးဂှ်ရောၚ်လေဝ် သာ်ဇကုစၞာံဇကုလေဝ် ခိုဟ်ရိုဟ်ဒၟံၚ်။ ဒမံၚ်ယဲဂှ်လေဝ် ဟွံပြာကတ်ညိအဴ။” (ဇ—၁၃ဝ။ အစွောံ။) = “ပုဏ္ဏေးမသည် လေထိုးကျင့်နာဖြစ်သည်ဆိုသော်လည်း အရောင်အဆင်း အသားအရေလည်း ပကတိကောင်းမွန် နေ၏။ ရောဂါရှိခြင်းသည် မထင်ရှားပါ။”')
,(2610,3,4,'ကောင်းမွန်သည်။','“(ကောန်တြုံသၟိၚ်မကြံၚ်မ္ၚိုဟ်သ္ကာတ်မြဟ်ဂှ်) ပတွဵုနူ ဂွံမိၚ်ဒလောအ်ဗ္တောန်ဗောဓိသတ်တုဲ — နွံကဵုခန္တဳမေတ္တာကရုဏာစိုတ်တုဲ သတပ်သတးခိုဟ်ရိုဟ်အာ ရ။” (ဇ—၁၄၉။ အစွောံ။) = “ကြမ်းကြုတ်ရုန့်ရင်းသော မင်းသားငယ်သည် ဘုရားလောင်း၏ အဆုံးအမကို နာရသည်မှစ၍ ခန္တီ၊ မေတ္တာ၊ ကရုဏာစိတ်တို့နှင့် ပြည့်စုံသည်ဖြစ်၍ ဆိုးပြစ်များ ပပျောက်၍ ပကတိကောင်းမွန်သွား၏။”')
,(2611,3,4,'စိတ်ဓါတ်ကျဆင်းသည်။ စိတ်အားလျော့သည်။ စိတ်ညှိုးနွမ်းသည်။',null)
,(2612,3,4,'ခြေထောက်ထော့နဲ့ထော့နဲ့ဖြစ်သည်။','ခေအ်အာ = ထော့နဲ့ထော့နဲ့ဖြင့်သွားသည်။')
,(2612,3,4,'ခြေထောက်ထော့နဲ့ထော့နဲ့ဖြစ်သည်။','“(စိၚ်ဂှ် ဇိုၚ်ဂိအာမွဲဒိုဟ်တုဲ) နဇိုၚ်ပိ ခေအ်အာရ။” (ဇ—၁၅၆။ အစွောံ။) = “ထိုဆင်သည် ခြေ တစ်ဖက်နာသွားသဖြင့် ခြေသုံးချောင်းဖြင့် ထော့နဲ့ထော့နဲ့သွား၏။”')
,(2613,3,4,'ထောက်သည်။ ခုသည်။ (တံ ပရံပ ုပ)','“ဇိုၚ်ဇံၚ်ပုၚ်ဂှ် ဂၠေံဒၟံၚ်မွဲဒိုဟ်၊ ခေါအ် ထောံကဵုဂတှ်ေဆုညိ။” = “ထမင်းစားပွဲသည် ခြေတစ်ချောင်းတိုနေသည်၊ (ညီအောင်)သစ်ပြား ဖြင့် ခုလိုက်ပါ။”')
,(2613,3,4,'ထောက်သည်။ ခုသည်။ (တံ ပရံပ ုပ)','“ဇိုၚ်ဇံၚ်မွဲဂှ်ဂၠေံအာတုဲ ဂၠာဲဟွံဂွံတုဲ နကဵုဒဳမၚ်ဗၠာဲ ခေါအ်လဝ်တုဲ မၚ်ဗၠာဲဂ္ဇအ်ဒၟံၚ် ရ။” (ဇ—၁၂၃။ အစွောံ။)')
,(2614,3,1,'(ဝါး)အကြော။','ခၞဒုန် = ဝါးအကြော။')
,(2615,3,1,'မီးဇာ။',null)
,(2616,3,4,'(အရောင်)ပြိုးပြက်သည်။ ဝင်းလက်သည်။',null)
,(2617,3,4,'ဆီနှင့်ကြော်သည်။','ခၞာက = ငါးကြော်သည်။')
,(2617,3,4,'ဆီနှင့်ကြော်သည်။','(န) အကြော်။')
,(2617,3,4,'ဆီနှင့်ကြော်သည်။','ကခၞာ = ငါးကြော်။')
,(2618,3,1,'နှဲ။',null)
,(2619,3,1,'မုန့်တီ။ မုန့်ဟင်းခါး။',null)
,(2620,3,4,'ဆောက်လုပ်သည်။ တည်ဆောက်သည်။ ဖန်တီးသည်။','“ပ္ဍဲဘာရာဇာကာရ သၟိၚ်ပဿိုန်မခၞံ—။” (ဇ—၁၅၅။ အစွောံ။) = “ပသေနဒီကောသလမင်းကြီးသည် ဆောက်လုပ် အပ်သော ရာဇိကာရုံ­—။” (ညောင်ကန်)')
,(2620,3,4,'ဆောက်လုပ်သည်။ တည်ဆောက်သည်။ ဖန်တီးသည်။','“(ဗောဓိသတ်သၟာတၟအ်) ခနှံဂိုဟ်သုမ္မထိုက်။” (ဇ— ၁၃၇။ အစွောံ။) = “ဘုရားလောင်းကျောက်သမားသည် ဖန်ဂူကို ဆောက်လုပ်၏။”')
,(2620,3,4,'ဆောက်လုပ်သည်။ တည်ဆောက်သည်။ ဖန်တီးသည်။','“(ဗောဓိ သတ်သၟိၚ်ဒကောတ် တၞဟ်နဗလးဘဲအနာဂတ်) ပ္ဍဲသ္ကဲမွဲ ဂမြေၚ်ကျာမွဲ ခနှံလဝ်ရ။” (ဇ—၁၄၁။ အစွောံ။) = “ဘုရားလောင်းဖွတ်မင်းသည် အနာဂတ်ဘေးမှ လွှတ်ရန်အလို့ငှာ တွင်းနံပါးတစ်ဖက် ­ ကယ်ပေါက်တစ်ခုကို ဖောက်လုပ်ထား၏။”')
,(2621,3,1,'သေးသေးတၚ်။ အက္ခရာ၏အထက်တွင် မွန်(အံ)သရရအောင် သၚ်္ကေတအဖြစ်ရေး သော အစက်အပြောက်။ —ံ။',null)
,(2622,3,1,'ကြာဆံ။ ခေါက်ဆွဲ။',null)
,(2623,3,1,'မြူစွမ်။',null)
,(2624,3,4,'ချစ်ခြင်းမေတ္တာတည်ဆောက်သည်။',null)
,(2625,3,4,'အင်အားစုစည်းသည်။',null)
,(2626,3,4,'ကျမ်းပြုသည်။',null)
,(2627,3,4,'ဥပါယ်ဖွဲ့သည်။',null)
,(2628,3,4,'ပြုလုပ်ဖန်တီးသည်။ ပြုစုရေးသားသည်။','“သၟိၚ်ပလံၚ်ဏာဣသိ (ပ္ဍဲဥဒျာန်)တုဲ ခၞံအ ဿမာပိုတ်တုဲ ဋ္ဌာန်ဗ္တံကီု ဋ္ဌာန်တ္ၚဲကီု ခၞံဗဒှ်ကဵုတုဲ—။” (ဇ—၁၄၉။ အစွောံ။) = “မင်းသည် ရ သေ့အား ဥယျာဉ်တော်သို့ ပို့ဆောင်၍ ကျောင်းသၚ်္ခမ်းဆောက်လုပ်၍ ညဉ့်သန့်စရာ နေ့သန့်စ ရာအရပ်တို့ကို ဆောက်လုပ်ဖန်တီးပေး၏။”')
,(2628,3,4,'ပြုလုပ်ဖန်တီးသည်။ ပြုစုရေးသားသည်။','“သုတ်ဇာတ်မသုန်ကၠံမသုန်စှ်ော နဘာသာမန်ဂှ် ကျာ်ဇၞော်အစွောံ စီရေၚ်ခၞံဗဒှ်လဝ်ရ။” = “မွန်ဘာသာဇာတ်တော်ငါးရာ့ငါးဆယ်ကို ဝေါဆရာ တော်ဘုရားကြီး စီရၚ်ပြုစုထားသည်။”')
,(2629,3,4,'ထောင်းသည်။ တံတောင်နှင့်တွက်သည်။','ထၞက်မြေက် = ၚရုပ်သီးထောင်းသည်။')
,(2629,3,4,'ထောင်းသည်။ တံတောင်နှင့်တွက်သည်။','“ဍေံထၞက်စုတ်အဲရ။” = “သူငါ့ကို တံတောင်နှင့်တွက်သည်။”')
,(2630,3,1,'အမှုန့်။','ခၞိက်မြေက် = ၚရုပ်သီးမှုန့်။')
,(2630,3,1,'အမှုန့်။','ခၞိက်တိ = မြေမှုန့်။')
,(2630,3,1,'အမှုန့်။','ခၞိက် ဇိုၚ်= ခြေဖဝါးတွင်ကပ်သောမြေမှုန့်။')
,(2630,3,1,'အမှုန့်။','ခၞိက်သ္ၚု = ဆန်မှုန့်။')
,(2630,3,1,'အမှုန့်။','ခၞိက်ဂဥုဲ = ဆေးမှုန့်။')
,(2630,3,1,'အမှုန့်။','ခၞိက်ၜဲ = ပဲမှုန့်။')
,(2630,3,1,'အမှုန့်။','“ဒမာတ်မွဲဂှ် ဍေံကၠောန်သၞာ်တုဲ အပ္ဍဲကၞပ်သၞာ်ဂှ် ကၞိက်မြေက်ဇိပ်ဂၠိပ် ဍေံစုတ်လဝ်တုဲ —။” (ဇ—၁၂၆။ အစွောံ။) = “တစ်ယောက်သောပန်းဘဲသည် သန်လျက်ကိုပြု၍ သန်လျက် အိမ်­ သိမ်မွေ့သောငြုတ်မှုန့်ကို ထည့်၍—။” (ညောင်ကန်)')
,(2631,3,4,'ကန်ကျောက်သည်။',null)
,(2632,3,1,'ကုလားတက်။ တုံး။ ခလောက်။','ခၞုက်ကဵုပိုန် = ဘုန်ကြီးဆွမ်းဘုဉ်းရန်ခေါက်သောကု လားတက်။')
,(2632,3,1,'ကုလားတက်။ တုံး။ ခလောက်။','ခၞုက်ဂၠဴ = နွားခလောက်။')
,(2633,3,1,'ဝဲခြောက်၊ ယားနာ။',null)
,(2634,3,4,'ရှားပါးသည်။',null)
,(2635,3,1,'ဟင်းဂလာ။','(နဝိ) သေးသွယ်သော။')
,(2635,3,1,'ဟင်းဂလာ။','ဂၞိၚ်မခၞာၚ်= သေးသွယ်သောခါး။')
,(2635,3,1,'ဟင်းဂလာ။','‘သၞာၚ်’ ရှု။')
,(2636,3,1,'ခေါင်းလောင်း။',null)
,(2637,3,1,'ပရစ်ကောင်။',null)
,(2638,3,1,'ဝဲ။ ဝဲဂယက်။','“ရာဒနာသၟိက်ဂွံတိတ်ဗၠးနူ ဝဲခၞံၚ်သြဃသံသာ” = “သံသရာဝဲ သြဃမှ လွတ်မြောက်ရပါစေကြောင်း ဆုတောင်း၏။”')
,(2638,3,1,'ဝဲ။ ဝဲဂယက်။','“ဗြဴမ္ဂးဂှ် ဍေံဗဂေတ်ကၠေံစိုတ်ညး ညံၚ်ရဴ ကဏှံၚ်ကီု။” (ဇ—၂၆၃။ အစွောံ။) = “မိန်းမတို့သည် ဝဲဂယက်ကဲ့သို့ လည်စေတတ်ကုန်၏။”')
,(2639,3,1,'ပက်ခွန့်။','‘သၞာတ်’ ရှု။')
,(2640,3,4,'(သန်းစသည်ကို) လက်သည်းစွန်းဖြင့် ဖိညှစ်သတ်သည်။','ခၞောတ်စဲ = သန်းကို လက်သည်းဖြင့် ဖိနှိပ်သတ်သည်။')
,(2641,3,4,'၁။ သေးသွယ်သည်။ ရှူးသည်။','“ဇြုံမ္ဂးဂှ် လ္ပာ်ဗတဍေံ ခၞောတ်စှ်ေ အာရ။” = “မြွေမည်သည် အမြီးပိုင်းသေးသွယ်သွားသည်။”')
,(2641,3,4,'၁။ သေးသွယ်သည်။ ရှူးသည်။','၂။ အဆုံးပိုင်းသို့ရောက်သည်။ နှောင်းပိုင်းသို့ရောက်သည်။')
,(2641,3,4,'၁။ သေးသွယ်သည်။ ရှူးသည်။','သာသနာသဏောတ်စှ်ေ = သာသနာနှောင်းပိုင်းသို့ရောက်သည်။')
,(2642,3,4,'၁။ ကျိုချက်သည်။ တေသည်။','ခၞာန်ကဝ် = ထန်းလျက်ကျိုသည်။ ထန်းလျက်တေသည်။')
,(2642,3,4,'၁။ ကျိုချက်သည်။ တေသည်။','၂။ ကူးစက်သည်။ ပျံ့နှံ့သည်။')
,(2642,3,4,'၁။ ကျိုချက်သည်။ တေသည်။','ယဲခၞာန် = ရောဂါကူးစက်သည်။')
,(2642,3,4,'၁။ ကျိုချက်သည်။ တေသည်။','‘သၞာန်’ ရှု။')
,(2643,3,1,'ငါးမျှာချိတ်။',null)
,(2644,3,1,'ဒန့်တလွန်ပင်။','သတ်ခၞာဲ = ဒန့်တလွန်သီး။')
,(2645,3,1,'နှဲ။',null)
,(2646,3,1,'ဟင်းသီးဟင်းရွက်။',null)
,(2647,3,1,'ဟင်းသီးဟင်းရွက်။',null)
,(2648,3,1,'ကိနနရာ၊ ကိနနရီ။',null)
,(2649,3,4,'မျှစားသည်။ အတိုင်းအတာနှင့် ပြုလုပ်သည်။','ခၞေဟ်စ = မျှစားသည်။ အတိုင်းအ တာနှင့်စားသည်။')
,(2650,3,1,'၁။ ခမည်း။ (စတိလက်ဆောင်)','၂။ ငှက်ပျောအုန်းပါသောပွဲလတ်။')
,(2651,3,1,'ရဟန်း။','‘ခမဳ’')
,(2651,3,1,'ရဟန်း။','‘ခမှဳ’')
,(2651,3,1,'ရဟန်း။','‘ဂမှဳ’')
,(2651,3,1,'ရဟန်း။','‘ဂမဳ’ ရှု။')
,(2652,3,4,'အသည်းယားသည်။ အသည်းထိတ်သည်။',null)
,(2653,3,4,'လိပ်သည်။','ခၟောဒကဝ် = ဖျာလိပ်သည်။')
,(2653,3,4,'လိပ်သည်။','ခၟောၜံက် = ဆေးလိပ်လိပ်သည်။')
,(2654,3,1,'တင်းတိပ်။ (မျက်နှာပေါ်တွင်ဖြစ်ပေါ်သော ညိုမည်းသောအပြောက်)',null)
,(2655,3,1,'နှုတ်သီး။','ခၟဴအဒါ = ဝမ်းဘဲနှုတ်သီး။')
,(2656,3,1,'အဆိုတော်။',null)
,(2657,3,1,'ထိကရုံး။ (ပါဠိ—ဂဏ္ဍကာရဳ)','ခၟက်ဂၠဴ = ကွင်းထိကရုံး။ (ဟင်းချိုရွက်အဖြစ် ကျေး လက်ဒေသတွင် စားသုံးကြသည်။)')
,(2657,3,1,'ထိကရုံး။ (ပါဠိ—ဂဏ္ဍကာရဳ)','ခၟက်တောဝ် = ရေထိကရုံး။ (တို့စရာအဖြစ် စားသုံးကြသည်။)')
,(2658,3,4,'ဟပ်သည်။','ကၠဵုခၟက်စပုၚ် = ခွေးက ထမင်းကို ဟပ်ပြီးစားသည်။')
,(2659,3,4,'ထောင်းသည်။','ခၟုက်မြေက် = ၚရုပ်သီးထောင်းသည်။')
,(2660,3,1,'၁။ ခမောက်။','၂။ အခေါင်း။')
,(2660,3,1,'၁။ ခမောက်။','ခၟော်ဆု၊ ခၟံက်ဆု = သစ်ခေါင်း။')
,(2660,3,1,'၁။ ခမောက်။','ခၟံက်ဇြုံ = မြွေနေသောသစ်ခေါင်း။')
,(2661,3,1,'ပါးစောၚ်ရိုး။','ယဲခၟၚ်ကၠိက် = ပါးချိတ်ရောၚ်နာ။')
,(2662,3,1,'အခကြေးငွေ။','လိၚ်ခၟာၚ် = လုပ်ခကြေးငွေ။ ငှားရမ်းခ။')
,(2663,3,1,'ခေါင်းဗေါင်း။','ခၟိၚ်က္ဍိုပ် = (ကြိ) ခေါင်းဗေါင်းပေါင်းသည်။')
,(2664,3,4,'ဆင်သည်။ ဆင်တူသည်။','“သၟတ်တြုံဏအ် ရုပ်ဍေံသၟုၚ်ဒၟံၚ်ကဵုဒေံအဲရ။” = “ဤသူငယ်သည် ကျွန်တော့်ညီနှင့် ရုပ်ချင်းဆင်သည်။”')
,(2665,3,4,'(ကျာပွတ်ဖြင့်) ရိုက်နှက်သည်။','လေံခၟေတ် = ကျာပွတ်။')
,(2666,3,4,'ဆုပ်လုံးသည်။','(န) တစ်ဆုပ်။')
,(2666,3,4,'ဆုပ်လုံးသည်။','ပုၚ်ၜါခၟောတ် = ထမင်းနှစ်ဆုပ်။')
,(2667,3,1,'ပုရွက်ဆိတ်။','ခၟောတ်တိုန် = ပုရွက်ဆိတ်တက်သည်။')
,(2667,3,1,'ပုရွက်ဆိတ်။','ခၟောတ်တၞဴ = အ ဆိပ်ပြင်းသော ပုရွက်မည်းတစ်မျိုး။')
,(2667,3,1,'ပုရွက်ဆိတ်။','ခၟောတ်အကၠေၚ် = အဆိပ်ပြင်းသော ပုရွက်နီတစ်မျိုး။')
,(2668,3,4,'လက်ဖြင့်ဆုပ်သည်။','(စည်း) လက်ဖြင့်ဆုပ်သောအဆုပ်ကို ရေတွက်ရာတွင် သုံးသော စကားလုံး။')
,(2668,3,4,'လက်ဖြင့်ဆုပ်သည်။','ကမၠေၚ်ၜါခၟိုန် = ကောက်ညှင်းနှစ်ဆုပ်။')
,(2669,3,1,'မေးရိုး။','သော်ခၟိပ် = မုတ်ဆိတ်မွေး။')
,(2670,3,1,'အငုံအဖူး။','ခၟောံမၠဵု = စံပယ်ငုံ။')
,(2670,3,1,'အငုံအဖူး။','“နထးထဝ်အနဂ္ဃၚုဟ်ဂှ် ကဵုစုတ်လဝ်ပုၚ် ညံၚ် ခၟောမ်မၠဵုတုဲ—။” (ဇ—၂၆ဝ။ အစွောံ။) = “အဘိုးအနဂ္ဃထိုက်သောရွှေခွက်­ စံပယ်ငုံနှင့်တူသော ထမင်းကို ထည့်ထားစေ၍—။”')
,(2671,3,1,'(= သၟိပ်တဲ) လက်အုပ်။ (ပါဠိ—အဥ္ဇလဳ)','ခၠအ်ခၟောံတဲ = လက်အုပ်ချီသည်။')
,(2672,3,1,'ရေပွက်။ (ပါဠိ—ဥဒကတာရက)',null)
,(2673,3,1,'၁။ (ကြက်ဘဲစသည်၏) ဥ။','၂။ (အပင်၏) ဥ။')
,(2673,3,1,'၁။ (ကြက်ဘဲစသည်၏) ဥ။','(ကြိ) ဥဥသည်။')
,(2674,3,16,'',null)
,(2676,3,16,'',null)
,(2677,3,16,'',null)
,(2680,3,16,'',null)
,(2682,3,1,'ဖားဥ။ (စိုထိုင်းမှုကြောင့် အဝတ်အထည်တွင် ဖြစ်ပေါ်သောအမည်းစက်များ။)','ခၟာဲၚဴ တိုန်၊ ဒှ်ခၟာဲၚဴ = ဖားဥစွဲသည်။')
,(2683,3,1,'(သမင်၊ ဒရယ်၊ ချေစသည် ထောၚ်ဖမ်းရန်) ဝါးချွန်၊ သစ်ချွန်။',null)
,(2684,3,1,'နှပ်။ နှာရည်။',null)
,(2685,3,3,'‘ခမိဟ်’ ရှု။',null)
,(2686,3,1,'သစ်ချပင်။ ယမနေပင်။','သတ်ချ = သစ်ချသီး။ ယမနေသီး။')
,(2686,3,1,'သစ်ချပင်။ ယမနေပင်။','ချကၠိက် = ဝက်သစ်ချ။')
,(2687,3,1,'နှီး။ (ချည်ရန်)',null)
,(2688,3,4,'လှုပ်သည်။ တုန်သည်။',null)
,(2689,3,4,'လှုပ်ခါသည်။ တုန်ခါသည်။',null)
,(2690,3,4,'လှုပ်ရှားသည်။ တုန်လှုပ်သည်။','“ဗောဓိသတ်(သၟိၚ်ဒြာဲ)တုန်ဂှ် ဗယာပ် ဒၟံၚ်မေတ္တာ ပ္ဍဲသၟိၚ်ဂှ်တုဲ ဖျာံဒုၚ်လဝ်ထကဲတုဲ ဟွံဂွံချဳဂရာၚ်သက်က်ရ။ သၟိၚ်ဖျာံလဝ်တ္ၚပန်ဂှ်လေဝ် နအနုဘဴမေတ္တာဗောဓိသတ်တုဲ တလိုဟ်တ္ၚဂှ် ဟွံမာန်သက်က်ရ။” (၅၅ဝ။ ဇ—၃၈၅။ ဒု—၄ဝ၃။ အစွောံ။) = “(ဘုရားလောင်းသမင်မင်းသည်) မေတ္တာကို ရှေ့ထားသည်ကိုပြု၍ လက်ယာနံပါး ဖြင့်ခံ၍ မတုန်မလှုပ်လျက်လျှင်နေ၏။ မင်းသည် ထိုသမင်မင်း၏ မေတ္တာအာနုဘော်ကြောင့် မြှား ကိုလွှတ်အံ့သောငှာ မတတ်နိုင်။” (၅၅ဝ။ တ—၁၇၅။ ညောင်ကန်။)')
,(2691,3,4,'တုန်ခါသည်။',null)
,(2692,3,4,'တုန်လှုပ်သည်။ လှုပ်ရှားတုန်ခါသည်။','“နကြဳဇှ်သဳလရသိတံဂှ် သၞာသၟိၚ်ဣန်ချဳတမ္ညဝ် တဴရ။” (ဇ—၂၈၁။ အစွောံ။) = “ရသေ့အပေါင်း၏ သီလတန်ခိုးအားဖြင့် သိကြားနေရာသည် လှုပ်၏။” (ညောင်ကန်)')
,(2693,3,4,'(စိတ်)လှုပ်ရှားသည်။ မတည်မငြိမ်ဖြစ်သည်။','“ယွံတၠအဲ၊ ဗြဴစိုတ်သမၠီုဒမၠု စိုတ်ချဳလ ရုတဴ တၠအဲမ္ဂးဂှ် လ္ပဟီုညိ။” (ဇ—၅၃၆။ အစွောံ။) = “အဆွေ၊ မိန်းမမည်သည် မိုက်မဲတွေဝေ၍ စိတ်လှုပ်ရှားတတ်၏ဟု မဆိုပါလေနှင့်။”')
,(2694,3,4,'လှုပ်ရှားသည်။',null)
,(2695,3,4,'လှုပ်ခါသည်။ တုန်လှုပ်သည်။',null)
,(2696,3,1,'ထိုးဝါး။','(ကြိ) ၁။ ရေးသည်။')
,(2696,3,1,'ထိုးဝါး။','ချူလိက် = စာရေးသည်။')
,(2696,3,1,'ထိုးဝါး။','ချူရုပ် = အရုပ်ရေးသည်။')
,(2696,3,1,'ထိုးဝါး။','၂။ သွေးသည်။')
,(2696,3,1,'ထိုးဝါး။','ချူမြ = ဓါးသွေးသည်။')
,(2696,3,1,'ထိုးဝါး။','၃။ ေငါထွက်သည်။ ရှည်ထွက်သည်။ မို မောက်သည်။')
,(2696,3,1,'ထိုးဝါး။','ကၞေၚ်ချူ = နဖူးမိုမောက်သည်။')
,(2696,3,1,'ထိုးဝါး။','ၚေက်ချူ = သွားခေါသည်။')
,(2696,3,1,'ထိုးဝါး။','ညးမၞုံေၚက်မ ချူ = သွားခေါသောသူ။ (ပါဠိ—ဒန္တုရ)')
,(2697,3,4,'စကားလုံးရေးထုံးနှင့်အညီ တွဲဖက်ရေးသားသည်။',null)
,(2698,3,4,'ပါးစပ်ပြင်ထားသည်။ ပြန်ပြောရန် အသင့်ပြုထားသည်။ ပြန်ချေပရန် ပြင်ဆင်ထားသည်။',null)
,(2699,3,4,'ကျိန်ဆဲသည်။','‘ကသဴ’ (န) လည်းရှု။')
,(2700,3,4,'ကျိန်ဆဲသည်။ ဆဲရေးသည်။',null)
,(2701,3,1,'၁။ မီးသွေး။','၂။ မြည်းသတ္တဝါ။ (ပါဠိ—ခရ)')
,(2701,3,1,'၁။ မီးသွေး။','“ချးချိုတ်အာတုဲ ညးဗၞိက်ဂှ် ထောံလဝ်ချး တုဲ စ္ဍးအာကၠေံရ။” (ဇ—၁၈၉။ အစွောံ။) = “(မြည်းသေသည်ရှိသော်) ကုန်သည်သည်လည်း ထိုမြည်းကိုစွန့်၍ သွား၏။” (ညောင်ကန်) (‘ဂဒြဘ’၊ ‘မာဲ’ တို့နှင့်အတူတူ။)')
,(2702,3,1,'ကျောက်မီးသွေး။',null)
,(2703,3,4,'၁။ (ဝမ်း)ချုပ်သည်။','ဂၞဴချုက် = ဝမ်းချုပ်သည်။')
,(2703,3,4,'၁။ (ဝမ်း)ချုပ်သည်။','၂။ ချုက်ဆိုသည်။')
,(2703,3,4,'၁။ (ဝမ်း)ချုပ်သည်။','ချုက်လိက် ကသုက် = စာချုပ်ချုပ်ဆိုသည်။')
,(2704,3,1,'အုံတုံပင်။ (ဆေးဖက်ဝင်)',null)
,(2705,3,1,'ချောၚ်ကြား။',null)
,(2706,3,1,'ချောၚ်ကြိုချောၚ်ကြား။',null)
,(2707,3,4,'လှောင်ပြောင်သည်။ သရော်သည်။ ကျီစယ်သည်။ ရယ်သွမ်းသွေးသည်။','“ဂံါတိုန် သာသၞာအဲကျာ်ပိလ္ၚီသၞာံဂှ် ပ္ဍဲကာလဂှ် ခမဳကောန်အဲကျာ်ဂမၠိုၚ် မစဴသ္ၚိဒါယကာတအ်ဂှ် ဟီုဂလာန် ချံက်ချာ ဂြိုၚ်ဝေၚ်ကဵုဒါယကာတအ်ရ။” (အဓါန်မသုန်။ အစွောံ) = “ငါဘုရား၏သာသနာတော် အနှစ်သုံးထောၚ်သို့ ဝင်ရောက်သောအခါ ထိုကာလ­ ငါဘုရား၏သားတော်ရဟန်းများသည် ဒါ ယကာတို့အိမ်သို့ သွားရောက်လည်ပတ်၍ ဒါယကာများနှင့်တကွ ကျီစယ်နောက်ပြောင်သော စ ကားများကို ပြောဆိုကုန်လျက် ရယ်ရွှၚ်ကစားကြကုန်လတ္တံ့။”')
,(2707,3,4,'လှောင်ပြောင်သည်။ သရော်သည်။ ကျီစယ်သည်။ ရယ်သွမ်းသွေးသည်။','“ဗောဓိသတ်ပၠန် (ကွးမသုန်ကၠံ) ဒဒှ်ဍေံပချံက်ချာကဵုဇကုဂှ် တီကေတ်တုဲ—။” (ဇ—၂၄၅။ အစွောံ။) = “ဘုရားလောင်းသည် တ ပည့်ငါးရာတို့က မိမိအားလှောင်ပြောင်ကြောင်းကို သိ၍—။”')
,(2708,3,1,'ချည်ရစ်ပတ်ထားရာဘီးလုံး။','ချိၚ်တောဝ်ပလုဲ = အပ်ချည်ထုံး ရစ်ပတ်ထားရာဘီး လုံး။')
,(2709,3,13,'(ကြိ) ၁။ ချိန်ရွယ်သည်။ မှန်းသည်။','“ဗီုချိၚ်သၟိၚ်ရောဟွံစၟတ်” = “မှန်း ထားသလို (တရားသူကြီး)မင်းက မစစ်ဆေး။”')
,(2709,3,13,'(ကြိ) ၁။ ချိန်ရွယ်သည်။ မှန်းသည်။','၂။ ချိန်းဆိုသည်။ ချိန်းချက်သည်။')
,(2709,3,13,'(ကြိ) ၁။ ချိန်ရွယ်သည်။ မှန်းသည်။','“ပိုဲချိၚ် လဝ် ဆဵုဂဗညးသ္ကအ် ပ္ဍဲသ္ၚိအမူရ။” = “ဦးလေးအိမ်တွင် တွေ့ဆုံကြရန် ကျွန်တော်တို့ချိန်းဆို ထားကြသည်။”')
,(2710,3,4,'ချိန်းဆိုသည်။ ချိန်းချက်သည်။',null)
,(2711,3,1,'၁။ ချင်းလူမျိုး၊ ချင်းတိုင်းရင်းသား။','၂။ ကျွဲဒညင်းပင်။')
,(2712,3,3,'ခြေဆာသော။ ခြေကျိုးသော။','ဇိုၚ်ချံၚ် = ခြေဆာသည်။ ခြေမသန်ဖြစ်သည်။')
,(2713,3,4,'၁။ တစ်စုံတစ်ခုကြား­ ညှပ်ထားသည်။ ထိုးထားသည်။','“ချတ်လဝ်သေနာတ်ပ္ဍဲဂၞိၚ်။” = “ခါးကြားတွင် သေနတ်ထိုးထားသည်။”')
,(2713,3,4,'၁။ တစ်စုံတစ်ခုကြား­ ညှပ်ထားသည်။ ထိုးထားသည်။','“မၞိက်စောလာမုဏိဝွံ ဗှ်ေကေတ်ဏာတုဲ ပ္ဍဲကွဳတြုံဂှ် ဗှ်ေအာချတ်စုတ်တုဲ ဗှ်ေကလေၚ်ကၠုၚ်ပြဟ်ရ” သၟိၚ်ဂးကဵုဗၠာဲဇကုရ။ (ဇ—၁၉၄။ အစွောံ။) = “အ ချင်း၊ သင်သည်သွား၍ ငါ၏ပတ္တမြားဥသျှောၚ်ကျၚ်ကို ထိုယောကျာ်း၏လည်း­ ထိုးညှပ်ထားပြီး လျှင် အမြန်ပြန်ခဲ့လော့” ဟုမင်းသည် မင်းချင်းယောကျာ်းအား စေလိုက်၏။')
,(2713,3,4,'၁။ တစ်စုံတစ်ခုကြား­ ညှပ်ထားသည်။ ထိုးထားသည်။','၂။ အစားထိုးသည်။ အစားသွင်းသည်။')
,(2713,3,4,'၁။ တစ်စုံတစ်ခုကြား­ ညှပ်ထားသည်။ ထိုးထားသည်။','ချတ်စုတ်မၞိဟ် = လူအစားထည့်သည်။ လူအစားသွင်းသည်။ လူအ စားထိုးသည်။')
,(2714,3,16,'(န) ဂျတ်။ (ရေငန်ပိုင်းနေ အဆိပ်ပြင်းသောမြွေတစ်မျိုး)',null)
,(2715,3,4,'လေချွန်သည်။',null)
,(2716,3,4,'၁။ သေသည်၊ သေဆုံးသည်။','“ချိုတ်မ္ဂးတိပိုၚ် ဂျိုၚ်မ္ဂးက္ဍိုၚ်ထဝ်။” = “သေလျှင်မြေ ကြီး ရှင်လျှင်ရွှေထီး။”')
,(2716,3,4,'၁။ သေသည်၊ သေဆုံးသည်။','၂။ (မျက်နှာ)ညှိုးသည်။')
,(2716,3,4,'၁။ သေသည်၊ သေဆုံးသည်။','‘မုက်ချိုတ်စိုတ်လီု’ = ‘စိတ်ပျက်ပြီး မျက် နှာမသာမယာဖြစ်သည်။’')
,(2716,3,4,'၁။ သေသည်၊ သေဆုံးသည်။','၃။ (လက်ခြေစသည်) ညောင်းညာ၍ မလှုပ်မရှားနိုင်ဖြစ်သည်။')
,(2716,3,4,'၁။ သေသည်၊ သေဆုံးသည်။','‘ဇိုၚ် ချိုတ်’ ‘တမ်ကအ်ချိုတ်’ စသည်ဖြင့်သုံးသည်။')
,(2716,3,4,'၁။ သေသည်၊ သေဆုံးသည်။','“ယွံမၞးတံ၊ ဍာ်မှာသၟိတ်ဝွံဂှ် ပိုဲဂၜံထောံကၠေံဍာ်ဂှ် ဇုတ်ထမၚ်ပိုဲလေဝ် ချိုတ်ကွိုၚ်အာရ။ မတ်ပိုဲလေဝ် ဗကေတ်အာရ” ခဍာ်ဂမၠိုၚ်ဂး။ (ဇ—၁၄၆။ အစွောံ။) = “အိုကျီးတို့၊ ဤသမုဒြာရေကို ငါတို့သည် ခံတွင်းဖြင့်ငုံ၍ ထုတ်သည်ရှိသော် ငါတို့၏ မေးရိုးတို့သည်လည်း ညောင်းကုန်၏။ ငါတို့၏မျက်စိတို့သည်လည်း နီကုန်၏” ဟုကျီးတို့ဆို၏။')
,(2717,3,4,'တိတ်တဆိတ်သေဆုံးသည်။ (မည်သူမျှမသိသော သေခြင်းမျိုးနှင့်သေသည်။)',null)
,(2718,3,4,'သေချာသည်။',null)
,(2719,3,4,'(သေပျော်ရှက်လေး။) သေရသည်က ပျော်သေး၏၊ ရှက်သည်က လေးလံ လှသည်။ (‘အရှက်ကို အသက်နှင့်လဲသည်’ ဟူသော မြန်မာစကားနှင့် အဓိပ္ပါယ်ဆင်တူသည်။)',null)
,(2720,3,5,'သေအတူ ရှင်အတူ။ အေးအတူပူအမျှ။',null)
,(2721,3,1,'ထိုစဉ်။ ထိုခဏ။','“ယြဴပူဂဵုလ္ၚဵု ချိုန်မညာတ်ဂှ်ဟေၚ် သ္ဇုၚ်သ္ဍိုက်တဴရ။” (ဇ—၂၃၇။ အစွောံ။) = “အချို့ကုန်သောသူတို့သည် မြင်မြင်ချင်း (ထိုခဏ­ပင်) ချစ်နှစ်သက်ကုန်၏။”')
,(2721,3,1,'ထိုစဉ်။ ထိုခဏ။','“ပ္ဍဲချိုန်မစပုၚ်တုဲဂှ်ဗက် သာ်ဝွံဗမၞးချပ်။” (ဇ—၁၇၉။ အစွောံ။) = “ထမင်းစားပြီးသည်နှင့် ထိုခ ဏ­ပင် ပုဏ္ဏားသည် ဤသို့ကြံ၏။”')
,(2722,3,5,'ထိုခဏ­။ ထိုအခိုက်အတန့်­။ ချက်ချင်း။','“အဲစဴစိုပ်သ္ၚိရ၊ ပ္ဍဲချိုန်ခဏ ဂှ်ရ မိစ္ဍးတိတ်နူသ္ၚိ တၞဟ်နအာဖျာရ။” = “ကျွန်တော်အိမ်ပြန်ရောက်သည်၊ ထိုခဏ­ပင် စျေး သွားရန် အမေအိမ်မှထွက်ခွာသည်။”')
,(2723,3,4,'စဉ်းစားသည်၊ ကြံစည်သည်။',null)
,(2724,3,4,'တိုင်ပင်သည်။','“ဂစေံဂမၠိုၚ်သီုခဍာ်ဆနွံဂှ် ချပ်ဂၞန်ပၠန်ရ။” (ဇ—၂၇ဝ။ အစွောံ။) = “ကျန်ရှိသမျှသော ငှက်များနှင့်ကျီးတို့သည် တိုင်ပင်ကြကုန်ပြန်၏။”')
,(2725,3,4,'ချင့်ချိန်ဆင်ခြင်သည်။ စဉ်းစားမြော်မြင်သည်။','ချပ်ဂြၚ်ဂုန်ဒုဟ် = အကျိုးအပြစ်ကို စဉ်းစားချင့်ချိန်သည်။')
,(2725,3,4,'ချင့်ချိန်ဆင်ခြင်သည်။ စဉ်းစားမြော်မြင်သည်။','“ပ္တုဲပွမွဲမွဲမ္ဂး ချပ်ဂြၚ်ဂုန်ဒုဟ်တုဲ ဂပ်ဂဝ်ပ္တုဲညိ။” = “တစ်စုံတစ်ခုသောအ မှုကိုပြုလျှင် အကျိုးအပြစ်ကို ချင့်ချိန်ဆင်ခြင်ပြီးမှ ပြုသင့်သည်။”')
,(2725,3,4,'ချင့်ချိန်ဆင်ခြင်သည်။ စဉ်းစားမြော်မြင်သည်။','ချပ်ဂြၚ်ဟိုတ်ဖဵု = အ ကြောင်းအကျိုးကို စဉ်းစားမြော်မြင်သည်။')
,(2725,3,4,'ချင့်ချိန်ဆင်ခြင်သည်။ စဉ်းစားမြော်မြင်သည်။','“ဟိုတ်မၞးဟွံဂွံချပ်ဂြၚ်ဟိုတ်ဖဵုတုဲ မၞးမဒးအလီဍေံ ရောၚ်။” = “အကြောင်းအကျိုးကို သၚ်မစဉ်းစားမဆင်ခြင်သောကြောင့် သၚ်အလိမ်ခံရသည်။”')
,(2725,3,4,'ချင့်ချိန်ဆင်ခြင်သည်။ စဉ်းစားမြော်မြင်သည်။','“ဣသိဂှ် လုကဴထပှ်တ္ၚဲဂှ် သတိက်ကၞပ်ချပ်ဂြၚ်ဒၟံၚ် ပ္ဍဲရုပ်ဂၞကျာ်ဂှ်ရ။” (ဇ—၂၅၁။ အစွောံ။) = “ရသေ့သည် ခုနစ်ရက်ပတ်လုံး ငြိမ်သက်စွာအိပ်၍ မိဖုယား၏ရုပ်ကိုသာလျှင် တစေ့စေ့တွေးပြီး တရေးရေးမြင်ယောၚ်နေ၏။”')
,(2726,3,4,'ကြံဆသည်။ တွေးတောသည်။ (ပါဠိ—တက္ကေတိ)',null)
,(2727,3,4,'စဉ်းစားဆင်ခြင်သည်။ ချင့်ချိန်ပိုင်းခြားသည်။',null)
,(2728,3,16,'(ကြိ) ဇတ်ကနဲဖမ်းသည်။ ဖျတ်ကနဲဖမ်းကိုၚ်သည်။','“အဲဒဗိုတ်ဏာကရောဲ(ဗဝ်) ဂှ် ချောပ်ကောန်ၚာ်တြုံဂှ် ရပ်ဂွံအာရ။” = “ဘောလုံးကို ငါပစ်လွှတ်လိုက်ရာ ထိုသူငယ်က ဖျတ်ကနဲဖမ်းမိလိုက်သည်။”')
,(2729,3,1,'နှာစေးအအေးမိရောဂါ။','ဒးချာံ = နှာစေးသည်။ အအေးမိသည်။')
,(2730,3,4,'နှာစေးရာမှ လည်ချောင်းဖက်သို့ နှာရည်ဆင်း၍ ချောင်းဆိုးသည်။',null)
,(2731,3,4,'နှာရည်ယိုသည်။',null)
,(2732,3,1,'မီးသွေးကဲ့သို့ဖြစ်အောင် မီးဖုတ်ထားသောအရာ။','ချောံသၠကၞိ = မီးဖုတ်ထား သောဓနိဖက်။')
,(2732,3,1,'မီးသွေးကဲ့သို့ဖြစ်အောင် မီးဖုတ်ထားသောအရာ။','ချောံဇုတ် = အရိုးပြာခဲ။')
,(2732,3,1,'မီးသွေးကဲ့သို့ဖြစ်အောင် မီးဖုတ်ထားသောအရာ။','(ကြိ) နွမ်းနယ်သည်။')
,(2733,3,1,'မီးသွေးခဲ။ ပြာခဲ။',null)
,(2734,3,1,'ဖွဲပြာ။ ပြာခဲ။','“ဟာဲမၞးတံ၊ ——၊ နာဲသာဗၞိက်မွဲဂှ်ပါဲလဝ်တုဲ ကောန်ဗၞိက်သမၠီုတံဂှ် ကဵုဒှ်ဗတ်သၟရ၊ ကဵုဒှ်ချောံပ္တေၚ်ရ” သၟိၚ်နာ်ဂး။ (ဇ—၄၉၃။ အစွောံ။) (ချောံပ္တေၚ် = ဗတ်သၟ၊ ဘ သ္မ) = “အချင်းတို့၊ လှည်းကုန်သည်မှူးကိုသာလျှင်ထား၍ ထိုကုန်သည်မိုက်တို့ကို သတ်လေ ကုန်။ — အလုံးစုံကုန်သော ထိုကုန်သည်မိုက်တို့ကို ဖွဲပြာကိုကဲ့သို့ ပြုကြလေကုန်။” (နဂါးမင်း ဆို၏။) (ညောင်ကန်)')
,(2735,3,3,'နက်ပြာသော။','သာ်ချီု = နက်ပြာရောၚ်။ ခရမ်းရောၚ်။')
,(2735,3,3,'နက်ပြာသော။','(ကြိ) မွေးကျွေးသည်။')
,(2736,3,1,'စွန်လက်သည်းပင်။ (ဆေးဖက်ဝင်)',null)
,(2737,3,16,'(ကြိ) (စာပေ) ကူးယူသည်။ ကူးရေးသည်။',null)
,(2738,3,4,'ဖရိုဖရဲကြဲသည်။ အနှံ့လွင့်စဉ်သည်။','“ညံၚ်ပ္တေၚ်မပက်ဏာဒစးကျာတုဲ ညံၚ်ဍေံမက လေၚ်ကၠုၚ်ဒွအ်ဇကုကီုတုဲ ဍေံချာဲပြးအာရ။” (၅၅ဝ။ ဇ—၄ဝ၆။ ဒု—၄၉၄')
,(2738,3,4,'ဖရိုဖရဲကြဲသည်။ အနှံ့လွင့်စဉ်သည်။','၄၉၅။ အစွောံ။) = “လေဆန်သို့ ပက်လိုက်သောဖွဲပြာသည် မိမိဆီသို့ ပြန်လည်လာ၍ ထိခတ်ဘိသကဲ့သို့ ဖရိုဖရဲ ကြဲ၏။”')
,(2738,3,4,'ဖရိုဖရဲကြဲသည်။ အနှံ့လွင့်စဉ်သည်။','‘ချာဲဖဍာဲ’ နှင့် အဓိပ္ပါယ်အတူတူ။')
,(2739,3,4,'ဖရိုဖရဲကြဲသည်။ —စေသည်။','“ဂျိပိုဲနာ်ဝွံဂှ် ဇၞော်ဒြဟတ်လောန်ရောၚ်။ အဲထေဲပၞတ် တုဲ နကျာမုဟ်အဲဂှ် တသိုဟ်ပ္တိတ်မ္ဂး ဇကုလမာဲဂှ် ရဴပ္တေၚ်ညးမပက်ဏာမုက်ကျာကီု ဒးချာဲဖဍာဲအာ ရ။ ယာံအဲသ္ပသာ်ဂှ် သဳလအဲလီုအာရ” သၟိၚ်နာ်ချပ်။ (ဇ—၅ဝ၆။ အစွောံ။) = “ငါ၏အဆိပ်သည် များစွာ၏။ အကယ်၍ငါသည် အမျက်ထွက်သဖြင့် နှာခေါင်းလေကို လွှတ်အံ့၊ (အလမ္ပယ်၏ကိုယ်သည် လေတိုက်ရာမျက်နှာစာသို့ ပက်လိုက်သော) ဖွဲပြာကဲ့သို့ ဖရိုဖရဲကြဲလတ္တံ့။ ထိုဖွဲပြာကဲ့သို့ ဖရိုဖရဲကြဲသည်ရှိသော် ငါ၏သီလသည်လျှင် ကျိုးပျက်သည်ဖြစ်လတ္တံ့” ဟုနဂါးမင်းကြံ၏။(ညောင်ကန်)')
,(2739,3,4,'ဖရိုဖရဲကြဲသည်။ —စေသည်။','“ညံၚ်ဂၠံမတ်ဗြဲ မဒးကျာသမ္ကာတ်တုဲ ရဴမချာဲဖဍာဲအာကီု။” (ဇ—၅၁ဝ။ အစွောံ။) = “မိုး သားတိမ်စုသည် လေပြင်းထိသောအခါ ဖရိုဖရဲကြဲ၍ လွင့်စဉ်သွားဘိသကဲ့သို့။”')
,(2740,3,1,'မြက်။','‘(ဂၠဴမ္ဂးဂှ်) ကမတ်ချောဲဆံက် မအောန်ကဵုရှ်ဂှ် မစရ။’ (ဇ—၂၈၆။ အစွောံ။) = ‘နွားတို့သည် အရသာနည်းပါးသော မြက်ကောက်ရိုးတို့ကို စားရ၏။’ (ချောဲ = ကမတ် = မြက်)')
,(2740,3,1,'မြက်။','ချောဲဒဇိပ် = နေစာမြက်။')
,(2740,3,1,'မြက်။','ချောဲဇိုၚ်ခ္ဍာ် = ဆင်ငိုမြက်။')
,(2740,3,1,'မြက်။','ချောဲချေံ = မြင်းသေမြက်။ တောက်တဲ့စာပင်။ (ဆေးဖက်ဝင်)')
,(2741,3,1,'နှီးအချောသပ်ရာမှ ထွက်လာသော ဝါးအမျှင်အစအန၊ ဝါးဖတ်။',null)
,(2742,3,1,'သတ္တုချေး။ သတ္တုချော်။ အောက်ဆိုက်(ံညိဒေ)။','ချဝ်ဒကောဝ် = ခဲချေးခဲချော်၊ ခဲ အောက်ဆိုက်။')
,(2742,3,1,'သတ္တုချေး။ သတ္တုချော်။ အောက်ဆိုက်(ံညိဒေ)။','ချဝ်ပသဲ = သံချေးသံချော်၊ သံအောက်ဆိုက်။')
,(2743,3,1,'‘ချဝ်’ (န)နှင့်အဓိပ္ပါယ်အတူတူ။',null)
,(2744,3,16,'(ကြိ) (လှီး၊ ဖြတ်၊ ညှပ်ရာတွင်) စွေစောင်းသည်။ တစ်ဖက်လိုက်သည်။',null)
,(2745,3,1,'ဂမုန်း။','‘ဖျောဝ်’ ရှု။')
,(2746,3,4,'(ထမင်းချက်ရာတွင် ရေမခန်းမီ) ရေစပ်စပ်ဖြစ်သည်။',null)
,(2747,3,4,'၁။ ပွသည်။ ဆွေးသည်။ ရိသည်။','ဂၠိက်ချဵု = လုံချည်ရိဆွေးသည်။')
,(2747,3,4,'၁။ ပွသည်။ ဆွေးသည်။ ရိသည်။','၂။ အထစ် အငေါ့မရှိ သွက်လက်စွာရွတ်ဆိုသည်။')
,(2748,3,1,'လဲ။ လဲဝါ။ လဲမှို့။ (ပါဠိ—တူလ)','ချဵုဆု၊ ချဵုမက္တဵုဒှ်နူတၞံဆု = သစ်ပင်မှဖြစ်သောလဲ။ (ပါဠိ—ရုက္ခတူလ)')
,(2748,3,1,'လဲ။ လဲဝါ။ လဲမှို့။ (ပါဠိ—တူလ)','ချဵုဇုက်လွာ = နွယ်မှဖြစ်သောလဲ။ နွယ်လဲ။ (ပါဠိ—လတာတူလ)')
,(2748,3,1,'လဲ။ လဲဝါ။ လဲမှို့။ (ပါဠိ—တူလ)','ချဵုကၟတ် ဗၞူ၊ ချဵုကၟတ်ၜုန်ပြေၚ် = ဖောင်းခါးမြက်လဲ။ ဖောင်းပွင့်လဲ။ (ပါဠိ—ပေါဋကိတူလ)')
,(2748,3,1,'လဲ။ လဲဝါ။ လဲမှို့။ (ပါဠိ—တူလ)','တောဝ်ချဵု = ဝါဂွမ်း။ ဖန်ထားသောဝါဂွမ်း။')
,(2749,3,4,'(တံတွေး)ထွေးသည်။','ချဟ်ဍာ်ပါၚ် = တံတွေးထွေးသည်။')
,(2749,3,4,'(တံတွေး)ထွေးသည်။','“ဍာ်ကသှ်ဂှ် ချဟ်ထောံ ကၠေံတုဲဂှ် ကၠာန်ဍေံပၠန်ဂှ် ဟွံဒှ်ရ။” (ဇ—၃၁ဝ။ အစွောံ။) = “ထွေးပစ်ပြီးသောတံတွေးပေါက်ကို ပြန်လျက်ရန် မဖြစ်နိုင်တော့ပါ။”')
,(2750,3,4,'(တံတွေး၊ သလိပ်စသည်) ထွေးသည်။ (စက်ဆုပ်ရွံရှာသဖြင့် ‘ထွီ’ ဟုအသံထွက်၍) တံတွေးထွေးသည်။ ရွံရှာမုန်းတီးသည်။ အော့ကြောလန်သည်။','“တြုံပိုတ်ဇိုၚ်တဲကတောဝ်မုဟ် မဂပ်ဂဝ်က္ဍုဟ်စအိုတ်တဴစိုတ်ဝွံ မူပလွဳပရာဝေၚ်ဍေံရော” ဂးတုဲ ဗြဴဂှ်ချဟ်ခါ်တဴရ။ (ဇ—၁၉၃။ အစွောံ။) = “စက်ဆုပ်ရွံရှာဖွယ်ကောင်းသော ခြေလက်နားနှာခေါင်းပြတ်သော ဤယောကျာ်းကို အဘယ်ကြောင့် ကုသနေရပါသနည်း” ဟုဆိုကာ ထိုမိန်းမသည် ‘ထွဳ’ ဟု တံတွေးထွေး၏။')
,(2751,3,1,'မြင်း။','(ကြိ) ကမြင်းသည်။ ကမြင်းကြောထသည်။')
,(2752,3,4,'မသတီစရာ ရွံစရာဖြစ်ကြောင်းကို ပြသောစကားလုံး။ ‘ထွီ’။',null)
,(2753,3,1,'ဘုရားလောင်း သိဒ္ဓတ္ထမင်းသား၏ ဖွားဖက်တော် စီးတော်မြင်း၏အမည်။ ကဏ္ဍ ကမြင်း။',null)
,(2754,3,1,'ခါးကျိုးတတ်သောမြင်း။ အမျိုးမကောင်းသောမြင်း။',null)
,(2755,3,1,'ရေမြင်း။',null)
,(2756,3,1,'မြင်းကျားသတ္တဝါ။',null)
,(2757,3,1,'ဝဲစားမျိုးမြင်း။ အမျိုးမမြတ်သောမြင်း။',null)
,(2758,3,1,'မြင်းပုကလေး။',null)
,(2759,3,1,'အရွယ်ရောက်မြင်းထီး။',null)
,(2760,3,1,'သိန္ဓောမြင်း။ အမျိုးမြတ်သောမြင်း။ အလွန်လျင်မြန်သောမြင်း။',null)
,(2761,3,1,'မြင်းအာဇာနည်။ အမျိုးမြတ်သောမြင်း။',null)
,(2762,3,1,'မြင်းအာဇာနည်။',null)
,(2763,3,1,'အဿတိုရ်မြင်း။ လားသတ္တဝါ။ (မုလေ)',null)
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','“စပုၚ်မ္ဂး လ္ပချအ်စုတ်တဲပ္ဍဲပါၚ်ညိ။” = “ထမင်းစားလျှင် ပါးစပ်ထဲ သို့ လက်မထိုးသွင်းပါနှင့်။”')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','“(တြုံမလုန်လန်ဂှ်) ဍေံခိုဝ်လုပ်အာတုဲ ပုၚ်မွဲလၟံက် ဍေံၜိုတ်ကေတ် ပ္ဍဲထးထဝ်သၟိၚ်ဂှ်တုဲ ဍေံချအ်ပၠောပ်ဏာပါၚ်ဍေံရ။” (ဇ—၂၆ဝ။ အစွောံ။) = “ထိုလော်လည်သော ယောကျာ်းသည် အလျင်အမြန်ဝင်သွားကာ မင်း၏စားတော်ရွှေခွက်မှ ထမင်းတစ်လုတ်ကို နှိုက် ယူပြီးလျှင် မိမိပါးစပ်ထဲ ထည့်သွင်း၍စား၏။”')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','“နၜဲမှေဟ် ပိုဟ်နဝိုဟ် မၞးတံချအ်ကလက်လဝ် သိုၚ်ကတောဝ်အိုတ်” ရဴဝွံကဵုလန်ဟီု။ (ဇ—၂၄၁။ အစွောံ။) = “ပဲကြီးမုံ့ညက်ဖြင့် သင်တို့နား ပေါက်တို့ကို ဆို့ပိတ်ထားကြကုန်လော့” ဟုကြေညာစေ၏။')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','၂။ ဝတ်သည်။ စွပ်သည်။')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','ချအ် ပလောအ် = အင်္ကျီဝတ်သည်။')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','ချအ်ဒၞပ် = ဘိနပ်စီးသည်။ ဘိနပ်စွပ်သည်။')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','၃။ (လေနာ) ထိုးကျင့်သည်။')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','“ကျာတိုန်ချအ်ပ္ဍဲဂၞဴအဲ” ဗမၞိဟ်ဂး။ (ဇ—၁၃ဝ။ အစွောံ။) = “ငါ၏ဝမ်း­ လေ နာထိုးကျင့်၏” ဟုပုဏ္ဏေးမဆို၏။')
,(2764,3,1,'၁။ ထိုးသွင်းသည်။','(န) မှန်ကူပင်။ မှန်ကူသီး။')
,(2765,3,4,'အသည်း­ဆို့နင့်သည်။ ရၚ်နင့်သည်။ စိတ်နှလုံးမခံသာအောင်ဖြစ်သည်။','(တၠသ္ၚိဇ ကုကိနနရာဒးပွန်တုဲ ပ္ဍဲမလောတ်သ္တိက်ဒၟံၚ်ဂှ် ကိနနရဳဗြဴဟီုယာံရိုဟ်ရေၚ်တဴရ။ “——၊ ကောဂၞဴအဲမွဲဟွံ ညာတ် အဲဗြဴချအ်ဂြိုဟ်နရာတ် သြိုဟ်သ္ပာ်အာန်တဏာန် သိက်ပအဲဗြဴချပ်မာန်ရောလေဝ်ကော။” (ဇ—၄၈၅။ အစွောံ။) = “နှမခမျာရၚ်နင့်ကြေကွဲ အသည်းကွဲ၍ ဝမ်းနည်းပူဆွေးနေရ၏၊ နှမ မတွေးနိုင်အောင်ရှိသည်ကို နှမနောင်တော်မမြင်နိုင်ပြီတကား။” (မြှားသင့်၍ လဲလျောင်းနေသော မိမိခင်ပွန်းကိနနာနှင့်တကွ ကိနနရီမ ငိုကြွေး၏။)')
,(2766,3,4,'(ရၚ်­)ဆို့နင့်သည်။',null)
,(2767,3,4,'ချဉ်ဖတ်သိပ်သည်။',null)
,(2768,3,4,'မြှောက်ပေးသည်၊ ဆွပေးသည်။',null)
,(2769,3,16,'(ကြိ) ၁။ ဆို့သည်။ ပိတ်ဆို့သည်။','၂။ လှိုက်ဆို့သည်။ (မောလွန်း၍)')
,(2769,3,16,'(ကြိ) ၁။ ဆို့သည်။ ပိတ်ဆို့သည်။','ချိုအ် တိုန်ပ္ဍဲသြိုဟ် = ရၚ်တွင်း­ လှိုက်ဆို့တက်သည်။')
,(2769,3,16,'(ကြိ) ၁။ ဆို့သည်။ ပိတ်ဆို့သည်။','“(သၟိၚ်ကၞုဲဂှ်) ဓဝ်စံၚ်တူက္တဵုဒှ် ပ္ဍဲဂၠံဟဒယဖျုန် ဂြိုဟ်ချိုအ်အာတုဲ ပကာဂစိုတ်ဒၞာဲဂှ်ရ။” (ဇ—၅၈။ အစွောံ။) = “ထိုမျောက်မင်းသည် ပူပန် သောကဖြစ်ပေါ်၍ နှလုံးဟဒယ­ လှိုက်ဆို့သည်ဖြစ်၍ ထိုနေရာ­လျှင်သေ၏။”')
,(2770,3,16,'(ကြိ) (ရၚ်တွင်း­) လှိုက်ဆို့သည်။',null)
,(2771,3,4,'၁။ ခြစ်သည်။','၂။ ဖြန့်ချဲသည်။')
,(2771,3,4,'၁။ ခြစ်သည်။','ခြလ္ၚပၟတ် = မီးကျီးခဲကို ဖြန့်ချဲသည်။')
,(2771,3,4,'၁။ ခြစ်သည်။','(န) ချေး။ ကြေး။ အညစ်အကြေး။')
,(2771,3,4,'၁။ ခြစ်သည်။','ခြေၚက် = သွားချေး။')
,(2772,3,4,'၁။ ခြားသည်။ ကွာသည်။','“တိုၚ်မွဲတၞုၚ်ကဵုမွဲတၞုၚ် ခြာလဝ်ပိပိဟတ်ညိ။” = “တိုင် တစ်ချောင်းနှင့်တစ်ချောင်း သုံးတောင်သုံးတောင်စီ ခြားထားပါ။”')
,(2772,3,4,'၁။ ခြားသည်။ ကွာသည်။','“ကောန်ၚာ်ၜါဂှ် အာယုက်ခြာ ပိသၞာံရ။” = “ထိုကလေးနှစ်ယောက်သည် အသက်သုံးနှစ်ကွာသည်။”')
,(2772,3,4,'၁။ ခြားသည်။ ကွာသည်။','“ကွာန်ၜါဂှ် ခြာဒၟံၚ်ပိ တိုၚ်ရ။” = “ထိုရွာနှစ်ရွာသည် သုံးမိုၚ်ကွာဝေးသည်။”')
,(2772,3,4,'၁။ ခြားသည်။ ကွာသည်။','၂။ အနားမကပ်ဘဲ ခွာ၍နေသည်။')
,(2772,3,4,'၁။ ခြားသည်။ ကွာသည်။','“(ဗောဓိသတ်ဒကောတ်) ဟွံပြာပ်အာညောန်ကုဣသိရ။ ခြာဒၟံၚ်ဝုတ်ဒိုဟ်ဂှ်ရ။” (ဇ—၁၃၈။ အစွောံ။) = “ဘုရားလောင်းဖွတ်သည် ထိုရသေ့အနားသို့မကပ်ဘဲ ထိုအနီးအနားတွင် ခွာလျက်နေ ၏။”')
,(2773,3,4,'ခွဲခွါသည်။ ကွဲကွာသည်။',null)
,(2774,3,1,'ကျီးကန်းခြေရာ။ ကြက်ခြေခတ်ပုံ။',null)
,(2775,3,5,'မကြာခင်။ မကြာမီ။',null)
,(2776,3,1,'အသက်။ သက်တမ်း။ တစ်သက်တာ။',null)
,(2777,3,4,'တုတ်နှင့်ဟိုဟိုဒီဒီခြစ်သည်။ ယက်သည်။','ခြးတိ = မြေကြီးယက်သည်။')
,(2777,3,4,'တုတ်နှင့်ဟိုဟိုဒီဒီခြစ်သည်။ ယက်သည်။','“စာၚ်တအ်ဂှ် ခြးတိတုဲ ဂၠာဲစစၟစၟောန်ရ။” = “ကြက်တို့သည် မြေကြီးကိုယက်၍ ပိုးမွှားများရှာစားကြသည်။”')
,(2778,3,4,'စိတ်ဆင်းရဲသည်။ စိတ်သောကရောက်သည်။','‘ခြုပ်ခြး’ (ကြိ)နှင့်အတူတူ။')
,(2779,3,4,'မာဆတ်သည်။ မာကြွပ်သည်။',null)
,(2780,3,4,'အဆန်ချောၚ်သည်။ (သစ်စေ့)',null)
,(2781,3,1,'သန္တာ။','(ကြိ) ကုတ်တက်သည်။ (ငါးများဆူးတောင်ဖြင့် ကုတ်တက်ခြင်း)')
,(2782,3,4,'စိပ်စိပ်ကာရံသည်။','“တၞံမုက်ဂှ် ညးခြိုၚ်ဒြာံခြံၚ်လဝ် ဗွဲမဗိုန်ရောၚ်။” (ဇ—၁၇၇။ အစွောံ။) = “ထိုတည်ပင်ကို လူတို့သည် (ဆူးခက်တို့ဖြင့်၄င်း ဝါးတို့ဖြင့်၄င်း) မြဲမြံစွာ ထွေးယှက် ကာရံထား၏။”')
,(2783,3,1,'လေမှုတ်တူရိယာတစ်မျိုး။','(ကြိ) (လေမှုတ်တူရိယာကို) မှုတ်သည်။ လေချွန်သည်။')
,(2783,3,1,'လေမှုတ်တူရိယာတစ်မျိုး။','“ဒန္တဂဳတမ္ပိ။ ၚ်ပွမကမြဴရာမ်သာၚ် မထေက်ကဵုခြံၚ်ခြာၚ်ကီုလေဝ်။ ဝါ။ ၚ်ပွမဒယှ်ေဆောတ်ကျာ ကီုလေဝ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၄၉၉။ စန္ဒိမာမဟာထေရ်။)')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','“ယွံတ္ၚေက်ကောန်သ္ဍိုက်အဲ၊ အဲပ္တိုန်လဝ်မ ကဵုခြိုၚ်ထဝ်ရောၚ် ကောန်” သၟိၚ်ဂး။ (ဇ—၂၈၁။ အစွောံ။) = “ချစ်သားကျေးသား၊ သင့်ကို ငါသည် ရွှေချိုင့်­ တၚ်၍ထား၏။”')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','“စာၚ်ဗ္တာၚ်မှာသေဋ္ဌဳ ညံၚ်ကၞုသၚ်ပွေါတ် မစုတ်လဝ်ပ္ဍဲခြိုၚ်ထဝ်ဂှ်—။” (ဇ—၂၈၄။ အစွောံ။) = “သူဌေးအားလည်း ကိုယ်လုံးဖြူသော ပွတ်အပ်သောခရုသင်းနှင့်တူသော ရွှေချိုင့်­ ထည့်၍ထားအပ်သော ကြက်သည်ရှိ၏။” (ညောင်ကန်)')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','‘ခရိုၚ်’ (န) လည်းရှု။')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','(ကြိ) ၁။ (လှောင်ချိုင့်ထဲတွင်) လှောင်သည်။')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','‘ဗ္ဂဲဂှ်ညးခြိုၚ်လဝ်ရ။’ = ‘ထိုကြောင်ကို လှောင်၍ထားသည်။’')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','‘ကြိုၚ်—၁')
,(2784,3,1,'ချိုင့်။ လှောင်ချိုင့်။','၁’ (ကြိ) လည်းရှု။')
,(2785,3,4,'ပတ်ပတ်လည်ကာရံသည်။','“တၞံမုက်ဂှ် ညးခြိုၚ်ဒြာံခြံၚ်လဝ် ဗွဲမဗိုန်ရောၚ်။” (ဇ— ၁၇၇။ အစွောံ။) = “ထိုတည်ပင်ကို လူတို့သည် (ဆူးခက်တို့ဖြင့်၄င်း ဝါးတို့ဖြင့်၄င်း) မြဲမြံစွာ ထွေးယှက်ကာရံထား၏။”')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','ခြပ်ပသဲ = သံချပ်။')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','“တၞဟ်နဗတိုက် ဍုၚ်ဗာရာဏသဳဂှ် သၟိၚ်သာမန္တရးဝွံ နခြပ်သၞာံဂြောပ်ကၠေံစိၚ်မ္ၚဵုတုဲ ဇကုတုန်လေဝ် သၠိုက်ကေတ်ခြပ် ထဝ်တုဲ ရပ်စရာၚ် ဍိုက်ကေတ်စိၚ်ဇၟူတုဲ ဗပါက်ကၠေံဍုၚ်ညးရ။” = “ဗာရာဏသဳပြည်ကိုတိုက် ရန် သာမန္တပြည့်ရှင်မင်းသည် မၚ်္ဂလာဆင်တော်ကို ချပ်ဝတ်တန်ဆာများဖြင့် ဖုံလွှမ်း၍ မိမိသည် လည်း ချပ်ကိုဝတ်၍ ဆင်ပြောင်ကိုစီးလျက် ချွန်းတောင်းကိုကိုၚ်စွဲ၍ ဗာရာဏသီမြို့ကို ထိုး ဖောက်၍ဖြို၏။”')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','၂။ (လိပ်၊ ခရုစသည်၏) အခွံမာ။')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','ခြပ်အရုတ် = လိပ်ခွံ။')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','ခြပ်ခရေၚ် = ဝင်ကစွပ်ကောင်၏အခွံ။')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','(ကြိ) ချိုးကပ်သည်။')
,(2786,3,1,'၁။ ချပ်ဝတ်တန်ဆာ။ ချပ်မိန်ညို။ သၚ်တိုင်း။','“ပ္ဍဲဇိုၚ်ဗှ်ေ မိဟ်ခြပ်ဒၟံၚ်တအ်ဂှ် တုဟ်ကဵုအး ညိ။”= “နင့်ခြေထောက်မှာ ကြေးတွေချိုးကပ်နေသည်ကို စင်ကြယ်အောင် ကြေးတွန်းပါ။”')
,(2787,3,4,'စိတ်ဆင်းရဲသည်။ စိတ်သောကရောက်သည်။',null)
,(2788,3,4,'မှိတ်တုတ်မှိတ်တုတ်ဖြစ်သည်။',null)
,(2789,3,1,'ချုံ။ ချုံပုတ်။ အုံ။','“လၟမွဲ အောပ်ဒၟံၚ်ပ္ဍဲခြုံဂှ် နွံတဴ။” (ဇ—၁၃။ အစွောံ။) = “တ ယောက်သောမုဆိုးသည် ဖုံးလွှမ်းအပ်သောအုံ­ (ပုန်း)နေ၏။” (ညောင်ကန်)')
,(2790,3,5,'ရုတ်တရက်။ ရုတ်ချည်း။ (လျောင်းရာ၊ ထိုၚ်ရာမှ ထရပ်သောလှုပ်ရှားမှုတွင် သုံး လေ့ရှိသည်။)','ခြုဟ်ဒလိုက်က္တဵု = ရုတ်တရက်ထလိုက်သည်။')
,(2790,3,5,'ရုတ်တရက်။ ရုတ်ချည်း။ (လျောင်းရာ၊ ထိုၚ်ရာမှ ထရပ်သောလှုပ်ရှားမှုတွင် သုံး လေ့ရှိသည်။)','“(မၚ်ဗၠာဲ)သဥ္ဇိဝရပ်ကြေဟ် မန် မဂၠိုၚ်ကဵုလတုန်တုဲ ဗိုတ်စုတ်ဇွကၠ ခြုဟ်ဇွကၠဒလိုက်က္တဵု—။” (ဇ—၁၅ဝ။ အစွောံ။) = “သဥ္ဇိဝလု လင်သည် ကျောက်စရစ်ကိုကိုၚ်၍ မန္တရားကို အကြိမ်များစွာ သရဇ္စျာယ်ပြီးလျှင် ကျားသေကို ကျောက်စရစ်ဖြင့် ပစ်၏။ ကျားသေသည် ရုတ်ချည်းထလာ၏။”')
,(2791,3,4,'၁။ ခုတ်ထွၚ်သည်။','“ခြောဟ်ဗာ်ထောံဇလတအ်ဂှ်ညိ” = “ဆူးများကို ခုတ်ထွၚ် လိုက်ပါ။”')
,(2791,3,4,'၁။ ခုတ်ထွၚ်သည်။','၂။ ဖြီးဖြန်းသည်။ ရမ်းသန်းသည်။')
,(2792,3,4,'ဝင့်ကြွားစွာလှမ်းသည်။ သတိဖြင့်လှမ်းသည်။ (တံ စတပေ ပရုံဒလယး တံ စတပေ ဝိတဟ ၚအရေ)','“ဗောဓိသတ်ဒကောတ် ဟွံဂံၚ်လုပ်ဆိုက်(ဣသိစၞာဲဂှ်)တုဲ သြာဲတိတ်အာညိညတုဲ ခြေအ်ဒၟံၚ် ရ။” (ဇ—၃၂၅။ အစွောံ။) = “ဘုရားလောင်းဖွတ်သည် ရသေ့စဉ်းလဲအနီးသို့ မချဉ်းကပ်ဝံ့သ ဖြင့် အနည်းငယ်ဆုတ်ခွါ၍ သတိဖြင့်လှမ်းလျှောက်နေ၏။”')
,(2792,3,4,'ဝင့်ကြွားစွာလှမ်းသည်။ သတိဖြင့်လှမ်းသည်။ (တံ စတပေ ပရုံဒလယး တံ စတပေ ဝိတဟ ၚအရေ)','“စာၚ်ဂှ် တက်တိုန်သၞေၚ် ဂြဴတိုန် ဗၞတ်ၜါဝါပိဝါတုဲ စာၚ်ဂှ် ဂေတ်ခြေအ်ဝိုၚ်ရ။” (လိက်ဗွဟ်မန်တန်သတ္တမ။ ဗော်ပရေၚ်ကိစ္စကေၚ် ကာမန်။) = “ထိုကြက်သည် တောင်ပံကိုခတ်၍ နှစ်ကြိမ်သုံးကြိမ်တွန်၍ ဝင့်ကြွားစွာလှမ်းလျက် ဝိုင်းပတ်လည်လှည့်၏။”')
,(2793,3,1,'အညစ်အကြေး။','(ကြိ) ကြို့ထိုးသည်။')
,(2794,3,4,'ကြည်လင်တောက်ပသည်။ ပြိုးပြိုးပြက်လင်းသည်။','“ပြဘာဝတဳဂှ် ပတၠလျးရုပ် ညံၚ် လျးတ္ၚဲဗၠာဲကီု လျးပန်ပန်ဟတ် ခၠၚ်တိတ်အာနူဇကုရောၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “ထိုပဘာ ဝတီမင်းသမီးကိုယ်မှ (လေးတောင်ပတ်လည်­) တက်သစ်သောနေလုလင်ကဲ့သို့ အရောင်တို့သည် ပြိုးပြိုးပြက်ထွက်ကုန်၏။” (ညောင်ကန်)')
,(2794,3,4,'ကြည်လင်တောက်ပသည်။ ပြိုးပြိုးပြက်လင်းသည်။','“(ကၠိက်တံဂှ်) ဍေံပၠောဇကုပ္ဍဲသၠိုက်ဂှ်တုဲ ဍေံ တိုန်ဂၠိန်မၞိက်ဂှ်ရ။ လျးမၞိက်ဂှ် ဒးတသော်ကၠိက်ဂှ်တုဲ လျးဂှ် ခၠၚ်တိတ်အာပၠန်ရ။” (ဇ—၂၈၅။ အစွောံ။) = “(ထိုဝက်တို့သည်) ညွန်­လူး၍ လာလတ်၍ ပတ္တမြားကို (ကိုယ်ဖြင့်)ပွတ်ကုန်၏။ ပတ္တမြားသည် ဝက်တို့၏အမွေးတို့ဖြင့် ပွတ်အပ်သည်ရှိသော် အတိုင်းထက်အလွန် ကြည်လင် (တောက်ပ)၏။” (ညောင်ကန်)')
,(2795,3,4,'လင်းလက်တောက်ပသည်။',null)
,(2796,3,4,'ထွန်းလင်းသည်။ တောက်ပသည်။ အလင်းရောၚ် ပြိုးပြိုးပြက်ပြက်ထွက်သည်။',null)
,(2797,3,4,'ထွန်းလင်းသည်။ တောက်ပသည်။ ပြောင်လက်သည်။','“သၞာ်ဂှ် သ္ကေက်လောန် ခၠၚ်လစးတဴရောၚ်။” (၅၅ဝ။ ဇ—၄ဝ၁။ ဒု—၄၆၅။ အစွောံ။) = “ထိုသန်လျက်သည် အလွန် ထက်သောအသွားရှိ၍ တပြောင်ပြောင်တောက်ပ၏။”')
,(2798,3,4,'တစ်ဖက်မှ တစ်ဖက်သို့ ထွင်းဖောက်သည်။ ထုတ်ချင်းပေါက် ထွင်းဖောက်ထွက်သည်။','“ဍေံဗလးဏာကံမွဲ အပ္ဍဲဍာ်ဂှ် ပန်ဥဿဘ အပ္ဍဲတိဂှ် ဗၞတ်ဒစာံဥဿဘဟေၚ် ခၠၚ်သာတ် အာ(ရ။)” (၅၅ဝ။ ဇ—၅၂၂။ ၈—၃၁၂။ အစွောံ။) = “မြှားတစင်းကို ပစ်လွှတ်လိုက်ရာ ရေထဲ ­ လေးဥဿဘ မြေထဲ­ ရှစ်ဥဿဘ ထွင်းဖောက်လွန်ထွက်သွား၏။”')
,(2799,3,1,'ရေအိုင်ငယ်။ တွင်းငယ်။ ရေရှိသောချိုင့်နေရာ။','ခၠိုၚ်ပြေၚ် = ကျွဲလူးအိုင်။')
,(2799,3,1,'ရေအိုင်ငယ်။ တွင်းငယ်။ ရေရှိသောချိုင့်နေရာ။','(ကြိ) (ရေ) ဝပ်နေသည်။ အိုင်နေသည်။')
,(2799,3,1,'ရေအိုင်ငယ်။ တွင်းငယ်။ ရေရှိသောချိုင့်နေရာ။','“ပ္ဍဲဒၞာဲဂှ် ဍာ်ခၠိုၚ်ဒၟံၚ်ညိရောၚ်။” = “ထိုနေရာ­ ရေအနည်း ငယ်ဝပ်နေသည် (ဝါ) အိုင်နေသည်။”')
,(2800,3,4,'ပြတ်လပ်သည်။ ပြောင်သည်။ သစ်ပင်မရှိဖြစ်သည်။ (တံ ဗေ ဗအရေး တံ ဗေ တရေလေစေစ)','“(ပ္ဍဲဥဒျာန်ဂှ်) တၞံဆုဍေံတိုန်ဒကုတ်ဒကန်ခၠိုၚ်ရိုၚ်ဒၟံၚ်ဂှ် မူဟိုတ်ဍေံမဂွံဒှ်ရော။” (ဇ—၂၆၈။ အစွောံ။) = “ထိုဥယျာဉ်­ သစ်ပင်များ အချို့နေရာတွင်ပေါက်၍ အချို့နေရာတွင်မပေါက် ပြတ် လပ်၍ ပြောင်နေသည်မှာ အဘယ်ကြောင့်ပါနည်း။”')
,(2800,3,4,'ပြတ်လပ်သည်။ ပြောင်သည်။ သစ်ပင်မရှိဖြစ်သည်။ (တံ ဗေ ဗအရေး တံ ဗေ တရေလေစေစ)','“တၞံဆုတံဂှ် လ္ၚဵုဍေံချိုတ်အာ လ္ၚဵုဍေံဒှ်တုဲ တၞံဆုတံဂှ် ဍေံတိုန်ခၠိုၚ်ရိုၚ်အာရောၚ်အဴ။” (ဇ—၂၆၈။ အစွောံ။) = “(စိုက်ထားအပ်သော) သစ်ပင်တို့သည် အချို့သေကုန်၍ အချို့သာဖြစ်ထွန်း၏။ သစ်ပင်တို့သည် (အတက်မညီဘဲ) ပြတ် လပ်ပြောင်နေကုန်၏။”')
,(2801,3,4,'ချန်လှပ်သည်။ ကျော်သွားသည်။ ရှောင်ကွင်းသည်။',null)
,(2802,3,4,'ခုံးသည်၊ ဝိုင်းသည်။',null)
,(2803,3,4,'စောက်နက်သည်။','ပ္ၚာန်ခၠုံ = စောက်နက်ပန်းကန်။')
,(2804,3,4,'တုံ့ပြန်သည်။ ချေပသည်။ ဖြေကြားသည်။','“ဂလာန်သၟာန်ညးဂှ် သ္ဇိုၚ်သ္ဇိုဟ်လောန် အဲခၠေဝ်ဟွံဒးရ။” = “သူ့မေးခွန်းသည် အလွန်လေးနက်သဖြင့် ငါမဖြေတတ်ပါ။”')
,(2804,3,4,'တုံ့ပြန်သည်။ ချေပသည်။ ဖြေကြားသည်။','“(ဂလာန် ဗောဓိသတ်ဂှ်) ပြဘာတ်မိၚ်တုဲ ချပ်ခၠေဝ်ဟီုဟွံဒးတုဲ ဒလိုက်က္တဵုဒြေပ်ဒဴအာကၠေံံရ။” (ဇ—၂၄၄။ အစွောံ။) = “ထိုပရိဗိုဇ်သည် ဘုရားလောင်းစကားကိုကြား၍ ပြန်လည်ချေပပြောဆိုခြင်းငှာ မ တတ်နိုင်သဖြင့် ထ၍ပြေးလေ၏။”')
,(2805,3,4,'(ရှုံးပြီးနောက်) ပြန်လည်အနိုင်ယူသည်။','“ညံၚ်သရာဲဒယှ်ရ လဆောဝ်မှာ ရာ ဒးကျဆောံတုဲ မရံၚ်ဂွာံကလေၚ်ဇၞးကီု — ခၠေဝ်ကေတ်ဇၞး ကဵုဇၞးဂေါဝ်ညိ။” (ဇ—၁၄၈။ အစွောံ။) = “စစ်သူရဲကျော်ကဲ့သို့ပင် ရံခါမှားယွင်းရှုံးနိမ့်ရသည်များရှိသကဲ့သို့ ပြန်လည်အနိုင်ယူ ရန် အခွင့်ကောင်းကို စောင့်ကြည့်လျက် ပြန်လည်အနိုင်ယူ၍ အောင်ပွဲလှလှရပါစေ။”')
,(2806,3,4,'အကြွေးဆပ်သည်။',null)
,(2807,3,4,'ချစ်ကြွေးဆပ်သည်။',null)
,(2808,3,4,'ကျေးဇူးဆပ်သည်။ ကျေးဇူးတုံ့ပြန်သည်။','“ဂုန်ညးမပ္တုဲလဝ်ပ္ဍဲဇကုဂှ် ပွမ ဂွံဂြၚ်ဂုန်ညး ဂွံခၠေဝ်ဂုန်ညးဂှ် ဒှ်ဒ္ဂေတ်တၠပညာမပြဲရ။” = “မိမိအားပြုအပ်သော သူ့ကျေးဇူးကို သိတတ်ခြင်း၊ သူ့ကျေးဇူးကို ဆပ်ခြင်းမည်သည် ပညာရှိတို့၏ မြတ်သောအကျင့်ဖြစ်သည်။”')
,(2809,3,4,'ပြန်လည်ခုခံပြောဆိုသည်။ ပြန်လည်ချေပသည်။','“ဗှ်ေဟွံဂွံကၠတ်လဝ်ဒြပ်ညးဍာံမ္ဂး စိုပ်ရုၚ်ဗစာတေံ ဗှ်ေခၠေဝ်ဒုၚ်ဂလာန်ညးမာန်ဟာ။” = “သူ့ဥစ္စာကို နၚ်တကယ်မခိုးရကြောင်း တ ရားရုံးရောက်သောအခါမှာ သူ့အဆိုကို နၚ်ပြန်လည်ခုခံနိုင်မလား။”')
,(2809,3,4,'ပြန်လည်ခုခံပြောဆိုသည်။ ပြန်လည်ချေပသည်။','“ယွံပြောဟိတ်၊ အဲကဵုတၠ အဲဂှ် ပိုဲညးၜါဝွံ ဗှ်ကဵုဇာတိဂကူကီု ဗှ်ကဵုဒြပ်ကသပ်ကီု တန်ဂွံခၠေဝ်ဒုၚ်မာန်ကီုရဂးတုဲ အဲဟီုပ္ညုၚ်ထ္ၜး တၠအဲရောၚ်” သေဋ္ဌဳဂး။ (ဇ—၉၂။ အစွောံ။) = “အိုပုရောဟိတ်၊ အကျွန်ုပ်နှင့်သၚ် ငါတို့နှစ်ဦး တို့သည် အမျိုးဇာတိအရလည်းကောင်း၊ ဥစ္စာဓနအရလည်းကောင်း (ဤရၚ်ဆိုင်နေရသောအမှု ကို) ခုခံချေပနိုင်လတ္တံ့ဟု နှလုံးသွင်း၍ သင့်အားညွှန်ပြလိုက်ခြင်းဖြစ်ပါသည်” ဟုသူဌေးဆို၏။')
,(2810,3,4,'အပြစ်ကိုချေသည်။ အပြစ်ပြေပျောက်သွားအောင် ချေပသည်။',null)
,(2811,3,4,'ပြန်လှန်ချေပသည်။',null)
,(2812,3,4,'ကျေးဇူးဆပ်သည်။ ကျေးဇူးတုံ့ပြန်သည်။','“ယွံကောန်၊ ယြဴညးမွဲဂှ် ကၠောန် ၜိုတ်ဥပကာလဝ်ဇကုကၠာတုဲ မ္ဒးခၠေဝ်ပလန်ဂုန်ညး မ္ဒးကၠောန်ၜိုတ်ဥပကာ ကဵုညးပၠန်ရောၚ်ကောန်။” (ဇ—၃ဝ၂။ အစွောံ။) = “ချစ်သား၊ သူတစ်ယောက်သည် မိမိအား ရှေးဦးစွာ လုပ်ကျွေးကျေး ဇူးပြုထားလျှင် မိမိက သူ့ကျေးဇူးကို ပြန်ဆပ်ရပါမည်။ ပြန်၍ကျေးဇူးပြုရပါမည်။”')
,(2813,3,4,'ကျေးဇူးဆပ်သည်။ ကျေးဇူးတုံ့ပြန်သည်။','“ယြဴပူဂဵုမွဲ ဂုန်မပ္တုဲလဝ်ပ္ဍဲဇကုဂှ် ဂွံဗှ် ဂုန်ညး ဂွံခၠေဝ်ရော်ဂုန်ညးဂှ် ဒှ်ပူဂဵုမပြဲရောၚ်။” (ဇ—၁၅၇။ အစွောံ။) = “အကြင်သူသည် မိမိ­ ပြုထားသော သူ့ကျေးဇူးကိုအောက်မေ့ခြင်း သူ့ကျေးဇူးကိုဆပ်ခြင်းသည် မြတ်သောသူမည်၏။”')
,(2814,3,4,'ပြန်လည်ကူညီသည်။ တုံ့ပြန်ကူညီသည်။',null)
,(2815,3,4,'(မေးသည်ကို) တုံ့ပြန်ဖြေဆိုသည်။',null)
,(2816,3,4,'ချစ်ခြင်းကြောင့် ကျေးဇူးပြုသည်။ ပေးဆပ်သည်။','“သၟိၚ်ၜိုပ်ထဝ်သၟိက် ဂွံခၠေဝ်အခေါၚ်ဇြဟာန် ကုသမ္ဘာကဵုကောန်ဘဝတြေံတေံဂှ်တုဲ ဇၟာပ်ပ်ကာလ ပရှ်ကဵုဍုတ်သၞေၚ်ထဝ်မွဲ မွဲတၞုၚ်ရ။” (ဇ—၁၃၆။ အစွောံ။) = “ရွှေဟၚ်္သာမင်းသည် ဘဝဟောင်းက မယားနှင့်သမီးတို့ကို ချစ်ခြင်းကြောင့် ချစ်ခွင့်ပေးဆပ်လိုသဖြင့် မိမိ၏ရွှေအတောင်ကို အချိန်ရောက်တိုင်း တစ်ချောင်း တစ်ချောင်းစီ နုတ်ပေး၏။”')
,(2817,3,4,'စကားချေပသည်။',null)
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','“ပဟိုတ်ကဵုသၟတ်တြုံမွဲ မပလီုခၠအ်ပ္ကဴတုဲ ပု တဒုဿကဇာတ် ကျာ်တြဲတွံ။” (ဇ—၂၈ဝ။ အစွောံ။) = “တယောက်သော အထုပ်ကိုဖျက်ဆီး တတ်သောသူငယ်ကို အကြောင်းပြု၍ ဟောတော်မူ၏။” (ညောင်ကန်)')
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','(ကြိ) ၁။ ခွက်ကဲ့သို့ ဖြစ်အောင်လုပ်သည်။')
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','“ယွံသူရိယကုမာ၊ — ခၠအ်ကေတ်သၠဒကှ်ဂှ်တုဲ ကေတ်နၚ်ဍာ်ကဵုပိုဲညးၜါ သုၚ်ညိ” ဗောဓိသတ်ဂး။ (ဇ—၆။ အစွောံ။) = “ညီတော်သူရိယကုမာ၊ ကြာရွက်ကို ခွက်ကဲ့သို့ လုပ်၍ ငါတို့သောက်ရန် ရေကိုယူဆောင်ပေးပါ။”')
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','၂။ (လျှာ)ခေါက်သည်။')
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','ခၠအ်လဝ်လတာ် = လျှာကိုခေါက်ထားသည်။')
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','၃။ ကော့သည်။')
,(2818,3,1,'ဖက်ရွက်စသည်ဖြင့် လုပ်ထားသောအထုပ်။','“ခၞာကွာၚ်က ကွာၚ်ကတအ်ဂှ် ဒးကၠေၚ်ဂမ္တဴတုဲ ခၠအ်တိုန်အိုတ်ရ။” = “ငါးမုန့်ကြော်ရာတွင် ငါးမုန့်တို့သည် ဆီပူထိ၍ ကော့လာကုန်သည်။”')
,(2819,3,4,'ကော့လန်သည်။',null)
,(2820,3,4,'လက်အုပ်ချီသည်။',null)
,(2821,3,4,'လက်ခုပ်လုပ်သည်။','(န) လက်ခုပ်။')
,(2822,3,1,'နှာဖု။ နှာခေါင်းဖု။ (ပါဠိ—နာသပုဋ)',null)
,(2823,3,4,'လက်အုပ်ချီသည်။',null)
,(2824,3,1,'ထန်းရွက်တံပိုး။ (လေမှုတ်ကိရိယာ)',null)
,(2825,3,1,'၁။ ရွာသူကြီး။','‘တၠခွါ’ ရှု။')
,(2825,3,1,'၁။ ရွာသူကြီး။','၂။ နောက်လိုက်။ နောက်ပါ။')
,(2826,3,1,'ဗျပ်။ ဘန်း။','(ကြိ) လက်ဖြင့်ဆွဲ၍သယ်ဆောင်သည်။')
,(2826,3,1,'ဗျပ်။ ဘန်း။','“(သမ္ၚေဟ်ဂှ်) ဂိုၚ်ကေတ်ဍာ် သာဲ တၚ်လာဲ သီုပ္ကဴမြမောဝ် သီုယာတ်ခွက်တုဲ တိတ်အာဘာဇေတဝန်ရ။” (ဇ—၁၇၁။ အစွောံ။) = “ထိုသူကြွယ်သည် ပျားရည် တၚ်လဲ ပန်း အမွှေးနံ့သာတို့ကို ယူဆောင်၍ အဝတ်ကိုပါ လက်ဖြင့်ဆွဲလျက် သယ်ယူပြီးလျှင် ဇေတဝန်ကျောင်းတော်သို့ ထွက်ခွာသွား၏။”')
,(2827,3,1,'ရေဗူး။ (ဝအတရြ်ေအရ)','“(ထေရ််ဂှ်) ပ္ဍဲဋ္ဌာန်ဘာမွဲဂှ် စွံလဝ်ဒၞပ်၊ ပ္ဍဲဋ္ဌာန်ဘာမွဲဂှ် စွံလဝ်ဒ စုန်၊ ပ္ဍဲဋ္ဌာန်ဘာမွဲဂှ် စွံလဝ်ခွက်ဍာ်၊ ပ္ဍဲဋ္ဌာန်ဘာမွဲဂှ် ဇကုပဒတဴရ။”(ဇ—၂၉၆။ အစွောံ။) = “(ထို ရဟန်းကြီးသည်) တခုသောကျောင်း­ ဘိနပ်ကိုထား၏။ တခုသောကျောင်း­ တောင်ဝှေးကိုထား ၏။ တခုသောကျောင်း­ ရေဗူးကိုထား၏။ တခုသောကျောင်း­ မိမိနေ၏။” (ညောင်ကန်)')
,(2828,3,4,'ခြစ်သည်။','ခွါတ်သတ်ဗြဴ = အုန်းသီးခြစ်သည်။')
,(2829,3,4,'လှီးဖဲ့သည်။',null)
,